/* ÇEVİRİ nl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("nl","olay",{
"OLAYLAR_EK16:1503-04-02:0":{"b": ["Wapenstilstand tussen Moskou en Litouwen — de regio Tsjernihiv-Severia ging naar Moskou", "8e4c56f9"], "d": ["De Moskovisch-Litouwse oorlog van 1500-1503 eindigde met een zesjarige wapenstilstand, tot stand gekomen door bemiddeling van Vladislav II, koning van Hongarije-Bohemen; het Groothertogdom Litouwen moest een uitgestrekt gebied, ongeveer een derde van het Groothertogdom, aan het Groothertogdom Moskou laten, waaronder de regio Tsjernihiv-Severia (omgeving van Tsjernihiv, Novhorod-Siverskyi, Starodoeb en Brjansk) en enkele gebieden rond Smolensk en Polotsk. Dit was een van de grootste afzonderlijke winsten van Moskou in het proces van het 'verzamelen' van Russische gronden.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Sjajbani Khan nam Herat en Khorasan van de Timuriden", "a81d8575"], "d": ["Volgens het lemma Şeybani Han van de TDV nam de Oezbeekse heerser Sjajbani Khan, nadat hij tussen 1503 en 1505 Andijan, Fergana, Hisar, Kunduz en Balkh had ingenomen, in 913 (1507) ook de Timuridische hoofdstad Herat in; het lemma Khorasan van de Encyclopaedia Iranica geeft de exacte datum van deze verovering — de stad viel op 8 Muharram 913 (20 mei 1507) en een week later, op 15 Muharram (27 mei), werd de khutba op naam van Sjajbani Khan gelezen en werd de verovering officieel. Heel Khorasan, inclusief Mashhad, ging in hetzelfde jaar van de Timuriden over naar de Sjajbaniden; dit betekende dat de Timuridische dynastie na Transoxanië ook haar laatste grote bolwerk in Iran verloor.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Val van Oran aan Spanje — de Noord-Afrikaanse veldtocht van kardinaal Cisneros", "86ed8ac1"], "d": ["Wahran (Oran), dat de zeeroute van de westelijke Middellandse Zee controleerde en de haven van Tlemcen was, was gegroeid door de toevlucht van Andalusische moslims en joden die in 1492 uit Granada waren gevlucht. Het Koninkrijk Castilië, dat aan het begin van de 16e eeuw de havensteden aan de Maghrebijnse kust een voor een innam, bezette Wahran op 17 mei 1509; het grootste deel van de bevolking werd afgeslacht, de overigen werden gevangengenomen en er bleef geen moslim- of joodse bevolking in de stad. De Spanjaarden breidden de muren en forten uit; Wahran bleef tot 1708 in Spaanse handen.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["Smolensk gaf zich over aan Moskou — Vasili III trok de stad binnen", "46c61446"], "d": ["Bij het derde beleg van de Moskovisch-Litouwse oorlog van 1512-1522 gaf het Litouwse garnizoen zich op 31 juli over; het Moskovische leger trok op 1 augustus plechtig de stad binnen en de bevolking zwoer trouw aan Vasili III. Smolensk is Vasili's grootste verwerving in het westen; de nederlaag bij Orsja enkele weken later zorgde er niet voor dat de stad werd teruggenomen.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["De Lage Landen verbonden aan de Spaanse kroon — dood van Ferdinand, troonsbestijging van Karel V", "fbe0dbd2"], "d": ["Met de dood van Ferdinand II van Aragón op 23 januari 1516 werd zijn kleinzoon Karel V, die sinds 1506 als hertog van Bourgondië al de Lage Landen (het huidige België-Nederland-Luxemburg en een deel van Noord-Frankrijk) bestuurde, ook erfgenaam van de tronen van Castilië en Aragón en op 14 maart 1516 in Brussel tot koning van Spanje uitgeroepen. Zo werden deze gebieden via personele unie niet langer beschouwd als verbonden aan de Duits/Oostenrijkse tak van het Huis Habsburg maar rechtstreeks aan de Spaanse kroon — met de verkiezing van Karel V tot Rooms keizer in 1519 zouden deze twee identiteiten (koning van Spanje en Duits-Rooms keizer) in dezelfde persoon verenigd worden, en de verbondenheid van de regio met Spanje zou duren tot 1556, toen Karel V aftrad en zijn erfenis aan zijn zoon Filips II overliet.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Het sultanaat Demak vernietigde Majapahit en kreeg de heerschappij over de kust van Java", "7da602b5"], "d": ["Volgens het lemma Demak van de TDV werd het sultanaat Demak, de eerste onafhankelijke moslimstaat van Java, in het laatste kwart van de 15e eeuw gesticht door Raden Patah; volgens Javaanse bronnen verdween het aflopende hindoeïstisch-boeddhistische koninkrijk Majapahit door de aanvallen van Demak. In 1527 veroverde Demak Tuban, dat in Chinese bronnen sinds de 11e eeuw als belangrijke haven voor de heersers van Majapahit wordt genoemd — dit is het jaar waarin ook de laatste resten van Majapahit aan Demak werden gebonden en het keerpunt in het proces van islamisering van het grootste deel van Java.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["Noorwegen teruggebracht tot een aan de Deense kroon gebonden provincie", "8e2f274e"], "d": ["De Deense koning Christiaan III verklaarde in zijn kroningscharter (håndfæstning) van 1536 dat Noorwegen niet langer als een afzonderlijk koninkrijk zou gelden maar als een provincie van Denemarken zou worden bestuurd en dat de Noorse Staatsraad (riksråd) werd opgeheven; dit besluit werd in 1537 feitelijk met de toepassing van de Deense kerkordening ook op Noorwegen en het verzet van de Schots-Noorse bisschop Olav Engelbriktsson werd gebroken. Hoewel Noorwegen in de praktijk nog enige tijd zijn eigen wetten en instellingen behield, was zijn politieke status niet langer die van een onafhankelijk koninkrijk maar van een aan de Deense kroon gebonden provincie — dit zou tot 1814 duren.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["Narva door de Russen ingenomen — de eerste grote stad van de Livonische Oorlog", "c21130d7"], "d": ["De legers van Ivan IV namen Narva in; Rusland bereikte de Oostzeekust. Narva bleef tot 1581, toen het naar Zweden ging, in Russische handen.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["Dorpat (Tartu) door de Russen ingenomen", "f941a504"], "d": ["De Russische legers namen in de zomerveldtocht van 1558 Dorpat (Tartu) en de omliggende forten in; de stad bleef tot de Wapenstilstand van Jam Zapolski in 1582 onder Russisch bestuur.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["Reval (Tallinn) kwam onder bescherming van Zweden — Noord-Estland ging naar Zweden", "3c183267"], "d": ["Terwijl de Livonische Confederatie uiteenviel, bood de stadsraad van Reval in 1561 trouw aan de Zweedse koning Erik XIV aan; Noord-Estland bleef tot de Grote Noordse Oorlog (1721) bij Zweden.", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Verdrag van Vilnius — het Livonische Confederatie viel uiteen, Koerland en Livonië aan Polen-Litouwen gebonden (behalve de stad Riga)", "d1ceaad5"], "d": ["Gotthard Kettler, de laatste grootmeester van de Livonische Confederatie, die onder Russische druk tijdens de Livonische Oorlog uiteenviel, plaatste zich met het op 28 november 1561 in Vilnius ondertekende verdrag (Pacta Subiectionis) onder de bescherming van Sigismund II August, groothertog van Litouwen en koning van Polen; het grootste deel van Livonië, met uitzondering van de stad Riga, werd aan Polen-Litouwen gebonden, terwijl Kettler de eerste hertog van het Hertogdom Koerland werd. Dit was het laatste bedrijf van de Livonische Ridderorde in de overgang van de Middeleeuwen naar de Nieuwe Tijd.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["Zweden nam Narva van Rusland", "5a7f7a6a"], "d": ["In de laatste jaren van de Livonische Oorlog namen Zweedse troepen Narva, dat sinds 1558 in Russische handen was; de stad bleef tot 1704 Zweeds.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["De vrije stad Riga werd aan Polen-Litouwen gebonden", "77dba329"], "d": ["Riga, dat tijdens de Livonische Oorlog een vrije stad was gebleven, werd in 1581 aan het Pools-Litouwse Gemenebest gebonden; de stad bleef bij het Gemenebest tot zij in 1621 naar Zweden ging.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Plakkaat van Verlatinghe — Nederland riep zijn onafhankelijkheid van Spanje uit", "a632aaee"], "d": ["Tijdens de Tachtigjarige Oorlog verklaarden de Staten-Generaal van de Nederlandse provincies die bij de Unie van Utrecht hoorden met het op 26 juli 1581 aangenomen Plakkaat van Verlatinghe koning Filips II van Spanje 'tiran' en wezen zij trouw aan hem af; dit document wordt beschouwd als de oprichtingsverklaring van de feitelijk onafhankelijke Verenigde Provinciën (Republiek der Nederlanden). De definitieve erkenning door Spanje zou wachten op Westfalen in 1648, maar de feitelijke breuk is deze dag.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Val van Smolensk aan Polen-Litouwen — einde van het 20 maanden durende beleg", "4e9678e3"], "d": ["Tijdens de Tijd der Troebelen (Smuta) sloeg het leger van de Poolse koning Sigismund III op 13 juni 1611 met een mijnontploffing een bres in de muren van Smolensk, dat het sinds september 1609 belegerde, en nam de stad in; het 20 maanden durende verzet eindigde. Smolensk bleef tot 1654 bij Polen-Litouwen en deze val bereidde de basis voor de zeven jaar later te ondertekenen Wapenstilstand van Deulino (1618).", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["Novgorod door het Zweedse leger ingenomen — Noordwest-Rusland kwam in de Tijd der Troebelen onder Zweedse controle", "a8ab28bb"], "d": ["Het Zweedse leger van Jacob De la Gardie nam Novgorod in; de stad werd tot 1617 de hoofdstad van de onder Zweedse bescherming staande 'Novgorodse Staat', Karel Filips werd als kandidaat-tsaar naar voren geschoven.", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["Verdrag van Stolbovo — Rusland verloor de Baltische kust (Ingermanland) aan Zweden", "175dc175"], "d": ["Het Verdrag van Stolbovo, dat de Ingermanlandse Oorlog beëindigde, werd op 27 februari 1617 ondertekend in het dorp Stolbovo ten zuiden van het Ladogameer; terwijl Rusland Novgorod en de andere noordelijke gebieden terugkreeg, hield Zweden Karelië en Ingermanland (tussen Estland en Finland, inclusief de forten Ivangorod, Jam, Koporje en Oreshek) in handen en werd Ruslands directe kust aan de Oostzee afgesneden. Deze onderbreking zou duren tot Peter de Grote in 1703 in hetzelfde gebied Sint-Petersburg stichtte.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["Verdrag van Stolbovo — Rusland liet Ingermanland aan Zweden, Novgorod teruggegeven", "e0bcbc7a"], "d": ["Rusland liet de oevers van de Neva en een deel van Karelië (Jam, Koporje, Ivangorod, Orešek) aan Zweden en werd van de Oostzeekust afgesneden; Zweden gaf Novgorod terug. Deze toestand duurde tot de Grote Noordse Oorlog van Peter I.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Wapenstilstand van Deulino — Smolensk, Tsjernihiv en Novhorod-Siverskyi aan Polen overgelaten", "6880d2c1"], "d": ["De Wapenstilstand van Deulino, die de Pools-Russische oorlog van 1609-1618 beëindigde, werd op 11 december 1618 ondertekend en verschafte een wapenstilstand van 14,5 jaar; Rusland moest Smolensk (met uitzondering van Vjazma) en 29 steden in de regio's Tsjernihiv en Novhorod-Siverskyi aan het Pools-Litouwse Gemenebest laten — dit was het zwaarste gebiedsverlies van de Tijd der Troebelen (Smuta). De regio zou tot de Wapenstilstand van Andrusovo van 1667 bij Polen blijven.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["Zweden nam Tartu (Dorpat) van Polen — de tweede fase van de Livonische veldtocht", "46b7c86a"], "d": ["Gustaaf II Adolf veroverde in de veldtocht van 1625 Zuid-Estland en Noord-Livonië; Tartu werd een Zweedse stad waar in 1632 de Academia Gustaviana zou worden gesticht.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Raad van Perejaslav — de Zaporozje-kozakken zwoeren trouw aan de Russische tsaar", "bcd8f8ef"], "d": ["Bohdan Chmelnytsky, hetman van de Zaporozje-kozakken, die sinds 1648 in opstand was tegen Polen-Litouwen, zwoer op de Raad van Perejaslav van 18 januari 1654 (Juliaans 8 januari), waaraan een delegatie uit Moskou onder leiding van Vasili Boetoerlin deelnam, trouw aan tsaar Alexis I Michajlovitsj; dit wordt beschouwd als het begin van de plaatsing van het Oekraïense Kozakken-Hetmanaat onder Russische bescherming en verschoof de feitelijke controle over de regio Tsjernihiv-Severia van Polen naar Rusland — de officiële grens zou met de Wapenstilstand van Andrusovo van 1667 worden getrokken.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Herovering van Smolensk door Rusland", "bf0eca92"], "d": ["Tijdens de in 1654 begonnen Pools-Russische oorlog heroverde het Russische leger Smolensk, dat het sinds juli belegerde, op 3 oktober 1654 toen het Poolse garnizoen zich overgaf; de stad, die in 1611 aan Polen was verloren, keerde na 43 jaar terug naar Rusland. Dit was een van de belangrijkste stappen in het proces waarin Rusland de verliezen van de Tijd der Troebelen ongedaan maakte en werd blijvend met de Wapenstilstand van Andrusovo van 1667.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Wapenstilstand van Andrusovo — Kiev en Linkeroever-Oekraïne gingen naar Rusland", "799be067"], "d": ["De Wapenstilstand van Andrusovo, die de Pools-Russische oorlog van 1654-1667 beëindigde, verschafte een wapenstilstand van 13,5 jaar; Rusland won Smolensk, de regio Tsjernihiv-Severia en Oekraïne aan de linkeroever van de Dnjepr en — aanvankelijk voor twee jaar, feitelijk blijvend — de stad Kiev. Dit verdrag legde de juridische grondslag voor de deling van het Oekraïense grondgebied langs de Dnjepr tussen Polen en Rusland (en voor het feit dat Kiev bij Rusland bleef).", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["Rusland nam Nöteborg (Orešek) van Zweden — het eerste Neva-fort van de Grote Noordse Oorlog", "28d180eb"], "d": ["De legers van Peter I belegerden en namen Nöteborg (in het Russisch Orešek) aan de uitgang van het Ladogameer in en noemden het Sjlisselburg ('Sleutelfort'); dit opende de weg naar de Neva en naar de stichting van Sint-Petersburg in 1703.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Stichting van Sint-Petersburg — Ruslands venster op het Westen", "ba196be0"], "d": ["Tijdens de Grote Noordse Oorlog legde Peter de Grote op 16/27 mei 1703 op Hazeneiland in de pas op Zweden heroverde Nevadelta de fundering van de Petrus-en-Paulusvesting (Peter-Pavel-vesting); deze dag wordt beschouwd als de stichtingsdatum van de stad Sint-Petersburg. Peter ontwierp de moerassige delta als een 'venster' naar het Westen en de stad werd in 1712 de nieuwe hoofdstad van Rusland — het gebied zou officieel met het Verdrag van Nystad van 1721 aan Rusland worden gebonden.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["Menorca veroverd door Engels-Nederlandse troepen", "3ca66a83"], "d": ["Tijdens de Spaanse Successieoorlog gingen de Engels-Nederlandse troepen, die optraden als bondgenoot van de Oostenrijkse aartshertog Karel VI, onder bevel van generaal James Stanhope op 14 september 1708 op het eiland aan land en brachten op 28-29 september de Spaanse verdediging ten val en namen de controle over Menorca over (de officiële overgave van het hoofdfort Fort St. Philip duurde tot 24 november). De strategische haven van Menorca, Mahón, zou in de daaropvolgende eeuw het brandpunt van de Engels-Frans-Spaanse strijd zijn.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Verdrag van Rastatt — de Spaanse Successieoorlog eindigde, de Spaanse Nederlanden en Milaan gingen naar Oostenrijk", "3c0e086f"], "d": ["Het Verdrag van Rastatt, dat de Spaanse Successieoorlog tussen Frankrijk en Oostenrijk beëindigde, werd op 7 maart 1714 ondertekend (Utrecht had in 1713 de verhouding tussen Engeland en Frankrijk geregeld); met het verdrag namen de Oostenrijkse Habsburgers de Spaanse Nederlanden (het huidige België) en in Italië Napels, Milaan en Sardinië over. Dit was de grootste gebiedsuitbreiding in de geschiedenis van Oostenrijk en voegde aan het gewicht van de Habsburgse dynastie in Midden-Europa een nieuw front in West- en Zuid-Europa toe.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Verdrag van Nystad — de Grote Noordse Oorlog eindigde, de Baltische kusten gingen naar Rusland", "068ffd06"], "d": ["Het Verdrag van Nystad, dat de 21 jaar durende Grote Noordse Oorlog beëindigde, werd op 10 september 1721 (Juliaans 30 augustus) in Finland ondertekend; Zweden liet Estland, Livonië (inclusief Riga), Ingermanland en een deel van Zuidoost-Finland (Karelië) aan Rusland, kreeg daarentegen de rest van Finland terug en er werd een schadevergoeding betaald. Het verdrag wordt beschouwd als het einde van de grootmachtstatus van Zweden en de officiële registratie van de opkomst van Rusland als Europees keizerrijk — Peter I nam na deze overwinning de titel 'Keizer' aan.", "f0c4fc4a"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["Eerste Poolse Deling — gebiedsverlies aan Rusland en Oostenrijk", "2c56a0d8"], "d": ["Met het op 5 augustus 1772 tussen Rusland, Pruisen en Oostenrijk ondertekende verdrag werd ongeveer een derde van het gebied van het Pools-Litouwse Gemenebest verdeeld: Rusland nam een deel van het huidige Wit-Rusland en Letland (inclusief Daugavpils, Polotsk en Vitebsk), Oostenrijk annexeerde Galicië (Lemberg en West-Podolië, inclusief Jazłowiec); Pruisen nam het kustgebied Koninklijk Pruisen over. De Poolse Sejm bekrachtigde het verdrag pas op 30 september 1773, onder druk. Dit was de eerste van de drie delingen die tot 1795 zouden duren.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Tweede Poolse Deling — gebiedsverlies aan Rusland en Pruisen", "31750484"], "d": ["Doordat de grondwetshervormingen van 1791 Rusland en Pruisen verontrustten, verdeelden de twee staten Polen opnieuw met het op 23 januari 1793 in Sint-Petersburg ondertekende verdrag: Rusland nam het grootste deel van Litouwen-Wit-Rusland en West-Oekraïne (inclusief Kamenets, Bar en Minsk), Pruisen annexeerde Groot-Polen met Gdańsk en Poznań — in totaal 307.000 km². De onder druk staande Poolse Sejm moest het verdrag in hetzelfde jaar bekrachtigen; dit was een kortstondige deling die de volledige annexatie van Polen twee jaar uitstelde. Op deze dag (23 januari 1793) ging in de Tweede Deling van Polen Rechteroever-Oekraïne, inclusief Berdytsjiv, Fastiv, Zjytomyr, Kaniv, Kostjantyniv, Oeman en Tsjerkasy, over naar Rusland.", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["Het Hertogdom Koerland en Semgallen bij Rusland gevoegd — de laatste hertog Peter von Biron deed afstand", "8d0e410f"], "d": ["In het proces van de Derde Poolse Deling boden de Koerlandse edelen Catharina hun trouw aan en deed hertog Peter von Biron afstand van de troon; Koerland werd een gouvernement van Rusland (in de bronnen komt ook 24 oktober 1795 voor).", "4682774b"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["Derde Poolse Deling — volledig verdwijnen van de staat", "e3c02d6b"], "d": ["Rusland, Pruisen en Oostenrijk verdeelden met het op 24 oktober 1795 in Sint-Petersburg ondertekende drievoudige verdrag de resterende gebieden van het Pools-Litouwse Gemenebest volledig: Rusland nam Litouwen (inclusief Vilnius en Kaunas) en de rest van Wit-Rusland, Pruisen het centrale Polen inclusief Warschau en Oostenrijk annexeerde het zuidelijke gebied inclusief Krakau. De drie staten garandeerden bovendien militair elkaars nieuwe gebieden en namen maatregelen tegen de mogelijkheid van een herstel van Polen. Dit is het volledige verdwijnen van de Pools-Litouwse staat als onafhankelijk land; tot de 20e eeuw zou hij niet worden hersteld.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["Einde van de Republiek Venetië — de Grote Raad ontbond zichzelf", "5efed589"], "d": ["Toen het leger van Napoleons Italiaanse veldtocht het Venetiaanse grondgebied bezette en de republiek een ultimatum stelde, stemde de Grote Raad (Maggior Consiglio) op 12 mei 1797 met 512 tegen 20 stemmen in met zijn eigen ontbinding; de laatste doge Ludovico Manin trad af en het aristocratische bestuur van de Republiek Venetië, die meer dan 1.100 jaar onafgebroken had bestaan, kwam ten einde. Haar gebieden werden eerst onder een voorlopig democratisch bestuur geplaatst en daarna met het Verdrag van Campo Formio in oktober 1797 officieel aan Oostenrijk overgelaten.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Einde van de Republiek Genua — Napoleon stichtte de Ligurische Republiek", "3d3e59ee"], "d": ["In de plaats van de Republiek Genua, die onder druk van Napoleon in de Italiaanse veldtocht begin juni 1797 aan een voorlopig bestuur was overgedragen, werd op 14 juni 1797 met een grondwet naar Frans model de 'Ligurische Republiek' uitgeroepen; het eeuwenoude Genuese dogaat veranderde feitelijk in een van de satellietstaten van Frankrijk. De republiek zou in 1805 rechtstreeks bij Frankrijk worden geannexeerd en met het Congres van Wenen in 1815 aan het Koninkrijk Sardinië-Piëmont worden overgelaten.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Verdrag van Campo Formio — Venetië verdeeld tussen Oostenrijk en Frankrijk", "9f29678c"], "d": ["Het Verdrag van Campo Formio, op 17 oktober 1797 ondertekend tussen Napoleon Bonaparte en de Oostenrijkse vertegenwoordiger graaf Cobenzl, schafte de duizendjarige Republiek Venetië officieel af en verdeelde haar gebieden: het gebied ten oosten van de Adige, Istrië en de kust van Dalmatië (inclusief Split, Zadar, Šibenik en Kotor) werden aan Oostenrijk gelaten, de Ionische Eilanden (Korfoe, Kefalonia, Zakynthos, Lefkas, Preveza en de Venetiaanse bases aan de Albanees-Moreaanse kust, waaronder Parga) gingen naar Frankrijk. Oostenrijk liet bovendien zijn gebieden in de Lage Landen (het huidige België) aan Frankrijk.", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Overgave van Malta aan Engeland — einde van de twee jaar durende Franse belegering", "fedc2867"], "d": ["Malta, dat Napoleon in 1798 op weg naar de Egyptische veldtocht had ingenomen, kwam kort daarna door een opstand van de eilandbevolking onder zeeblokkade van de Engelse vloot; na twee jaar beleg en honger gaf de Franse commandant generaal Vaubois zich op 5 september 1800 over aan de Engelse generaal Pigot. Malta ging zo van de Franse Republiek over onder Engelse bescherming en zou met het Verdrag van Parijs van 1814 officieel aan de Engelse kroon worden gebonden — het werd de belangrijkste Britse marinebasis in de Middellandse Zee.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Vrede van Amiens — Menorca aan Spanje teruggegeven", "f341e4b8"], "d": ["De Vrede van Amiens (25 maart 1802), ondertekend tussen Frankrijk, Spanje, Nederland en Engeland, beëindigde tijdelijk de Tweede Coalitieoorlog; Engeland gaf bijna alle tijdens de oorlog veroverde gebieden terug (met uitzondering van Ceylon en Trinidad) — een daarvan was Menorca, dat in 1798 aan Spanje was ontnomen. De vrede duurde slechts een jaar, in mei 1803 brak de oorlog opnieuw uit, maar Menorca kwam na dit verdrag niet meer in Engelse handen.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Verdrag van Fredrikshamn (Hamina) — Zweden liet Finland aan Rusland", "c0d407bc"], "d": ["Het Verdrag van Fredrikshamn (het huidige Hamina), dat de Russisch-Zweedse oorlog van 1808-1809 beëindigde, werd op 17 september 1809 ondertekend; Zweden liet heel Finland, inclusief de Åland-eilanden, aan Rusland. Finland kreeg de status van een Groothertogdom met uitgebreide autonomie onder het Russische Keizerrijk en behield het lutherse geloof en het Zweedse recht. Dit betekende het feitelijke einde van de status van Zweden als grote mogendheid in de Oostzee. Met dit verdrag gingen zes provincies van Finland en Västerbotten tot aan de rivier Torne (Kokkola, Joensuu, Savonlinna, Tornio, Rovaniemi, Inari enz.) over naar het aan Rusland gebonden Groothertogdom Finland.", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["Annexatie van het Koninkrijk Imereti — koning Salomo II van de troon gezet", "5ad36bff"], "d": ["Salomo II, de laatste koning van het West-Georgische Koninkrijk Imereti, dat in 1804 met het Verdrag van Elaznauri het Russische vazalschap had moeten aanvaarden, bleef de toenemende Russische druk weerstaan; daarom namen Russische troepen op 20 februari 1810 de hoofdstad Koetaisi in, zetten Salomo van de troon en dwongen de lokale edelen trouw te zweren aan tsaar Alexander I; het Koninkrijk Imereti kwam zo feitelijk ten einde en werd rechtstreeks onder Russisch bestuur gebracht. Salomo vluchtte naar Ottomaans grondgebied en stierf in ballingschap (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Verdrag van Kiel — Denemarken liet Noorwegen aan Zweden", "59ab1601"], "d": ["Zweden, dat na de nederlaag van Napoleon bij Leipzig Denemarken vanuit het zuiden aanviel, nam met het op 14 januari 1814 ondertekende Verdrag van Kiel Noorwegen over (met uitzondering van IJsland, de Faeröer en Groenland) — de Deens-Noorse unie die sinds 1380 had bestaan kwam zo officieel ten einde. In ruil liet Zweden zijn gebieden in Pommeren aan Denemarken; Denemarken droeg bovendien Helgoland aan Engeland over. Noorwegen verzette zich met wapens tegen het verdrag en riep zijn eigen grondwet uit, en Zweden moest dit erkennen — het resultaat werd een personele unie (real union) die tot 1905 zou duren. Zweden kon Noorwegen feitelijk niet overnemen: het verdrag werd in Noorwegen niet aanvaard en het bestuur bleef bij Christian Frederik; het Zweedse leger trok pas op 26 juli 1814 Noorwegen binnen.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Slotakte van het Congres van Wenen — de kaart van Europa na Napoleon werd opnieuw getrokken", "fca1c676"], "d": ["De Slotakte van het Congres van Wenen, ondertekend tussen de grote mogendheden (Oostenrijk, Rusland, Pruisen, Engeland, Frankrijk) die de Napoleontische oorlogen beëindigden, werd op 9 juni 1815 (9 dagen vóór Waterloo) aangenomen en trok de kaart van het continent gezamenlijk opnieuw: de voormalige Spaanse/Oostenrijkse Nederlanden en de Verenigde Provinciën werden verenigd onder het 'Verenigd Koninkrijk der Nederlanden', de Republiek Genua werd bij het Koninkrijk Sardinië-Piëmont gevoegd, het grootste deel van het Hertogdom Warschau werd onder de naam 'Congres-Polen' aan Rusland gebonden en Zweeds Pommeren (Stralsund) ging naar Pruisen. Deze ene dag wordt beschouwd als het officiële begin van het naoorlogse Europese evenwicht (Concert of Europe). Met deze akte gingen Łódź, Częstochowa, Kielce, Radom, Lublin, Chełm en Zamość (Hertogdom Warschau) naar het aan Rusland gebonden Koninkrijk Polen, Poznań (Groothertogdom Posen) naar Pruisen, Maastricht en Roermond naar het Koninkrijk der Nederlanden.", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Algemeen Zeeverdrag — de Qawasim en andere sjeikdommen van de Golf werden door verdrag aan Engeland gebonden", "fc499e19"], "d": ["Nadat Engeland in 1819 Ras al-Khaimah had gebombardeerd en de 'piraten'-vloot van de Qawasim had verstrooid, legde het het Algemeen Zeeverdrag op, dat op 8 januari 1820 begon en met de sjeikdommen van de regio een voor een werd ondertekend en in maart voltooid was; het verdrag verbood piraterij en slavernij en maakte het verplicht dat schepen een rood-witte vlag voerden die op de Engelse vlag leek. Met dit verdrag veranderde de 'Piratenkust' na verloop van tijd in de 'Bestandskust' (Trucial Coast); de Britse hegemonie, die werd verdiept met het permanente zeebestand van 1853 en de exclusieve verdragen van 1892, was het begin van een relatie die tot 1971 zou duren.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Einde van het beleg van Gaeta — ineenstorting van het Koninkrijk der Beide Siciliën", "121ae580"], "d": ["Na de ineenstorting die begon met de landing van Garibaldi op Sicilië in mei 1860, werd de Bourbonkoning Frans II, die uit Napels was gevlucht, vanaf 3 november 1860 in zijn laatste fort Gaeta belegerd; toen de Franse vloot zich in januari 1861 uit de regio terugtrok, werd de Italiaanse zeeblokkade aangescherpt en op 13 februari 1861 gaf Gaeta zich over. Frans II verliet zijn troon en ging in ballingschap; het laatste verzetspunt van het Koninkrijk der Beide Siciliën, Civitella del Tronto, zou pas op 20 maart 1861 vallen. Met de ineenstorting van het koninkrijk stonden de gebieden op Sicilië (Palermo, Messina, Syracuse, Trapani, Misilmeri) en in Campanië (inclusief Nola) niet langer onder Bourbonbestuur.", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Uitroeping van het Koninkrijk Italië — eenwording van Sardinië, Toscane en Zuid-Italië", "12e52f70"], "d": ["In de eerste zitting van het Italiaanse parlement in Turijn werd op 17 maart 1861 het Koninkrijk Italië officieel uitgeroepen en koning Victor Emanuel II van Sardinië-Piëmont werd de eerste koning van het verenigde Italië. Het nieuwe koninkrijk verenigde de in het voorgaande jaar bij volksstemmingen aangesloten gebieden Toscane, Emilia-Romagna, Napels en Sicilië (de Beide Siciliën) met het Koninkrijk Sardinië; Rome (de Kerkelijke Staat) en Venetië (Oostenrijk) bleven er nog buiten — zij zouden zich respectievelijk in 1870 en 1866 aansluiten.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["Val van Jizzakh aan Rusland — het laatste fort van het emiraat Boechara aan de Syr Darja-lijn", "21205a6e"], "d": ["Tijdens de Russische opmars in Centraal-Azië, na de mislukte poging van generaal Tsjernjajev in februari 1866, namen de Russische troepen onder bevel van de in zijn plaats benoemde generaal Dmitri Romanovski in oktober 1866 na een zeven dagen durend beleg en een felle aanval Jizzakh in, het laatste grote fort van het emiraat Boechara in de Syr Darja-vallei; deze val maakte feitelijk een einde aan het Boecharaanse verzet in de regio en opende de weg van het Russische leger naar Samarkand.", "b95ba993"]},
"OLAYLAR_EK16:1868-05-14:0":{"b": ["Het Russische leger nam Samarkand in — de stad ging van het emiraat Boechara naar het gouvernement-generaal Turkestan", "321473be"], "d": ["Russische troepen namen Samarkand, dat in handen van het emiraat Boechara was, in en voegden de stad bij het gouvernement-generaal Turkestan. Samarkand was in de tijd van de Oezbeekse khans een stad in de schaduw van Boechara geweest; met het Russische bestuur werd het een nieuwe halte van de Russische opmars in Centraal-Azië.", "3bc56bbe"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["Overgave van Straatsburg: Duitse troepen bezetten de stad", "ef3281f3"], "d": ["Na een zes weken durend beleg en bombardement ondertekende generaal Uhrich 's nachts in Koenigshoffen de capitulatie; 's ochtends werden de poorten en de Citadel aan Pruisische en Badense troepen overgegeven. De stad bleef tot het Verdrag van Frankfurt (10 mei 1871) onder militaire bezetting.", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["Overgave van Metz: het leger van Bazaine legde de wapens neer, Duitse troepen namen het fort in", "8dd66f58"], "d": ["Het capitulatieprotocol van het omsingelde Rijnleger werd op de avond van 27 oktober ondertekend; op de ochtend van 29 oktober werden Pruisische vlaggen op de bastions gehesen en verlieten de Franse troepen het fort. Metz bleef tot het Verdrag van Frankfurt (10 mei 1871) onder militaire bezetting.", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["Overgang van Assab naar Italiaans staatseigendom — de basis van Italiës eerste kolonie", "15ab8732"], "d": ["De haven van Assab aan de Rode Zeekust was in 1869 door een particuliere Italiaanse scheepvaartmaatschappij (Rubattino) gekocht van lokale Afar-leiders; met de instemming van Engeland nam de Italiaanse regering op 10 maart 1882 het directe staatseigendom van de haven over en riep zij met een in juli uitgevaardigde wet Assab officieel uit tot Italiës eerste kolonie. Dit was het uitgangspunt van de Italiaanse expansie aan de Rode Zeekust die later zou veranderen in de Kolonie Eritrea (1890).", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["Vernietiging van het garnizoen van Sinkat — Sinkat ging naar de Mahdistische strijdkrachten", "e175a94e"], "d": ["Het garnizoen van Sinkat, dat al maandenlang door de strijdkrachten van Osman Digna werd belegerd en zonder voorraden zat, probeerde samen met zijn commandant Tevfik Bey het beleg te doorbreken en Suakin te bereiken; het werd op 8 februari 1884 buiten het fort vernietigd en Sinkat viel in handen van de Mahdistische strijdkrachten. Het nieuws bereikte Suakin op 12 februari.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["Staat van beleg in Suakin — de stad kwam onder Brits bevel", "801f6a81"], "d": ["Nadat de ontzettingsmacht van Baker voor Tokar op 4 februari bij El Teb een nederlaag had geleden, liet admiraal Hewett op 6 februari mariniers in Suakin aan land gaan. Op 9 februari 1884 werd in de stad de staat van beleg uitgeroepen en kregen Britse officieren volledige militaire en civiele bevoegdheid over de stad; de dag daarop werd de verantwoordelijkheid voor de stad officieel van Baker aan Hewett overgedragen.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["Overgave van Tokar aan de Mahdistische strijdkrachten", "0e21fd24"], "d": ["Het belegerde garnizoen van Tokar onderhandelde op 19 februari 1884 met de Mahdistische strijdkrachten en gaf de stad de dag erop, op 20 februari, over. Het nieuws bereikte op 24 februari de Britse troepen in Trinkitat; de ontzettingsoperatie van Graham kwam te laat.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["Groot-Brittannië vestigde een protectoraat aan de noordelijke Somalische kust — begin van Somaliland", "f301ea94"], "d": ["Volgens het lemma Somali van de TDV werden Zeila, Berbera en Tajura in 1884 door de Engelsen onder de naam Somaliland gekoloniseerd; volgens de standaard academische bron begon dit proces met het verdrag dat in Berbera op 21 Ramadan 1301 (14 juli 1884) met de Habar Awal-stam werd gesloten en breidde zich in 1884-1886 uit met soortgelijke verdragen met de stammen Gadabuursi, Habar Toljaala, Habar Garhajis, Issa en Warsangali; Engeland beloofde in ruil militaire bescherming. Deze keten van verdragen vormde de basis voor de uitroeping van het officiële Brits Somaliland Protectoraat in 1887.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Slag bij Mulayda — einde van de Tweede Saoedische Staat, Nadjd ging naar de Rashidi's", "1cd3b213"], "d": ["Na relaties die verslechterden door een zakat-geschil en de arrestatie van een Rashidi-gezant, bracht het leger van Muhammad ibn Rashid, emir van Jabal Shammar, op 21 januari 1891 bij Mulayda in de regio Qasim de Saoedische troepen onder leiding van Abd al-Rahman ibn Faysal en hun bondgenoten een zware nederlaag toe; dit was het feitelijke einde van de Tweede Saoedische Staat, de familie Al Saud ging in ballingschap naar Koeweit en heel Nadjd kwam onder Rashidi-heerschappij; ook de zuidelijke streken Dilam (Harj), Hawtat (Hawtat Bani Tamim) en Layla (Aflaj) behoorden daartoe. De heerschappij zou duren tot de herovering van Riyad door de jonge Abdulaziz ibn Saoed in 1902 (Overval op Riyad, 16 januari 1902).", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["Herovering van Tokar door Brits-Egyptische troepen — terugtocht van Osman Digna", "80a2c26a"], "d": ["Tokar aan de Rode Zeekust, dat sinds 1884 in handen was van Osman Digna, de plaatselijke commandant van de Mahdistische beweging, werd in februari 1891 door een operatie van Brits-Egyptische troepen heroverd; Osman Digna moest zich terugtrekken in de bergen. Dit was een grote slag voor de aanwezigheid van de Mahdistische staat aan de Rode Zeekust en de regio kwam onder gezamenlijk Brits-Egyptisch bestuur.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["Doortocht van de colonne van Grenfell door Sinkat — Sinkat kwam uit het Mahdistische bestuur en keerde terug onder Brits-Egyptisch bestuur", "b7539a44"], "d": ["Na de herovering van Tokar in februari 1891 vertrok de Brits-Egyptische colonne onder Grenfell op 3 maart 1891 vanuit Afafit via Sinkat en bereikte op 7 maart Suakin; de colonne vond het gebied, dat sinds 1884 niet meer was betreden, volledig verlaten door de vijand. Op 8 maart werd aan de in Suakin verzamelde sjeiks namens de khedive een algemene amnestie afgekondigd en Sinkat werd opnieuw onder Brits-Egyptisch bestuur geplaatst.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Italiaans Somaliland ging over op direct staatsbestuur — liquidatie van de Benadir-compagnie", "8c7d085b"], "d": ["Volgens het lemma Somali van de TDV had Italië zijn heerschappij over de zuidelijke Somalische kust (Benadir) in 1889-1891 gevestigd met overeenkomsten met het sultanaat Zanzibar en Engeland en het bestuur aanvankelijk overgelaten aan een bevoorrechte handelsmaatschappij (Benadir Company); volgens de standaard academische bron liep het privilege van deze maatschappij op 24 januari 1905 af en kocht de Italiaanse staat de directe soevereiniteit over de Benadirkust (inclusief Mogadishu, Merca en Brava) en vestigde officieel koloniaal bestuur. De feitelijke uitbreiding van de kolonie naar het binnenland (Bardera, Baidoa) zou met het oprichtingsdecreet van 1908 en in de daaropvolgende jaren worden voltooid.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Ontbinding van de Noors-Zweedse Unie — eenzijdige onafhankelijkheidsverklaring van de Storting", "aaba2935"], "d": ["Nadat koning Oscar II het verzoek van de Noorse regering om een afzonderlijk consulaat te vestigen had geveto'd en had verklaard dat hij geen nieuwe regering kon vormen, besloot de Noorse Storting (parlement) op 7 juni 1905 unaniem dat de koning feitelijk niet langer als koning van Noorwegen functioneerde en dat de sinds het Verdrag van Kiel van 1814 bestaande unie was ontbonden. In het referendum van 13 augustus 1905 keurden bijna alle kiezers (371.000 tegen 184 stemmen) de ontbinding goed; Zweden erkende de onafhankelijkheid officieel op 26 oktober 1905 na de besprekingen van Karlstad.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["Libau (Liepāja) door Duitse troepen ingenomen — begin van de bezetting van Koerland", "fdb10548"], "d": ["In het Duitse zomeroffensief van 1915 trok het leger Koerland binnen; Libau was de Russische marinebasis aan de Oostzeekust. Het grootste deel van Koerland kwam onder het bevel van Ober Ost (tot eind 1918).", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["Mitau (Jelgava) door Duitse troepen ingenomen", "eb491281"], "d": ["Mitau, de oude hertogelijke hoofdstad van Koerland, kwam onder Duitse controle; het front bij Riga bevroor aan de Daugava-lijn en bleef tot 1917 stilstaan.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["Het fort Kovno (Kaunas) door de Duitsers ingenomen — Litouwen kwam onder bezetting", "9849405b"], "d": ["Het Duitse 10e Leger nam Ruslands grootste fort aan de Memel in; het Litouwse gebied kwam onder het bestuur van Ober Ost en in 1918 riep de Taryba onder deze bezetting de onafhankelijkheid uit.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["Vilna (Vilnius) door Duitse troepen ingenomen", "2781858b"], "d": ["Tijdens de Grote Terugtocht ging Vilna naar de Duitse troepen en werd aan het Litouwse gebied van Ober Ost gebonden; de stad wisselde tot 1919 tussen Duitse, Sovjet- en Poolse troepen van hand.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["Brits-Qatarees verdrag — Qatar kwam onder Britse bescherming", "f61c4e49"], "d": ["Tijdens de Eerste Wereldoorlog stemde Qatar met het op 3 november 1916 ondertekende verdrag tussen majoor Percy Cox, de Britse politieke vertegenwoordiger in de Perzische Golf, en sjeik Abdullah bin Jassim Al Thani van Qatar ermee in zijn buitenlandse betrekkingen afhankelijk te maken van de goedkeuring van Engeland, in ruil waarvoor het Britse bescherming tegen zeeaanvallen kreeg gegarandeerd; dit verdrag vormde de juridische grondslag van de Britse beschermingsrelatie van Qatar die tot 1971 zou duren en werd officieel in 1918 bekrachtigd.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["Riga door het Duitse 8e Leger ingenomen", "df95df19"], "d": ["De Duitse troepen staken de Daugava over en namen Riga in; de stad bleef tot november 1918 onder Duitse controle, de Letse onafhankelijkheid werd onder deze bezetting uitgeroepen (18 november 1918).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["De Letse Volksraad riep de onafhankelijkheid uit", "fc72a7f7"], "d": ["De Letse Volksraad, bijeen in het Nationaal Theater in Riga, riep de van het Russische Keizerrijk onafhankelijke Republiek Letland uit; onder leiding van Kārlis Ulmanis werd een voorlopige regering gevormd. Enkele weken later (december 1918) viel Sovjet-Rusland aan en begon de Onafhankelijkheidsoorlog. Met deze uitroeping werden Riga, Jelgava, Liepāja, Ventspils, Cēsis, Daugavpils en Rēzekne beschouwd als grondgebied van de Republiek Letland.", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["Het Rode Leger trok Vilnius binnen — de Litouwse regering ontruimde de stad", "889a97b3"], "d": ["De Litouwse regering ontruimde Vilnius toen het Rode Leger naderde; Sovjettroepen trokken de stad binnen en in februari 1919 werd van hieruit de Litouws-Wit-Russische Sovjetrepubliek (Litbel) uitgeroepen. De stad zou in april 1919 door Poolse troepen worden ingenomen.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["Poolse troepen namen Vilnius (Wilno) van de Sovjets", "32d36c4a"], "d": ["De troepen van Józef Piłsudski namen in april 1919 Wilno van het Rode Leger; Litouwen bleef aanspraak maken op de stad en de Vilnius-kwestie vergiftigde de Litouws-Poolse betrekkingen in het interbellum.", "85e7c434"]},
"OLAYLAR_EK16:1920-10-12:0":{"b": ["Żeligowski riep Midden-Litouwen uit — Vilnius werd de hoofdstad van de door Polen gesteunde marionettenstaat", "11400510"], "d": ["Generaal Lucjan Żeligowski nam met zijn 'muiterij' Vilnius in en riep de Republiek Midden-Litouwen uit; de staat duurde tot 24 maart 1922.", "d8050fe5"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["Engeland hief het protectoraat over Egypte op en verklaarde Egypte onafhankelijk", "f8faab66"], "d": ["Engeland beëindigde met de verklaring van 28 februari 1922 eenzijdig het protectoraat dat sinds 1914 had bestaan en verklaarde Egypte een onafhankelijke staat; kwesties als defensie, verbindingswegen en Soedan werden voor Engeland voorbehouden. Twee weken na de verklaring (15 maart 1922) nam sultan Ahmed Fuad de titel koning aan. Op de kaart eindigt de laag van Engelse bezetting in de Egyptische steden op deze dag.", "8cde4005"]},
"OLAYLAR_EK16:1922-03-24:0":{"b": ["Midden-Litouwen bij Polen gevoegd — Vilnius werd Pools", "e929fa20"], "d": ["De Wilno-Sejm stemde op 20 februari 1922 voor aansluiting; de Poolse Sejm bekrachtigde dit op 24 maart 1922. De Conferentie van Ambassadeurs erkende de grens in 1923, Litouwen niet.", "4a067568"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["Litouwen aanvaardde het Duitse ultimatum — het Memelgebied aan Duitsland overgedragen", "149fb0b2"], "d": ["Op het ultimatum van Ribbentrop liet Litouwen het Klaipėda (Memel)-gebied aan Duitsland; Hitler trok op 23 maart Memel binnen. Het gebied werd op 28 januari 1945 door het Rode Leger ingenomen.", "75afd979"]},
"OLAYLAR_EK16:1939-09-19:0":{"b": ["Het Rode Leger bezette Vilnius", "5b25d037"], "d": ["Het Rode Leger, dat op 17 september Oost-Polen was binnengetrokken, trok in de nacht van 18-19 september Vilnius binnen, dat in Poolse handen was. Met het Sovjet-Litouwse wederzijdse bijstandspact van 10 oktober zou de stad aan Litouwen worden overgelaten en op 28 oktober zou het Litouwse leger binnentrekken.", "285aa71c"]},
"OLAYLAR_EK16:1939-10-28:0":{"b": ["Litouwen nam Vilnius over — de prijs van het Sovjet-Litouwse wederzijdse bijstandspact", "37ba5976"], "d": ["Vilnius, dat het Rode Leger op 19 september 1939 had ingenomen, werd met het wederzijdse bijstandspact van 10 oktober 1939 aan Litouwen overgelaten; het Litouwse leger trok op 28 oktober de stad binnen. In ruil vestigden Sovjetgarnizoenen zich in Litouwen en in 1940 volgde annexatie.", "60d2f2bf"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["Duitsland bezette Grodno", "b7ca9378"], "d": ["Oostfront: Barbarossa in 1941 en Bagration in 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["Duitsland bezette Brest-Litovsk", "25898c65"], "d": ["Oostfront: Barbarossa in 1941 en Bagration in 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["Pskov door het Duitse leger ingenomen — begin van de bezetting van Russische gebieden", "d9822e30"], "d": ["In de derde week van Barbarossa trok de Wehrmacht Pskov binnen; de stad bleef tot 23 juli 1944 onder Duits militair bestuur. Bron: Pskov-stadschronologie, memorialmuseums.org «Memorials in Pskov» — zoeksamenvatting [samenvatting].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["Vitebsk door het Duitse leger ingenomen", "e1e4d7d0"], "d": ["De Legergroep Midden nam Vitebsk in de eerste weken van Barbarossa in; de stad bleef tot juni 1944 onder Duits militair bestuur en een groot deel van haar bevolking kwam om.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Smolensk door het Duitse leger ingenomen", "5a7f4e2a"], "d": ["De Legergroep Midden nam Smolensk in; deze stad aan de weg naar Moskou bleef tot 25 september 1943 26 maanden bezet en werd zwaar verwoest.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["Mogilev door het Duitse leger ingenomen", "4362b7a1"], "d": ["Mogilev kwam na een 23 dagen durende verdediging in handen van de Wehrmacht; de stad bleef tot 28 juni 1944 bezet.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Reichskommissariat Ostland opgericht — de Baltische landen en Wit-Rusland kwamen onder Duits civiel bestuur", "052d4c08"], "d": ["Met het besluit van Hitler van 17 juli 1941 werden de bezette gebieden van het Oosten aan civiel bestuur overgedragen; Ostland onder leiding van Hinrich Lohse omvatte Estland, Letland, Litouwen en Wit-Rusland (centrum Riga). Het civiele bestuur van Estland volgde op 5 december 1941, het oosten van Wit-Rusland bleef onder militair bestuur.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["Narva door Duitse en Estse troepen ingenomen", "60fc2b6a"], "d": ["In de Zomeroorlog namen Estse vrijwilligers en de Wehrmacht Narva in; de stad werd bij Ostland gevoegd en bleef tot 26 juli 1944 onder Duits bestuur.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["Novgorod door het Duitse leger ingenomen", "4f599b62"], "d": ["De Legergroep Noord nam Novgorod in; een van de oudste steden van Rusland bleef tot januari 1944 bezet en werd grotendeels verwoest.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["Gomel door het Duitse leger ingenomen", "9d78eb92"], "d": ["Drie dagen na de aanval van de Wehrmacht op Gomel trok het Rode Leger zich volledig uit de stad terug; de stad bleef tot 26 november 1943 bezet.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["Tallinn door het Duitse 18e Leger ingenomen", "a855ad0d"], "d": ["Met de bloedige evacuatie van de Sovjet-Baltische Vloot naar Kronstadt viel Tallinn; Estland werd binnen Ostland het Generalbezirk Estland (op 5 december 1941 civiel bestuur).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["Orjol door het Duitse leger ingenomen", "3127f454"], "d": ["In de operatie Brjansk-Vjazma nam het Duitse 2e Pantserleger Orjol in; de stad bleef tot 5 augustus 1943 bezet.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["Brjansk door het Duitse leger ingenomen", "20fa93f8"], "d": ["Aan het einde van de Slag om Brjansk trokken de Duitse troepen de stad binnen; de stad bleef tot 17 september 1943 bezet.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["Koersk door het Duitse leger ingenomen", "a723a00a"], "d": ["Op bevel van het Sovjetcommando werd Koersk ontruimd en trok het Duitse 2e Leger de stad binnen; de stad bleef tot 8 februari 1943 bezet.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["Koersk door het Rode Leger bevrijd", "1ac03fba"], "d": ["Aan het einde van het Sovjetwinteroffensief (de Koersk-Charkov-richting na de operatie Voronezj-Kastornoje) werd Koersk heroverd; in juli van hetzelfde jaar werd de naam van de stad aan de Slag bij Koersk gegeven.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["Orjol door het Rode Leger heroverd — de eerste Sovjetsalvo na Koersk", "80bfc68d"], "d": ["De verovering van de Orjol-boog en het afvuren van de eerste artilleriesalvo in Moskou, samen met Belgorod.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["Brjansk door het Rode Leger heroverd", "d0f2a35f"], "d": ["Met de Brjansk-operatie werd de stad op 17 september 1943 heroverd.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["Smolensk door het Rode Leger bevrijd", "6516d85a"], "d": ["Op het hoogtepunt van de Smolensk-operatie van 7 augustus-2 oktober 1943 werd de stad heroverd; Smolensk kreeg in 1985 de titel 'heldenstad'.", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["Gomel door het Rode Leger bevrijd", "280268c2"], "d": ["Het Wit-Russische Front heroverde de stad in de operatie Gomel-Retsjitsa; het is een van de eerste grote stadsbevrijdingen van Wit-Rusland.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["Novgorod door het Rode Leger bevrijd", "52962012"], "d": ["Tijdens de operatie Leningrad-Novgorod werd Veliki Novgorod op 20 januari 1944 heroverd.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["Vitebsk door het Rode Leger bevrijd — Operatie Bagration", "b06be69c"], "d": ["Het 1e Baltische en het 3e Wit-Russische Front omsingelden en namen Vitebsk in; het was de eerste grote stadsbevrijding van Operatie Bagration.", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["Mogilev door het Rode Leger bevrijd — Operatie Bagration", "52fa985d"], "d": ["Het 2e Wit-Russische Front nam Mogilev in en overschreed de Dnjepr-lijn.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["Het Rode Leger heroverde Minsk — Operatie Bagration", "87dc1fb5"], "d": ["In Operatie Bagration, die op 22 juni begon, doorbraken de Wit-Russische fronten Legergroep Midden en omsingelden Minsk; de stad werd op 3 juli heroverd en bijna 50 duizend Duitse soldaten bleven in het oosten omsingeld. Het Duitse civiele bestuur van Wit-Rusland (Generalbezirk Weißruthenien) stortte in.", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["Het Rode Leger nam Vilnius in", "0172450e"], "d": ["In de Vilnius-operatie van 5-13 juli omsingelde het 3e Wit-Russische Front het Duitse garnizoen en nam de stad in (de operatie «Ostra Brama» van het Poolse Thuisleger was gelijktijdig). Vilnius werd de hoofdstad van de Litouwse SSR.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["Het Rode Leger bevrijdde Grodno van de Duitse bezetting", "1d134151"], "d": ["Oostfront: Barbarossa in 1941 en Bagration in 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["Pskov door het Rode Leger heroverd", "f18103aa"], "d": ["Na meer dan drie jaar Duitse bezetting werd Pskov door het Rode Leger heroverd.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["Het Rode Leger nam Narva in", "64854ae3"], "d": ["Narva, dat sinds februari 1944 verwoest aan de frontlinie lag, werd in de Narva-operatie van juli 1944 door Sovjettroepen ingenomen; het noordoosten van Estland ging uit handen van het Duitse civiele bestuur (Generalbezirk Estland).", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["Rēzekne door het Rode Leger ingenomen — het oosten van Letland bevrijd", "e9efd12d"], "d": ["Het 2e Baltische Front nam Rēzekne in; de Letse regio Latgale kwam uit het Duitse bestuur.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Daugavpils door het Rode Leger bevrijd", "b4ee6622"], "d": ["De 360e Infanteriedivisie van het 2e Baltische Front nam Daugavpils (Dünaburg) in; de tweede grote stad van Latgale kwam uit het Duitse bestuur.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Šiauliai door het Rode Leger ingenomen — Šiauliai-operatie", "ccb20729"], "d": ["Het 1e Baltische Front nam Šiauliai, het spoorwegknooppunt in het noorden van Litouwen, in; de operatie duurde van 5 juli tot 29 augustus 1944 en bereikte de Golf van Riga.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["Het Rode Leger bevrijdde Brest-Litovsk van de Duitse bezetting", "6d5a837a"], "d": ["Oostfront: Barbarossa in 1941 en Bagration in 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Kaunas door het Rode Leger ingenomen — de tijdelijke hoofdstad van Litouwen kwam uit het Duitse bestuur", "5c2b2c16"], "d": ["Het 3e Wit-Russische Front nam Kaunas in; Stalins dagorder van 1 augustus maakte de inname bekend. De stad was in 1919-1939 de tijdelijke hoofdstad van Litouwen.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Tartu door het Rode Leger ingenomen — Tartu-operatie", "cc8069ab"], "d": ["Het 3e Baltische Front doorbrak de verdediging van het Duitse 18e Leger en nam Tartu in; de stad bleef enkele weken aan de frontlinie en de Tartu-operatie eindigde op 6 september 1944.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["Het Rode Leger trok Tallinn binnen — de Duitse troepen verlieten de stad", "41ae1ec5"], "d": ["Tijdens de Tallinn-operatie verlieten de Duitsers de stad; de regering van het Estse Nationale Comité, die op 18 september de regeringsgebouwen overnam, kon het bestuur niet behouden toen het Rode Leger binnentrok. Estland kwam opnieuw onder Sovjetbestuur.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["Het Rode Leger nam Memel (Klaipėda) in", "d01ad3dc"], "d": ["In de Sovjetoperatie richting Oost-Pruisen en de Oostzeekust werd de haven van Memel (Klaipėda) aan Duitsland ontnomen en aan de Litouwse SSR gebonden. Het gebied dat in 1939 aan Duitsland was overgedragen, kwam zo uit het Duitse bestuur.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["De Koerland-zak gaf zich over — de Courland Army Group tekende de capitulatie voor Govorov", "3c88889b"], "d": ["De Duitse Legergroep Koerland, sinds oktober 1944 omsingeld rond Liepāja-Ventspils, gaf zich over; het westen van Letland kwam onder Sovjetcontrole.", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["De troepen van de sultan van Oman trokken de belangrijkste centra van Binnen-Oman binnen; het Ibadi-imamaat kwam feitelijk ten einde", "9a9962a5"], "d": ["In december 1955 trad de sultan van Oman op om zijn gezag te herstellen en zijn troepen trokken de belangrijkste nederzettingscentra van Binnen-Oman binnen (Bahla, Izki, Nizwa); het bestuur van het Ibadi-imamaat over Binnen-Oman eindigde feitelijk. De bron geeft alleen de maand; op de kaart wordt 1 december 1955 getoond.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Koeweit kwam uit de Britse bescherming en verwierf volledige onafhankelijkheid", "e9a86d04"], "d": ["Met de op 19 juni 1961 tussen Koeweit en het Verenigd Koninkrijk uitgewisselde noten eindigde de Britse bescherming die sinds de overeenkomst van 1899 had bestaan en werd Koeweit volledig onafhankelijk. Op de kaart eindigt de Britse laag in Koeweit op deze dag.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Qatar riep zijn onafhankelijkheid uit na het aflopen van de verdragen met Engeland", "8f288cc6"], "d": ["Na de datum waarop de beschermingsverdragen met Groot-Brittannië afliepen, riep Qatar op 3 september 1971 zijn onafhankelijkheid uit. Op de kaart eindigt de Britse laag in Doha op deze dag.", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["De forten van Istranca: verovering van Pınarhisar, Kırkkilise (Kırklareli) en Vize", "c6b1a9c1"], "d": ["Murad I, die de winter van 1369 in het paleis van Edirne had doorgebracht, trad in het voorjaar opnieuw op tegen Byzantium en nam de forten Pınarhisar, Kırkkilise en Vize aan de voet van het Istranca-gebergte in. Deze veroveringen veroorzaakten paniek in Constantinopel en keizer Johannes V besloot naar de paus te gaan om hulp te zoeken.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Tasjkent kwam onder het bestuur van Yunus Khan, khan van Mogolistan", "a37ee010"], "d": ["Tijdens de troonstrijd tussen de Timuridische prinsen kwamen Tasjkent en omgeving in handen van Yunus Khan, khan van Oost-Chagatai (Mogolistan). Toen Yunus Khan twee jaar later stierf, werd hij opgevolgd door zijn zoon Mahmud Khan; de stad bleef bij de Mogol-khans tot de Oezbeken van Sjajbani Khan haar in 1503 innamen.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Babur liet Fergana aan de Oezbeken en ging naar Kabul", "69df593c"], "d": ["Babur, de Timurid en zoon van Umar Sheikh Mirza, liet na de oorlogen met Muhammad Sjajbani Khan Fergana, waar hij sinds 1494 regeerde, aan de Oezbeken en vestigde zich in Kabul na de Hindoekoesj te zijn overgestoken.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Piri Reis tekende de oudste overgeleverde wereldkaart", "6ef941f5"], "d": ["Piri Reis tekende in Gallipoli de wereldkaart met de datum 919 (1513); volgens de TDV Islam Ansiklopedisi behoren tot de bronnen van de kaart 'oude kaarten uit de oostelijke en westelijke wereld die hem bereikten en de kaart van Christoffel Columbus' — dat wil zeggen dat men denkt dat zij sporen draagt van Columbus' originele navigatiekaart, die in die tijd als verloren werd beschouwd. Hij bood de kaart in 923 (1517) in Caïro aan Selim de Norse aan. Slechts een fragment dat alleen de westelijke/Atlantische kusten toont (Spanje, Portugal, West-Afrika, de oostkust van Zuid-Amerika) is tot op heden bewaard gebleven; dit fragment werd in 1929 opnieuw ontdekt in het Topkapı-paleis en staat op de UNESCO-lijst van het Geheugen van de Wereld.", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Integratie van de regio Kars: Şüregel, Arpaçay en Digor kwamen onder Ottomaans bestuur", "10f16b5c"], "d": ["Tijdens de Irakeyn-veldtocht kwamen de forten Pasin, Şüregel en Oltu in handen van de Ottomanen; het is zeer waarschijnlijk dat ook het fort Kars toen werd ingenomen. De regio Arpaçay en Digor ten noorden en oosten van Kars kwam met dezelfde operatie onder Ottomaanse controle.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Einde van de Sjirvansjahs: Elqas Mirza nam Sjahroech gevangen, Sjirvan werd een Safawidische provincie", "e6d64114"], "d": ["Elqas Mirza, door Sjah Tahmasp gestuurd, plunderde Sjirvan, nam het fort Baykurd in en voerde de vijftienjarige Sjirvansjah Sjahroech gevangen naar Tabriz. Het bestuur van de Sjirvansjahs, dat lange tijd in de regio de heerschappij had gevoerd, kwam zo ten einde; Sjirvan werd een provincie van de Safawidische staat.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Uitbreiding van de Ocak van Algiers naar de Sahara — Touggourt-Ouargla tribuutplichtig, definitieve verovering van Tlemcen", "705ec920"], "d": ["Volgens het lemma Tilimsan van de TDV nam een groot leger dat in 960 (1553) vanuit Algiers werd gestuurd onder bevel van Salih Reis de stad definitief in en maakte een einde aan de driehonderd jaar oude Zayyanid-dynastie. In dezelfde periode (1552) organiseerde Salih Reis een veldtocht tegen de onafhankelijke sultanaten Touggourt en Ouargla; de Ottomaanse troepen namen Touggourt in, rukten op naar Ouargla en beide sultanaten werden tribuutplichtig; in Biskra, op de route, werd een permanent Ottomaans garnizoen achtergelaten. Zo bereikte de grens van de Ocak van Algiers voor het eerst, de Tell Atlas overschrijdend, de rand van de Sahara. De grote slag voor Mostaganem vond echter niet dit jaar plaats maar in 1558: Hasan Pasja versloeg daar de Spaanse graaf van Alcaudete en maakte een einde aan de Spaanse aanvallen in Noord-Afrika.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Stichting van het eyalet Habesh — de kust van de Rode Zee kwam onder Ottomaans bestuur", "7dd470ec"], "d": ["Het eyalet, gesticht om te voorkomen dat Portugal via Abessinië tot de Rode Zee doordrong, werd volgens het lemma Habeş Eyaleti van de TDV op 15 Şaban 962 (5 juli 1555) officieel gesticht, met Suakin als sandjakcentrum. Özdemir Pasja begon in de herfst van 1555 met de operatie; hij nam de Dahlak-eilanden in die de haven van Massawa controleerden en nam op 2 april 1557 de stad Massawa in en daarna Arkiko. De verovering werd voortgezet met de onderwerping van het eyalet Tigray in 1558 en van Debarwa in 1559 aan de Ottomaanse heerschappij.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Sedefkâr Mehmed Ağa werd tot hoofdarchitect benoemd — de architect van de Sultanahmet-moskee", "27b66fce"], "d": ["Mehmed Ağa, die in 1562-63 als devşirme uit de stad Elbasan in Albanië aan het paleis werd opgenomen, werd bij Mimar Sinan opgeleid en op 11 oktober 1606 tot hoofdarchitect van het Ottomaanse Rijk benoemd. De TDV Islam Ansiklopedisi vermeldt dat een bron uit zijn tijd hem beschrijft als 'zachtaardig, bescheiden, een man van zijn woord, vroom en intelligent'. Mehmed Ağa, die drie jaar later op bevel van Ahmed I met de bouw van de Sultanahmet-moskee zou beginnen, liet een uitgebreid oeuvre na, van herstelwerkzaamheden aan de Kaäba tot talrijke fonteinen en moskeeën in Constantinopel en Edirne. Dat de zes minaretten tot een discussie over 'gelijkheid' met de Kaäba in Mekka leidden, is een wijdverbreid volksverhaal; encyclopedische bronnen bevestigen dit niet en kenmerken de opzet alleen als 'tot dan toe onbeproefd'.", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["De nieuwe sultan Mustafa I: een 'kafes'-gevangene met een bleek gelaat en verstrooide blik op de troon", "c487b0d1"], "d": ["Mustafa I, die na de dood van Ahmed I de troon besteeg, had als eerste prins die zijn broer in leven had gelaten jarenlang onder strenge bewaking in het paleis opgesloten geleefd; de TDV Islam Ansiklopedisi beschrijft hem als 'met een bleek gelaat, dunne baard, grote zwarte ogen en een doffe blik' en noteert dat deze lange gevangenschap zijn psychische toestand verergerde. In dit eerste sultanaat van zesennegentig dagen kon hij de staatszaken niet voeren; daarentegen wordt verteld dat hij vaak ging jagen, de scheepswerf bezocht en zelfs goud in het water wierp om naar de vissen te kijken. Het Janitsarenkorps en de ulema, die hem ongeschikt voor het heerserschap achtten, zetten hem op 26 februari 1618 af en plaatsten zijn veertienjarige neef Osman II op de troon.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["De reisdroom van Evliya Çelebi — 'Seyahat' zeggen in plaats van 'Şefaat'", "2d863e22"], "d": ["Volgens de TDV Islam Ansiklopedisi verbindt Evliya Çelebi het begin van zijn veertig jaar durende reizende leven met een droom die hij in de Asjoera-nacht van Muharram van het jaar 1040 (19 augustus 1630) had: in zijn droom zag hij in de Ahi Çelebi-moskee in Constantinopel samen met een grote gemeente de Profeet en zei van opwinding in plaats van 'şefaat ya Resulallah' (voorspraak, o Gezant van God) 'seyahat ya Resulallah' (reizen, o Gezant van God). Volgens het verhaal glimlachte de Profeet bij deze verspreking en kondigde hem zowel voorspraak als reizen als bedevaart aan. Hij trouwde nooit en wijdde zijn leven aan deze belofte van 'reizen'.", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["De tegenstrijdigheden van Murad IV: het drankverbod van een aan drank verslaafde sultan, de pols van een worstelaar, het oor van een componist", "3d2ea5e0"], "d": ["Tijdens de eerste jaren van Murad IV, die op elfjarige leeftijd de troon besteeg, was de invloed van zijn moeder Kösem Sultan bepalend; de TDV Islam Ansiklopedisi vermeldt dat Kösem, bevreesd voor de machtsneiging van haar zoon, hem 'tot vermaak aanzette en hem met geschenken en feesten bezighield'. Toen hij op ongeveer twintigjarige leeftijd feitelijk het bestuur in handen nam, was hij een lange, breedgeschouderde, indrukwekkende heerser — er wordt verteld dat hij een sterke man bij zijn gordel optilde en enkele keren in de Has Oda rondvoerde. De opvallende tegenstrijdigheid die de TDV noteert, is deze: de sultan, van wie werd gezegd dat hij tabak en opium verafschuwde, was buitensporig aan drank verslaafd, en verbood desondanks vóór de veldtocht koffie, tabak en later ook de drank zelf; tegelijk had hij zoveel kennis van muziek dat hij overeenkomstig de traditie van het ambt composities maakte.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["De raketvlucht van Lagari Hasan Çelebi — een verhaal waarvoor Evliya Çelebi de enige bron is", "1f02e3f2"], "d": ["Volgens de Seyahatname van Evliya Çelebi vervaardigde Lagari Hasan Çelebi in aanwezigheid van Murad IV bij Sarayburnu een zevenarmige vuurpijlconstructie met vijftig oka buskruit en besteeg de pijl met de woorden 'Mijn sultan, ik vertrouw u toe aan God, ik ga praten met de profeet Jezus'. Volgens het verhaal steeg Hasan Çelebi ongeveer 250 meter omhoog, zweefde met werktuigen die op valkenvleugels leken naar de zee, zwom en keerde terug naar de sultan en verdiende daarvoor een sipahilik met een dagloon van zeventig akçe.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Kemankeş Kara Mustafa Pasja werd grootvizier — begin van de periode van financiële sanering", "583846a4"], "d": ["Kemankeş Kara Mustafa Pasja, die op 17 Şaban 1048 (24 december 1638) grootvizier werd nadat Tayyar Mehmed Pasja tijdens de Bagdad-veldtocht was gesneuveld, voerde onder Sultan Ibrahim een strenge financiële discipline in: hij bracht het aantal Janitsaren en sipahi's terug tot een derde, herstelde het muntgehalte en verscherpte het narh-stelsel. Met het door de TDV gegeven cijfer bereikte deze bezuiniging 6000 buidels per jaar — maar deze strenge controle bezorgde hem vijanden in de omgeving van het paleis.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Mustafa I stierf na vijftien jaar van vergetelheid", "b4c872cd"], "d": ["Mustafa I, die op 10 september 1623 voor de tweede keer werd afgezet, leefde tot zijn dood vijftien jaar lang in een kamer waarin hij werd opgesloten; over deze jaren is er in de bronnen geen enkele informatie. Hij overleed op 15 Ramadan 1048 (20 januari 1639) — een deel van de bronnen beschouwt dit als natuurlijke dood, een deel beweert dat Murad IV er de hand in had.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["'Gekke Ibrahim' of een wisselvallige ziekte?", "2abc230f"], "d": ["De TDV Islam Ansiklopedisi verwerpt uitdrukkelijk de in de 20e eeuw wijdverbreide bijnaam 'Gekke Ibrahim'; zij vermeldt dat de sultan in zijn eigen brieven klaagt over pijnen, gebrek aan eetlust, zwakte in zijn benen, een mistgevoel in zijn hoofd, benauwdheid op de borst en flauwtevallen. Daartegenover staat dat zijn consistente en redelijke antwoorden tijdens het afzettingsproces de bewering van een voortdurende onevenwichtigheid tegenspreken; het lemma komt tot de conclusie dat zijn toestand 'niet constant was maar in ernst wisselde'. In deze periode namen de verantwoordelijkheden van Kösem Sultan geleidelijk toe en vergrootte het feit dat Cinci Hoca aan het paleis werd geroepen om de sultan met 'werkzame gebeden' geestelijke troost te bieden, zijn macht om zich met de politiek te bemoeien.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["De Samur-affaire — de bonthoofdbelasting van grootvizier Ahmed Pasja bereidde het einde van Ibrahim voor", "a2a47d62"], "d": ["Terwijl Sultan Ibrahims voorliefde voor sabelbont en amber in het paleis steeds groter werd, begon grootvizier Ahmed Pasja omstreeks 1647-1648 een praktijk waarbij van de staatsgrootheden met dwang een bedrag voor sabelbont werd geïnd; de TDV Islam Ansiklopedisi noteert dat de ambtenaren dit als een regelrechte 'haraç' (schatting) zagen. Toen de Janitsarenofficieren de betaling gezamenlijk weigerden, werd dit verzet de directe aanleiding voor het proces dat tot de afzetting van de sultan leidde — de op de ochtend van 7 augustus 1648 verzamelde ambtenaren doodden eerst Ahmed Pasja en zetten de volgende dag Ibrahim af.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["'De staat wordt door vrouwen bestuurd' — de opstand van Varvar Ali Pasja vanuit Sivas", "5b027357"], "d": ["Varvar Ali Pasja, beylerbey van Sivas, weigerde de 30.000 kuruş te betalen die Constantinopel onder de naam 'bayramiye' eiste, met de woorden 'de jaarlijkse inkomsten van Sivas dekken dit bedrag niet'; volgens de TDV Islam Ansiklopedisi was de rechtvaardiging van zijn opstand de bewering dat de staatszaken door de ongesteldheid van de sultan in handen van vrouwen waren gekomen en dat dit door veelvuldige gouverneurswisselingen instabiliteit veroorzaakte. Hoewel hij in mei 1648 eerst militair succes had, werd hij door Ipşir Mustafa Pasja verslagen, op 20 mei 1648 geëxecuteerd en zijn hoofd naar Constantinopel gestuurd.", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Verlies van Nauplion aan Venetië — het keerpunt van de Morea-oorlog", "9d400557"], "d": ["Volgens het lemma Anabolu van de TDV vluchtte tijdens het beleg het overlevende deel van de moslimbevolking van de stad naar de omliggende eilanden en naar Anatolië (1686). Volgens de standaard academische bron (Setton, Venice, Austria, and the Turks in the Seventeenth Century) sloegen de troepen van Königsmarck twee weken lang de aanvallen van het Ottomaanse ontzettingsleger af; toen de aanval van İsmail Pasja op 29 augustus met een zware nederlaag eindigde, gaf het fort zich binnen enkele dagen over. Nauplion was Ottomaans gebied dat in 1540 bij verdrag was overgenomen; met het verlies ervan versnelde de overgang van het schiereiland Morea naar Venetië.", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Mehmed IV gaf de jacht op — de laatste stuiptrekking aan de vooravond van zijn afzetting", "7daa904b"], "d": ["Na de nederlaag bij Mohács (augustus 1687) kwam het leger, dat zijn soldij niet kreeg uitbetaald, in opstand en marcheerde naar Constantinopel. Mehmed IV liet Süleyman Pasja, die het grootviziersegel had laten ontvluchten, doden en toonde zijn hoofd aan de soldaten, en verklaarde zijn berouw door zijn jachtuitrusting en windhonden uiteen te laten gaan — maar dit gebaar was niet genoeg om zijn troon te redden, enkele maanden later werd hij afgezet.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Overgave van het fort Munkács (Mukatsjeve) aan Oostenrijk na een beleg van drie jaar", "ca2efc3d"], "d": ["Het fort Munkács, dat eind 1685 door keizerlijke troepen werd belegerd, hield drie jaar stand onder het bestuur van İlona Zrínyi, de echtgenote van Imre Thököly; volgens veel gepubliceerde naslagwerken werd het fort op 17 januari 1688 aan generaal Antonio Caraffa overgegeven. Dit was de val van een van de laatste grote forten van het pro-Ottomaanse verzet in Hongarije aan het Ottomaans-Habsburgse front.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Baltacı Mehmed Pasja en het verhaal over tsarina Catharina", "c1b739f1"], "d": ["Het populaire verhaal dat de redding van het bij de Pruth belegerde Russische leger toeschrijft aan de geschenken/het steekpenningen die Catharina I naar Baltacı Mehmed Pasja stuurde, werd eeuwenlang herhaald.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["De discussie over de 'gemiste kans' bij de Pruth — twee opvattingen", "61ee699c"], "d": ["Dat men zich met vrede tevreden stelde terwijl het Ottomaanse leger het Russische leger volledig had omsingeld, werd direct na het verdrag onderwerp van discussie onder historici — in de eigen woorden van de TDV 'bleek dat een grote kans was gemist en deze stelling werd door de tegenstanders intensief uitgewerkt.' Volgens de critici had de tsaar gevangen kunnen worden genomen en hadden de wapens van het Russische leger in beslag kunnen worden genomen; volgens de verdedigers was het daarentegen een 'verstandiger beleid' om Rusland slechts beperkt te verzwakken om te voorkomen dat Zweden in Noord-Europa sterker werd. De TDV geeft beide opvattingen weer en kiest geen partij.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Commissie van tweeëndertig personen voor wetenschap/vertaling opgericht", "0e3a713c"], "d": ["Tijdens het grootvizierschap van Damat İbrahim Pasja werd in Constantinopel een commissie van tweeëndertig geleerden en schrijvers opgericht die, in de bewoordingen van de TDV, 'als de academie van de tijd kan worden beschouwd'. De commissie bracht werken over geschiedenis, filosofie en geografie uit het Arabisch, Perzisch, Grieks en Latijn naar het Turks — onder meer Yanyalı Esad Efendi, die met een team van vijfentwintig personen de Fysica van Aristoteles vertaalde, en de dichter Nedim, die voorzitter was van een commissie voor geschiedenisvertalingen. De dag wordt in de TDV niet vermeld, het jaar wel.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Mahmud I lokte Patrona Halil in de val door hem naar het paleis uit te nodigen", "6147059f"], "d": ["Zeven weken na zijn troonsbestijging brak Mahmud I de invloed van Patrona Halil door via vertrouwelingen — in het paleis Hacı Beşir Ağa, daarbuiten Kaplan Giray I, khan van de Krim — de leiders van de soldaten naar zijn zijde te trekken. Patrona Halil, die op 25 november 1730 voor een vergadering in de Sünnet Odası van het Topkapı-paleis werd geroepen, werd samen met Muslu Beşe en Kel Mehmed Ağa binnengelaten; op een teken van grootvizier Silahdar Mehmed Pasja kwamen tweeëndertig van tevoren verborgen gewapende mannen tevoorschijn en doodden alle drie. Mahmud I nam zo de controle over de opstand volledig over.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Humbaracı Ahmed Pasja (Bonneval) werd aan het hoofd van het Humbaracı-korps geplaatst", "27b0b1d7"], "d": ["De officier van Franse afkomst, wiens eigenlijke naam Claude-Alexandre Comte de Bonneval was, diende eerst in de Franse en Oostenrijkse legers, nam daarna in Sarajevo de islam aan onder de naam Ahmed en zocht in 1729 zijn toevlucht bij het Ottomaanse Rijk. Ahmed Pasja, die onder Mahmud I in 1731 aan het hoofd van het Humbaracı-korps werd geplaatst, liet in de door hem gebouwde kazerne in Üsküdar Ayazma ongeveer 300 manschappen die uit Bosnië waren gehaald oefenen; hun aantal steeg weldra boven de 600 en hij gaf zelf ook wiskundelessen. Zijn poging tot een opstand in Hongarije met Rákóczi ten gunste van Frankrijk ondermijnde zijn invloed en in 1738 werd hij naar Kastamonu verbannen. Hij overleed op 23 mei 1747 in Constantinopel; zijn graf bevindt zich op het kerkhof van het Galata-Mevlevi-klooster.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Herovering van Smederevo op de Habsburgers (kroon van het Koninkrijk Hongarije) — de oorlog van 1737-39", "63dcf604"], "d": ["Volgens het lemma Semendire van de TDV werd het fort, dat in 1717 met Passarowitz aan Oostenrijk was afgestaan, heroverd door de Ottomaanse opmars aan het Donau-Sava-front van de in 1737 begonnen Ottomaans-Oostenrijkse Oorlog; de Habsburgse troepen (kroon van het Koninkrijk Hongarije) konden zich in de regio tot augustus 1738 handhaven, waarna Smederevo opnieuw onder Ottomaans bestuur kwam. Het een jaar later ondertekende Verdrag van Belgrado (1739-09-18) zou deze winst — samen met Belgrado en Noord-Servië — bekrachtigen.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Terugkeer van de Morava-vallei onder Ottomaans bestuur — Jagodina, Kragujevac en Čačak", "b219d3c9"], "d": ["Met de herovering van Smederevo in augustus 1738 keerde ook de Morava-vallei, die tussen Smederevo en het hoofdgebied van de Ottomanen lag, terug onder Ottomaans bestuur: Jagodina, Kragujevac en Čačak gelden vanaf deze datum als Ottomaans. De bronnen vermelden de terugkeer van deze drie plaatsen niet afzonderlijk met een datum; de kaart werkt met de dag van Smederevo. Het Verdrag van Belgrado (1739-09-18) bekrachtigde deze toestand.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Abdülhamid I kreeg een beroerte en overleed bij het lezen van het nieuws over de val van Özi", "6ac60365"], "d": ["Volgens het lemma abdulhamid-i van de TDV Islam Ansiklopedisi overleed Abdülhamid I, wiens gezondheid door het zware verloop van de Russisch-Oostenrijkse oorlog sterk was verslechterd, aan een plotselinge beroerte terwijl hij de kaime van de grootvizier las die meldde dat het fort Özi door de Russen was bezet (11 Recep 1203 / 7 april 1789). Zijn lichaam werd in Constantinopel bij Bahçekapı bijgezet in het mausoleum dat hij zelf had laten bouwen. Op dezelfde dag besteeg zijn neef Selim III de troon.", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Ottomaans-Russische Defensieve Alliantie — gezamenlijke verdediging tegen Frankrijk", "c87079d1"], "d": ["Naar aanleiding van de bezetting van Egypte door Napoleon sloten Selim III en de Russische tsaar Paul I een defensieve alliantie van veertien artikelen voor acht jaar. De partijen namen op zich gezamenlijke vrienden en vijanden te hebben, elkaar wederzijds te helpen en geen afzonderlijke vrede te sluiten.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Ottomaans-Siciliaanse (Napels) Defensieve Alliantie — gemeenschappelijke zaak tegen Frankrijk", "1d2be816"], "d": ["Tegenover de Franse bezetting van Italië, Malta en Egypte sloten het Ottomaanse Rijk en het Koninkrijk der Beide Siciliën een defensieve alliantie van negen artikelen. De partijen namen op zich gezamenlijk oorlog te voeren, geen afzonderlijke vrede te sluiten en elkaar hulp te verlenen te land en ter zee.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["De Republiek der Zeven Eilanden werd gesticht — de Ionische eilanden onder Russisch-Ottomaanse bescherming", "08839694"], "d": ["In 1799 had de gezamenlijke Russisch-Ottomaanse vloot de Fransen van de Ionische eilanden verdreven (het fort van Korfoe viel op 5 maart 1799); met de overeenkomst van twaalf artikelen van 21 maart 1800 werden de eilanden gesticht als de Cezayir-i Seb'a-i Müctemia Cumhuru (Republiek der Zeven Eilanden), autonoom in interne zaken en in buitenlandse zaken aan de Ottomanen gebonden. De periode tussen 1799-03-05 en deze dag is een periode van gezamenlijke bezetting.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Tilsit — de Russische rechten over de Republiek der Zeven Eilanden werden aan Frankrijk overgedragen", "98a78beb"], "d": ["Met de overeenkomst die in Tilsit tussen Rusland en Frankrijk werd bereikt, liet Rusland zijn rechten over de Zeven Eilanden aan Frankrijk; Franse troepen vestigden zich in de zomer van 1807 op de eilanden en de Republiek der Zeven Eilanden verdween.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Overgang van Santa Maura en de Ionische Eilanden onder Britse bescherming — de orde na Napoleon", "0af821dc"], "d": ["Santa Maura en de andere Ionische eilanden, die in 1797 aan Frankrijk waren gegaan, werden na de definitieve nederlaag van Napoleon met het op 5 november 1815 in Parijs tussen Engeland, Rusland, Oostenrijk en Pruisen ondertekende bijzondere verdrag onder de naam 'Verenigde Staten van de Zeven Eilanden' onder Britse bescherming gelaten — dit is een afzonderlijk document van het algemene Verdrag van Parijs van 20 november 1815. De bescherming zou tot 1864 duren, daarna werden de eilanden aan Griekenland overgedragen.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Verovering van Prizren — Ottomaans sandjakcentrum in Kosovo", "f84c220f"], "d": ["Op 4 Recep 859 (20 juni 1455) nam het Ottomaanse leger onder bevel van Mehmed de Veroveraar Prizren in na de strijd met de Servische despoot Đurađ Branković — in Ottomaanse bronnen Vılkoğlu. De stad was halverwege de 13e eeuw van Byzantium naar het Servische Koninkrijk gegaan en was onder koning Milutin, tsaar Dušan en koning Uroš koninklijke residentie geweest; na de dood van Dušan was haar belang afgenomen. Na de verovering werd zij het centrum van een sandjak en behield deze hoedanigheid vier en een halve eeuw tot 1912. Prizren was vóór de ontbinding van Joegoslavië de enige stad op de Balkan waar drie talen — Albanees, Turks en Servisch — samen werden gesproken.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["Val van de Bastille — begin van de Franse Revolutie", "96e931f1"], "d": ["Te midden van de woede en de economische crisis die door het ontslag van Necker, de minister van Financiën van koning Lodewijk XVI (11 juli 1789), waren ontstaan, marcheerde het volk van Parijs naar het fort van de Bastille met een eis om wapens en buskruit. In de gevechten die 's middags begonnen en waarin tegenover meer dan drieduizend opstandelingen slechts ongeveer honderd bewakers stonden, gaf het fort zich omstreeks 17.00 uur over; enkele functionarissen, onder wie de commandant van het fort Bernard-René de Launay, werden gedood en zeven gevangenen werden vrijgelaten. Het bijna lege fort, dat bovendien al voor sloop was gepland, was het symbool van koninklijke tirannie — over de val ervan wordt aan Lodewijk XVI gemeld: 'Nee, sire, dit is geen opstand, het is een revolutie.' 14 juli is tegenwoordig de nationale feestdag van Frankrijk en de gebeurtenis wordt beschouwd als het symbolische begin van de volksbeweging die zich snel over het hele land verspreidde en van de Franse Revolutie (1789-1799) — de revolutie zou in het volgende decennium de absolute monarchie omverwerpen en de politieke kaart van Europa en ook de internationale evenwichten waartoe het Ottomaanse Rijk behoorde blijvend veranderen.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Het Mamelukse leger trok Malatya binnen — de stad ging van de Ilkhanen naar Mamelukse heerschappij", "2540363d"], "d": ["De Mamelukken stuurden een leger onder bevel van Sayf al-Din Tengiz, de naib van Damascus, tegen Malatya; het leger trok op 22 Muharram 715 (28 april 1315) de stad binnen. Malatya was tot dan toe onder Ilkhanische heerschappij en was het sleutelpunt van de lijn ten westen van de Eufraat waar de invloedssferen van de Ilkhanen en Mamelukken elkaar raakten. Het van hand wisselen van de stad toont de opmars van de Mamelukken naar de Boven-Eufraat in de lange strijd tussen de twee staten. Malatya zou na deze datum enige tijd onder het bestuur van de Eretnaoğulları komen en vanaf 1338 opnieuw onder Mamelukse heerschappij terugkeren.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Einde van het beylik van de Eşrefoğulları — Beyşehir en Seydişehir gingen naar de Hamidoğulları", "e4e70846"], "d": ["Demirtaş, zoon van Emir Çoban, gouverneur-generaal van Anatolië van de Ilkhanen, trad op tegen de Turkmeense beyliks die hun onafhankelijkheid hadden uitgeroepen, trok Beyşehir binnen en liet Eşrefoğlu Süleyman Şah, die zich destijds over hem had beklaagd, doden (9 oktober 1326). Het beylik van de Eşrefoğulları, dat aan het einde van de 13e eeuw in de regio Beyşehir en Seydişehir was gesticht, kwam zo ten einde. Het lemma Hamîdoğulları van de TDV geeft het vervolg: Beyşehir, Seydişehir, Akşehir en Doğanhisar, die aan de door Demirtaş uit de weg geruimde Eşrefoğulları hadden toebehoord, werden bij de grenzen van het beylik Hamid gevoegd. In hetzelfde jaar werd ook Hamidoğlu Dündar Bey aan Demirtaş uitgeleverd en gedood. Deze gebieden zouden in 1381 voor 80.000 goudstukken aan Murad I worden verkocht en onder Ottomaans bestuur komen.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Malatya kwam opnieuw onder Mamelukse heerschappij — einde van het bestuur van de Eretnaoğulları", "08b80aa2"], "d": ["Malatya, dat in 1315 onder Mamelukse heerschappij was gekomen, was in de jaren van ontbinding van de Ilkhanische staat enige tijd in handen van de Eretnaoğulları gekomen. Het lemma Malatya van de TDV geeft de terugkeer in één zin: vanaf 1338 heersten de Mamelukken opnieuw over de stad. Dit is een doorsnede van de jaren waarin het vacuüm na de Ilkhanen in het zuidoosten van Anatolië tussen Mamelukken en Eretna werd verdeeld.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Verlies van de haven van İzmir aan de kruisvaardersvloot — de zeemacht van de Aydınoğulları gebroken", "775c65fe"], "d": ["De kruisvaardersvloot, bestaande uit schepen van Venetië, Genua, het Koninkrijk Cyprus, de Rhodische ridders en de hertog van Naxos, op aansporing van paus Clemens VI, nam de haven van İzmir van de Aydınoğulları af (28 oktober 1344). De haven was in 1328-1329 door Mehmed Bey, de vader van Umur Bey, van de Genuees Martino Zaccaria genomen en was de basis van de Aydınoğlu-zeemacht in de Egeïsche Zee. In september 1334 had een kruisvaardersvloot die met hetzelfde doel kwam, zich moeten terugtrekken; deze tweede veldtocht slaagde. Umur Bey zette het verzet voort en versloeg, verenigd met de andere Turkse beyliks, de kruisvaardersvloot op 17 januari 1345, maar de haven kon niet worden teruggenomen.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Karamanoğlu Alaeddin Bey voegde Konya, Aksaray en Niğde bij het Karaman-gebied", "2b8b0f70"], "d": ["Karamanoğlu Alaeddin Bey, die gebruik wilde maken van het feit dat het Mamelukken-sultanaat het Armeense Koninkrijk had beëindigd en heel Çukurova bij zijn eigen gebied had gevoegd, en van de onrust in de Eretna-staat in Midden-Anatolië, voegde, voorop Konya (1366-1367), ook Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı en Kayseri bij het Karaman-gebied. Konya was door haar gewicht als Seltsjoekse hoofdstad voor de Karamanoğulları niet slechts een stad maar een aanspraak op legitimiteit.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Uzun Hasan beëindigde de Kara Koyunlu-staat — het Van-meerbekken ging naar de Akkoyunlu", "d8d6c2e8"], "d": ["De Akkoyunlu-heerser Uzun Hasan overviel in 1467 Jahan Sjah, de Kara Koyunlu-heerser en zijn onverzoenlijke vijand, die tegen hem optrok, en beëindigde zo de Kara Koyunlu-staat. Met het verdwijnen van Jahan Sjah, die sinds 1438 regeerde, ging het Van-meerbekken — Van, Bitlis, Bargiri (Muradiye), Hoşap en Kotur — van de Kara Koyunlu over naar Akkoyunlu-bestuur. Deze overwinning maakte de Akkoyunlu-staat tot de enige grote macht in Oost-Anatolië en Iran en zette Uzun Hasan op de weg die hem een generatie later tegenover de Ottomanen zou brengen.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Cem Sultan naar Rome gebracht — gijzelaarsdiplomatie en jaarlijks 40.000 dukaten", "1c6715a8"], "d": ["Paus Innocentius VIII liet Cem Sultan in overeenstemming met Pierre d'Aubusson, het hoofd van de Rhodische ridders, naar Rome brengen (4 maart 1489). Cem had op 29 juli 1482 zijn toevlucht gezocht op Rhodos en was van daar naar Savoye-gebied en uiteindelijk onder pauselijke bewaking gekomen. Bayezid II had ermee ingestemd de ridders jaarlijks 40.000 dukaten te betalen in ruil voor het in hechtenis houden van zijn broer en hun vrije handel op Ottomaans grondgebied toe te staan. Deze betaling was geen tribuut maar de prijs om de legitieme rivaal voor de troon in Europa bewegingsloos te houden: als Cem vrij was gekomen, had hij in Anatolië een leger kunnen verzamelen en bovendien een bron van legitimiteit voor een kruistocht kunnen worden. Zo werd een dynastieke kwestie dertig jaar lang de belangrijkste beperking van het Ottomaanse buitenlandse beleid — dit is de reden dat Bayezid zich in het Westen voorzichtig gedroeg. Met Cems dood in 1495 verviel deze beperking.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Het Koninkrijk Georgië werd in drieën gedeeld — Kartli, Kachetië en Imereti met Koetaisi als centrum", "f9c5f798"], "d": ["Het verenigde Koninkrijk Georgië, bestuurd door de Bagratiden-dynastie, werd na een lange interne strijd officieel in drie koninkrijken verdeeld: in het oosten Kartli met als centrum Tbilisi, in het noordoosten Kachetië en in het westen Imereti met Koetaisi als centrum. Het lemma Gürcistan van de TDV bevestigt de verdeling — 'Georgië werd verdeeld in drie koninkrijken (Kartlia, Kachetia, Imeretia) en vijf vorstendommen'. De verdeling werd bepalend in de Ottomaans-Safawidische rivaliteit van de volgende eeuw: volgens het Verdrag van Amasya van 1555 werden Imereti, Dadiani, Gurieli en Daveli aan de Ottomanen, Kartli, Kachetië en Mosuk aan de Safawiden gelaten. Dat de atlas West- en Oost-Georgië aan verschillende heren bindt, komt dus voort uit deze verdeling. Selim de Norse had, toen hij nog gouverneur van Trabzon was, in 1508 het Koninkrijk Imereti (Açıkbaş) tot gehoorzaamheid en tribuut gedwongen.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Spaanse bezetting van Tripoli — einde van de Hafsidische heerschappij", "de319d23"], "d": ["Na de Ammarogulları duurde de heerschappij van de Hafsiden in Tripoli tot het jaar 1510. In dat jaar werd de stad bezet door de Spanjaarden onder bevel van Don Pedro Navarro, graaf van Oliveto; de moslims die aan de slachting ontkwamen, verlieten de stad. De bezetting was het oostelijke uiteinde van de keten van forten van Spanje aan de Noord-Afrikaanse kust die van Melilla tot Tripoli reikte. De bevolking van Tripoli zou in 925 (1519) een delegatie naar Constantinopel sturen om Ottomaanse hulp te vragen tegen de Spaanse invasie; de stad zou in 1551 door Turgut Reis en Sinan Pasja worden ingenomen en onder Ottomaans bestuur komen.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Malta en Tripoli aan de Ridders van Sint-Jan gegeven — de nieuwe basis van de orde die uit Rhodos was verdreven", "2595729e"], "d": ["De Ridders van Sint-Jan (Hospitaalridders), die Süleyman de Grote in 928 (1522) uit Rhodos had verdreven, werden na acht jaar zonder vaderland door Karel V, koning van Spanje-Duitsland, op Malta gevestigd; met dezelfde schenking werd ook de verdediging van Tripoli aan de orde gegeven. Malta werd met zijn ideale havens een gunstige basis voor de ridders, die op zee invloedrijk waren: zij vestigden zich eerst in Birgu, versterkten het fort Sint-Elmo en bouwden aan de punt van Senglea het fort Sint-Michiel. Deze vestiging bracht een blijvende vijandelijke basis voort in het midden van de Middellandse Zee, die de Ottomaanse zeeroutes doorsneed; de gevechten die begonnen met Turgut Reis' inval op Gozo in 947 (1540) zouden duren tot het beleg van Malta in 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Vrede van Westfalen — de Dertigjarige Oorlog eindigde, de eenheid van het Heilige Roomse Rijk werd ontbonden", "d7719f05"], "d": ["De verdragen die de Dertigjarige Oorlog (1618-1648) beëindigden, werden op dezelfde dag in Münster en Osnabrück ondertekend (24 oktober 1648). Zo'n driehonderd vorstendommen van het Heilige Roomse Rijk verwierven het recht een eigen buitenlands beleid te voeren; het rijk hield op een staat te zijn en werd een overkoepelend dak. Zweden nam West-Pommeren en Stettin, Brandenburg verwierf Oost-Pommeren en de aanspraak op het aartsbisdom Maagdenburg — hier begint de gebiedsophoping van de Hohenzollern die in 1701 naar het koninkrijk zou leiden. De onafhankelijkheid van Nederland en Zwitserland werd officieel erkend. Voor de Ottomanen is het belang indirect maar groot: toen de Habsburgers zich van het westelijke front terugtrokken, ontstond in Midden-Europa een macht die zich weer naar het oosten kon keren.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Uitroeping van het Koninkrijk Pruisen — Frederik I werd in Königsberg gekroond", "337a9f74"], "d": ["Frederik III, keurvorst van Brandenburg, werd met toestemming van keizer Leopold I in Königsberg gekroond en nam de titel «Koning in Pruisen» aan (18 januari 1701). De titel was ontleend aan Oost-Pruisen, omdat dat buiten het Heilige Roomse Rijk lag en een keurvorst die aan de keizer was gebonden slechts buiten de grenzen van het rijk koning kon worden. De verspreide gebieden van de Hohenzollern-dynastie werden vanaf deze datum onder één staatsnaam bekend.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["Sardinië ging van Spanje naar het Huis Savoye — het Koninkrijk Sardinië werd geboren", "adf778b7"], "d": ["In de laatste schakel van de regelingen die de Spaanse Successieoorlog afsloten, werd het eiland Sardinië aan Spanje ontnomen en aan het Huis Savoye gegeven; de hertog van Savoye liet in ruil Sicilië en nam de titel koning van Sardinië aan. Cagliari en Sassari kwamen zo uit het tweehonderd jaar durende Spaanse bestuur. Het ontstane Koninkrijk Sardinië is de kern van de staat die anderhalve eeuw later de Italiaanse eenheid zou vestigen — de wortel van het Koninkrijk Italië dat in 1870 Rome binnentrok, gaat dus hierop terug.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["Corsica door Genua aan Frankrijk verkocht — Verdrag van Versailles", "770343df"], "d": ["De Republiek Genua liet Corsica, dat zij eeuwenlang had bezeten maar door opstanden feitelijk niet kon controleren, aan Frankrijk. Het lemma Korsika van de TDV geeft de gebeurtenis in één zin: Genua verkocht dit eiland, waar het weinig vat op had, in 1768 aan Frankrijk. De overdracht markeert de terugtrekking van Genua uit zijn laatste grote gebiedsbezit in de Middellandse Zee; het eiland zou in 1796 enige tijd in Engelse handen komen en daarna opnieuw aan Frankrijk worden teruggegeven. Dat het eiland Frans grondgebied was, maakte Napoleon Bonaparte, die een jaar later in Ajaccio zou worden geboren, tot Frans onderdaan. In dit jaar (1768) werd Corsica, inclusief Bastia, door Genua aan Frankrijk verkocht (TDV Korsika; dag niet bevestigd).", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Verdrag van Tilsit — Pruisen verloor de helft van zijn gebied, het Hertogdom Warschau werd gesticht", "d30bb2cc"], "d": ["Na de nederlaag bij Jena-Auerstedt moest Pruisen met Napoleon in Tilsit een zware vrede aanvaarden (9 juli 1807). Het liet al zijn gebieden ten westen van de Elbe en de Poolse gebieden die het bij de delingen van 1793 en 1795 had gekregen; uit de laatste werd het Hertogdom Warschau gesticht en de omgeving van Białystok aan Rusland gegeven. Pruisen verloor ongeveer de helft van zijn bevolking en gebied en zijn leger werd beperkt tot 42.000. In de atlas gaan Poznań en Toruń vanaf deze dag naar het Hertogdom Warschau en Białystok naar Rusland. Met dit verdrag gingen Łódź en Częstochowa (de Poolse provincies die na 1772 aan Pruisen waren gekomen) naar het Hertogdom Warschau; Gdańsk (Danzig) werd een onafhankelijke vrije stad.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Italiaanse troepen trokken Rome binnen — einde van de Kerkelijke Staat en voltooiing van de Italiaanse eenheid", "a3689f2e"], "d": ["Toen de val van Napoleon III in de Frans-Pruisische Oorlog het Franse garnizoen dat Rome beschermde deed terugtrekken, trokken Italiaanse troepen de stad binnen en trok de paus zich terug in het Vaticaan. Zo kwam een einde aan de Kerkelijke Staat, die meer dan duizend jaar had bestaan, en trad het Koninkrijk Italië, dat ook Rome bij de eenheid had gevoegd, als politieke macht op het toneel van Europa en de wereld. Dit is een gebeurtenis met directe gevolgen voor de laatste halve eeuw van de atlas: het verenigde Italië is de staat die in 1911 Tripolitanië en de Dodekanesos van de Ottomanen zou nemen.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Slag bij Chelenqo — einde van het emiraat Harar en Abessijnse bezetting", "5671a0d9"], "d": ["Toen Dawud imam van Aussa werd, was Harar, dat in het midden van de door de Oromo bestuurde gebieden lag, opnieuw een onafhankelijk emiraat geworden en had deze toestand gehandhaafd tot de Abessijnse bezetting van 1887. Emir Abdullah, die de jihad had uitgeroepen, trof de Abessijnen op 7 januari 1887 met 5000 man bij Chelenqo (Çelenko); toen hij begreep dat hij zou worden verslagen, vluchtte hij naar de regio Ogaden in Zuid-Harar. De slag toonde de onevenwichtigheid tussen het met vuurwapens uitgeruste Abessijnse leger en de strijdkrachten van het emiraat en maakte een einde aan een van de laatste onafhankelijke moslimemiraten achter de Rode Zee. Harar, Jijiga en Dagahbur werden zo bij Abessinië gevoegd.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Sjah Ismails inname van Derbent — de Safawidische heerschappij bereikte de poort van de Kaukasus", "305542c4"], "d": ["Nadat Sjirvansjah Farrukh Yasar in 1500 was verslagen en gedood, waren Bakoe en Shamakhi in Safawidische handen gekomen, terwijl Derbent nog enige tijd afzonderlijk bleef. Sjah Ismail nam de stad in 1509 in en vestigde er een van de Rumlu-stammen; zo bereikte de Safawidische heerschappij de noordelijke poort van de Kaukasus, de smalle doorgang tussen de Kaspische Zee en de bergen. Met de overgang van Sjirvan onder direct Safawidisch bestuur in 1538 werd de band blijvend. Derbent zou in de veldtocht van 1578 in Ottomaanse handen komen en tot 1607 het centrum zijn van een beylerbeylik van zeven sandjaks. Het register van de TDV luidt: 'De stichting en ontwikkeling van de Safawidische staat vormde het begin van een nieuwe periode in Derbent. Sjah Ismail nam de stad in 1509 in en vestigde er een van de Rumlu-stammen. Toen Sjirvan in 1538 direct onder Safawidische heerschappij kwam...'", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Definitieve opname van Kars in Ottomaans gebied — de pin van de oostelijke grens", "6235c85a"], "d": ["Na de vernietiging van de Akkoyunlu-staat door de Safawiden was Kars enige tijd in handen van Sevündük Han Kurçibaşı van de Avşar-Turkmenen gebleven. Het is zeer waarschijnlijk dat het fort van Kars tijdens de Irakeyn-veldtocht van Süleyman (940/1534), toen de forten Pasin, Şüregel en Oltu werden ingenomen, al aan de Ottomanen werd gebonden; de definitieve aansluiting van de stad volgde echter drie jaar later. Het register van de TDV luidt: 'Kars werd definitief in 944 (1537) bij Ottomaans gebied gevoegd door Dulkadırlı Mehmed Han, die in Ottomaanse dienst was getreden.' Omdat de stad en het fort door de lange strijd grotendeels verwoest waren, werd snel met herstel begonnen; terwijl het fort in 955 (1548) werd hersteld, viel de Safawiden de stad aan en verwoestten het fort opnieuw. Kars zou daarna driehonderdveertig jaar lang het slot van de noordoostelijke grens van de Ottomanen blijven en na de oorlog van 1877-78 aan Rusland worden afgestaan.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Herovering van Nikopol — einde van de zes maanden durende Russische bezetting", "7fb299d7"], "d": ["In de Ottomaans-Russische oorlog van 1806-1812 hadden de Russische troepen die de zuidoever van de Donau overstaken Nikopol in oktober 1810 onder bevel van generaal Koetoezov ingenomen. Zes maanden later ontruimden zij de stad toen zij zagen dat zij de Donaulinie niet konden houden; voor zij vertrokken, bliezen zij een belangrijk deel van het fort op. Het register van de TDV luidt: 'In oktober van het jaar 1810 (tijdens de Turks-Russische oorlog van 1808-1812) werd Nikopol door de troepen van de beroemde Russische generaal Michail Koetoezov ingenomen. De Russen bliezen in april 1811, voor zij de stad verlieten, een belangrijk deel van het fort op en richtten grote schade aan in de stad.' Na de terugtrekking van de Russische troepen lieten de Ottomanen het fort herbouwen; het opschrift van 1813-1814 is de registratie van dit herstel.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Ontruiming van Silistra — de middelste vesting van de Donau werd met neergehaalde muren verlaten", "561628bb"], "d": ["Silistra, een van de sterkste Ottomaanse forten aan de Donau, werd in 1810 door de Russische artillerie gebombardeerd en het fort en de voorstad liepen zware schade op door de explosie van een wapenopslag. Nadat de Russen de stad hadden ingenomen, kozen zij ervoor haar niet te houden maar haar versterkingen te vernietigen: generaal Koetoezov gaf bevel de muren te slopen en meldde de tsaar in mei 1811 dat de muren van Silistra waren opgeblazen. Het register van de TDV: 'In 1810 werd de stad door de Russen gebombardeerd… Nadat de Russen de stad hadden ingenomen en voordat zij zich terugtrokken, gaf generaal Koetoezov bevel Silistra te verwoesten. In mei 1811 meldde hij de tsaar dat de muren van Silistra waren opgeblazen.' Hetzelfde fort zou in de oorlog van 1827-1828 opnieuw door de Russen worden ingenomen en dat beleg zou door Helmuth von Moltke uitvoerig worden beschreven.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Einde van de Zand-dynastie — Qajar-heerschappij in Iran", "5dda30a4"], "d": ["Met de nederlaag van Lotf Ali Khan, de laatste heerser van de Zand-dynastie, kwam in 1751 een einde aan de gestichte dynastie en kwam heel Iran in handen van Agha Mohammad Khan. De officiële stichting van de Qajar-staat wordt twee jaar later gedateerd, op de kroning van Agha Mohammad Khan tot sjahinsjah in Teheran (1796); de feitelijke macht was echter in 1794 overgenomen.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Verschillen tussen Lausanne en Sèvres: van een opgelegde vrede naar een gelijkwaardige vrede", "4b578583"], "d": ["Sèvres (10 augustus 1920) was een document dat aan de regering in Constantinopel was opgelegd en nooit in werking is getreden; Lausanne (24 juli 1923) is daarentegen de vrede die Ankara als gelijkwaardige partij ondertekende en die de TBMM op 23 augustus 1923 bekrachtigde (Lausanne art. 1, 143). Wat de grenzen betreft, trekt Sèvres de Europese grens van Turkije terug tot de Çatalca-lijn en geeft Oost-Thracië, inclusief Edirne, en Imbros en Tenedos aan Griekenland (Sèvres art. 27, 84); İzmir en omgeving blijven in naam onder Turkse soevereiniteit maar het bestuur wordt aan Griekenland overgelaten, waarbij het lokale parlement na vijf jaar kan verzoeken om aansluiting (art. 65-83). Lausanne trekt de Maritsa-Arda-lijn, Edirne en Karaağaç blijven bij Turkije, Imbros en Tenedos worden Turks (Lausanne art. 2, 12, 14; Protocol van Karaağaç). Aan de Zeestraten stelt Sèvres een internationale commissie in die zich over alle wateren uitstrekt en waarin het Turkse lid slechts met één stem zit; versterkingen worden geslecht en het gebied wordt voor Geallieerd gebruik opengesteld (Sèvres art. 36-61, 178-180). Lausanne behoudt het beginsel van vrije doorvaart maar laat een commissie onder Turks voorzitterschap, gedemilitariseerde zones en een garnizoen van 12.000 man in Constantinopel (Lausanne art. 23; Conventie van de Zeestraten). De erkenning van Armenië en de grensarbitrage door de president van de VS en het plan voor Koerdische autonomie (Sèvres art. 62-64, 88-93) komen in Lausanne niet voor. Over de Arabische gebieden, Egypte, Soedan en Cyprus bevat Sèvres gedetailleerde overdrachtsbepalingen (Sèvres art. 94-97 mandaten, art. 98-100 Hidjaz, art. 101-122 afstand van Egypte, Soedan, Cyprus, Marokko, Tunesië en Libië; ook de artikelreeksen van de TDV zijn zo); Lausanne formuleert de afstand korter, de Dodekanesos blijft bij Italië, Cyprus bij Engeland, de grens van Mosul wordt uitgesteld (Lausanne art. 3, 15-21). Sèvres herstelt en breidt de capitulaties uit, controleert met een Financiële Commissie de Turkse begroting en leningen, de gewapende macht (gendarmerie en versterkingselementen) mag niet meer dan 50.000 man bedragen en militaire en marineluchtvaart zijn verboden (Sèvres art. 155, 164, 191-195, 231-264, 261-263). Lausanne schaft de capitulaties af, verdeelt de schulden en legt geen afzonderlijke legerbeperking op (Lausanne art. 28, 46-63; art. 113 schaft ook de buitenlandse postkantoren af). De minderheidsbepalingen zijn in Sèvres ruimer en open voor Geallieerde inmenging, terwijl zij in Lausanne door de Volkenbond gegarandeerd en wederkerig zijn (Sèvres art. 140-151; Lausanne art. 37-45).\n\nVergelijking per as:\n• Oost-Thracië, Edirne, Çatalca — Sèvres: Çatalca-lijn als grens; Oost-Thracië en Edirne aan Griekenland (art. 27, 84-85) | Lausanne: grens langs de Maritsa en Arda; Edirne en Karaağaç bij Turkije (art. 2; Protocol van Karaağaç)\n• Regio İzmir — Sèvres: soevereiniteit Turks, bestuur en leger Grieks, na vijf jaar aansluitingsverzoek (art. 65-83) | Lausanne: geen specifiek statuutartikel voor İzmir; Anatolië ligt binnen de grenzen van Turkije (art. 2-3 algemene grens; geen artikelbewijs specifiek voor İzmir)\n• Zeestraten en Constantinopel — Sèvres: Internationale Commissie voor de Zeestraten, Turkije 1 stem; slechting van versterkingen, gebied in Geallieerd gebruik; Constantinopel in Turkse handen maar gebonden aan minderheidsvoorwaarde (art. 36-61, 178-180) | Lausanne: beginsel van vrije doorvaart; commissie onder Turks voorzitterschap, gedemilitariseerde zones, garnizoen van 12.000 man in Constantinopel (art. 23; Conventie van de Zeestraten)\n• Armenië en Koerdistan — Sèvres: Armenië erkend, grens bepaald door de president van de VS; Koerdische autonomie, na een jaar onafhankelijkheidsverzoek (art. 62-64, 88-93) | Lausanne: geen betreffende bepaling (komt niet voor in de samenvattingen van art. 1-143)\n• Egeïsche eilanden, Dodekanesos — Sèvres: Imbros, Tenedos en de Egeïsche eilanden aan Griekenland; Dodekanesos en Kastellorizo aan Italië (art. 84, 122) | Lausanne: Imbros en Tenedos bij Turkije, de oostelijke Egeïsche eilanden Grieks, Dodekanesos en Kastellorizo bij Italië (art. 12-15)\n• Cyprus, Egypte, Soedan, Arabische gebieden — Sèvres: mandaat over Syrië/Mesopotamië en Palestina, Hidjaz onafhankelijk; protectoraat over Egypte, Soedan, annexatie van Cyprus erkend (art. 94-98, 101-117) | Lausanne: de grens met Syrië volgens de Frans-Turkse overeenkomst van 1921, de grens met Irak later; afstand van Egypte, Soedan, Cyprus (art. 3, 16-20)\n• Capitulaties — Sèvres: herstel en uitbreiding; plan voor gerechtelijke hervorming in een Geallieerde commissie (art. 136, 261-263, 308-309) | Lausanne: volledig afgeschaft; buitenlandse postkantoren en de Hoge Gezondheidsraad vervallen (art. 28, 113-114)\n• Financieel toezicht en schulden — Sèvres: Geallieerde Financiële Commissie controleert begroting en leningen, Düyun-ı Umumiye breidt uit, bronnen als onderpand (art. 231-264) | Lausanne: Düyun-ı Umumiye verdeeld over de staatsaandelen; oorlogsschade wederzijds kwijtgescholden (art. 46-63, 58)\n• Militaire beperkingen — Sèvres: leger 50.000 man, luchtmacht en tanks verboden, Geallieerde Controlecommissies (art. 152-207) | Lausanne: geen algemene beperking; alleen ontwapening op de Griekse eilanden en in Zeestraten-Thracië-gebieden (art. 13; conventies over de Zeestraten en Thracië)\n• Minderheden — Sèvres: Geallieerde garantie en interventierecht, annulering van Emval-i Metruke, teruggave (art. 140-151, 86, 142-144) | Lausanne: door de Volkenbond gegarandeerde rechten voor niet-moslimse minderheden, wederzijdse moslimrechten in Griekenland; Grieks-Turkse bevolkingsruil (art. 37-45; Conventie inzake de Ruil)\n• Juridische status — Sèvres: ondertekend door de regering in Constantinopel, door Ankara verworpen, niet in werking getreden (TDV) | Lausanne: gelijkwaardige partij; bekrachtiging door de TBMM op 2 augustus 1923, 213 voor, 14 tegen (TDV; art. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Dood van Timoer Sjah, troonsbestijging van Zaman Sjah (Durrani-rijk)", "c3effdb2"], "d": ["Na de dood van Timoer Sjah, die het land ruim twintig jaar van binnenuit had geconsolideerd, betwistten drie broers, de gouverneurs van Kandahar, Herat en Kabul, de troon; Zaman Sjah, de gouverneur van Kabul, die de hoofdstad in handen had, werd op 20 mei 1793 sjah. Deze opvolgingscrisis is feitelijk het begin van het desintegratieproces van de dynastie.", "4b3d7d19"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["De Volksrepubliek Chorezm werd uitgeroepen", "0a6b79f9"], "d": ["Na de omverwerping van de khan van Chiva na de Oktoberrevolutie van 1917 werd de Volksrepubliek Chorezm uitgeroepen.", "1934b071"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Het Rode Leger trok de stad Boechara binnen — de laatste emir Alim Khan van de troon verwijderd", "f8f5bfcf"], "d": ["Het Rode Leger trok op 2 september 1920 de stad Boechara binnen en de laatste Mangit-emir Alim Khan werd van de troon verwijderd. De emir trok zich terug naar het oosten van het land, naar Dosjanbe, en leidde van daaruit een half jaar lang de strijd tegen de Sovjets; het Rode Leger nam Dosjanbe op 21 februari 1921 in, waarna de emir verder naar het oosten en vandaar naar Afghanistan trok. Het khanaat werd officieel op 6 oktober 1920 afgeschaft (zie Volks-Sovjetrepubliek Boechara).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["De Volks-Sovjetrepubliek Boechara werd uitgeroepen", "ef579627"], "d": ["Nadat het Rode Leger op 28-31 augustus 1920 het emiraat Boechara had vernietigd en emir Alim Khan naar Oost-Boechara had doen vluchten, werd onder leiding van Fajzoellah Choedjajev de Volks-Sovjetrepubliek Boechara uitgeroepen.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["De Volksrepubliek Tannu-Toeva riep haar onafhankelijkheid uit", "8710ea3d"], "d": ["Onder leiding van de Toevaanse Revolutionaire Volkspartij werd de onafhankelijkheid uitgeroepen; het eerste artikel van de eerste grondwet bepaalde dat de staat 'in internationale betrekkingen onder de bescherming van Sovjet-Rusland' handelde. Met deze gebeurtenis ging Kyzyl (Belotsarsk, Tannu-Toeva) over naar de Volksrepubliek Tannu-Toeva.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["De nieuwe grondwet van de Volks-Sovjetrepubliek Boechara werd aangenomen", "fb17bf39"], "d": ["Er werd een nieuwe grondwet aangenomen die, anders dan de Russische grondwet van 1918, particulier bezit van grond en productiemiddelen toestond en ook niet-proletariërs stemrecht verleende (met uitzondering van de verwanten van de afgezette emir en de grootgrondbezitters).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Omvorming tot Chorezmse Socialistische Sovjetrepubliek", "14a1d26f"], "d": ["Het land veranderde zijn naam en status en werd de Chorezmse Socialistische Sovjetrepubliek; de bestuurlijk-juridische structuur werd herschikt volgens het Sovjetsysteem.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["De regering van Tannu-Toeva trad feitelijk in functie", "22ea1516"], "d": ["De regering, gevormd na de eerste partijvergadering van februari 1922, trad feitelijk in functie.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["De eerste Grote Choeral van Tannu-Toeva kwam bijeen", "80fe15f2"], "d": ["De eerste Grote Choeral (Volksvergadering) van het land kwam bijeen; dit is de eerste grote representatieve bijeenkomst in het proces van institutionalisering van de staat.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Het einde van de Chorezmse SSR en de Volks-Sovjetrepubliek Boechara door nationale afbakening — oprichting van de Oezbeekse en Turkmeense SSR's", "e8c8ab4f"], "d": ["Bij besluit van de Sovjet-'nationale afbakening' (natsionalno-territorialnoe razmezjevanie) werden de Chorezmse Socialistische Sovjetrepubliek en de Volks-Sovjetrepubliek Boechara afgeschaft; hun gebieden werden verdeeld tussen de nieuw opgerichte Oezbeekse en Turkmeense Socialistische Sovjetrepublieken (het oosten van Chiva aan Oezbekistan, het westen aan Turkmenistan). Het lemma `harizm` van de TDV: 'In 1924 werden de oostelijke delen van het khanaat Chiva aan de Oezbeekse Socialistische Sovjetrepubliek en het westelijke deel aan de Turkmeense Socialistische Sovjetrepubliek overgelaten.' — geeft alleen het jaar.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Verkoop van Alanya aan de Mamelukse sultan Barsbay", "c8bd35f2"], "d": ["Alanya, dat in 1293 door de Karamanoglu Mecdüddin Mahmud Bey was veroverd, was een afzonderlijk beylik geworden dat door een tak van de Karamanoglu's werd bestuurd; Ibn Battuta vermeldt dat het bestuur in 1333 bij Karamanoglu Yusuf Bey lag. Karaman b. Savci Bey verkocht de stad in 1427 voor vijfduizend goudstukken aan de Mamelukse sultan Barsbay en Alanya kwam onder Mamelukse heerschappij. Deze sleutelhaven van de Middellandse Zee werd zo in handen van de Mamelukken een obstakel op de weg van de Ottomanen naar het zuiden; toen Gedik Ahmed Pasja de stad in 1471 belegerde, gaf de laatste bey Kilicarslan de stad over.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Tabarka op de Genuezen veroverd — einde van het Lomellini-koraalmonopolie", "b1f33eb5"], "d": ["Na het verdrag dat Karel V in 1544 met de bey van Tunis sloot, hadden de Genuese Lomellini zich op het eiland Tabarka gevestigd en tweehonderd jaar lang het koraalmonopolie in handen gehouden; het eiland bleef midden in het Ottomaanse Tunis een christelijke handelspost. Ali Pasja van de Husseiniden-dynastie, die hoorde dat de familie het eiland wilde afstoten, stuurde troepen en nam het eiland op 12 juni 1741 in; ongeveer vijftienhonderd christenen werden naar Tunis overgebracht. Tabarka kwam vanaf deze datum onder het bestuur van de ocak van Tunis.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Slag bij de Piramiden en inname van Caïro door de Fransen", "3ddd6b96"], "d": ["Napoleon trok vanuit Alexandrië langs de Nijl naar het zuiden en trof op 21 juli 1798 bij Imbaba tegenover Gizeh de Mamelukse cavalerie van Murad Bey. De Franse infanterie in carrévorm brak de cavalerieaanvallen; het Mamelukkenleger werd verstrooid en Caïro gaf zich twee dagen later zonder verzet over. Murad Bey trok zich terug naar Boven-Egypte en Ibrahim Bey naar Syrië. De Fransen richtten in Caïro een diwan op en probeerden het bestuur via de ulema te voeren; in oktober 1798 en maart 1800 braken twee grote opstanden in Caïro uit.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Napoleons beleg van Akko — stopzetting van de Syrische veldtocht", "d2a947ad"], "d": ["Napoleon, die de door het Ottomaanse Rijk voorbereide strijdkrachten om Egypte terug te nemen wilde verstrooien, trok begin 1799 naar Syrië; hij nam El Arish op 18 februari, Jaffa in maart en belegerde Akko op 18 maart 1799. De verdediging van Cezzar Ahmed Pasja en de steun van de Britse admiraal Sidney Smith vanaf zee doorbraken het beleg twee maanden lang; omdat de belegeringskanonnen op zee waren buitgemaakt, konden de muren niet worden overwonnen. Napoleon trok zich in mei terug en deze nederlaag werd het uiterste punt van de Franse bezetting.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Stichting van de staat van emir Abd al-Qadir — centralisering van het verzet in West-Algerije", "9e482383"], "d": ["Het verzet, dat na de val van Algiers uiteen was gevallen, verzamelde zich rond de jonge Abd al-Qadir, zoon van de Qadiri-sjeik Muhyi al-Din; op 22 november 1832 zwoeren stamhoofden bij Muaskar hem trouw met de titel 'emir al-mu'minin'. De structuur die hij schiep was geen stammenbond maar een geregelde staat: hij had een munt, een buskruitfabriek, een belastingstelsel en een hoofdstad in Tagdempt. Frankrijk erkende zijn gezag officieel met het Verdrag van de Tafna van 1837. Abd al-Qadir zocht zijn toevlucht niet bij de Ottomanen maar onder de suzereiniteit van de Marokkaanse sultan Abd al-Rahman; deze gebieden waren na 1832 dus geen Ottomaanse onderdanen. Op 23 december 1847 gaf hij zich over en in hetzelfde jaar verklaarde ook het Ottomaanse Rijk dat zijn rechten op Algerije waren beëindigd.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Val van Constantine — einde van het beylik van Oost-Algerije", "159fed36"], "d": ["Na de val van Algiers in 1830 viel het oostelijke beylerbeylik niet uiteen: de laatste bey, Ahmed, zette zijn eigen bestuur in Constantine voort en verklaarde namens de Ottomanen te handelen. De eerste Franse expeditie van 1836 eindigde in een nederlaag; de tweede expeditie belegerde de stad op 6 oktober 1837, bevelhebber Damrémont werd op 12 oktober door kanonvuur gedood en op 13 oktober werden de muren overwonnen en werd de stad straat voor straat ingenomen. Ahmed Bey trok zich terug in de bergen en gaf zich pas in 1848 over. Deze datum is het feitelijke einde van het driehonderd jaar durende Ottomaans-Turkse bestuur in het oosten van Algerije.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Verovering van de regio Taka en stichting van Kassala", "cc3e0631"], "d": ["Ahmed Pasja Abu Widan, heerser van Soedan, voegde in 1840 de regio Taka tussen de rivieren Atbara en Gash bij het Egyptische bestuur en stichtte de stad Kassala als militair hoofdkwartier. De stad werd een mudiriyya-centrum dat de karavaanroute tussen Sennar en Suakin en de Abessijnse grenszone controleerde.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Franse bezetting van Muaskar (Mascara) — verlies van de hoofdstad van Abd al-Qadir", "bd363c05"], "d": ["Met de komst van Bugeaud als gouverneur in 1841 veranderde de Franse strategie: in plaats van zich aan de kust te handhaven, werden de steden in het binnenland een voor een bezet. Mobiele colonnes vanuit Oran, Mostaganem en Médéa namen de centra van Abd al-Qadirs geregelde staat in; Muaskar, een echte hoofdstad met een munt, een buskruitfabriek en graanmagazijnen, was de belangrijkste daarvan. De emir gaf daarna het vestigen van een vast centrum op en veranderde zijn leger in een nomadisch kamp, de 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Bezetting van de Chélif-vallei en Ténès — stichting van Orléansville", "e1eeeb68"], "d": ["Om Abd al-Qadir te kunnen achtervolgen stichtten de Fransen in april 1843 midden in de Chélif-vallei een nieuwe stad, Orléansville; in hetzelfde jaar werd ook de kusthaven Ténès bezet. Zo kwam de binnenlandse corridor tussen Algiers en Oran onder Frans gezag en werd het verzet in het Dahra-gebergte omsingeld. Op 16 mei van hetzelfde jaar werd Abd al-Qadirs nomadische kamp, de 'smala', bij toeval gevonden en uiteengedreven.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Stichting van het versterkte kamp Sidi Bel Abbès", "fb33ec29"], "d": ["Bugeaud beval generaal Bedeau op 12 juni 1843 in Sidi Bel Abbès een versterkt kamp met gracht en muren aan te leggen; de bouw begon op 18 juni en in november van hetzelfde jaar vestigde zich er een bataljon van het Vreemdelingenlegioen. Het kamp werd een permanente basis die de binnenlandse vlakte tussen Oran en Tlemcen controleerde.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Overgang van Nedroma en de Marokkaanse grenszone onder Frans gezag", "61d821f3"], "d": ["Nadat Abd al-Qadir zich in 1843 naar Marokko had teruggetrokken, kwamen Nedroma ten noordwesten van Tlemcen en de kust van Traras onder Frans gezag. De Slag bij Isly op 14 augustus 1844 bracht het Marokkaanse leger een nederlaag toe en de grens tussen beide landen werd getrokken met de Conventie van Lalla Maghnia van 18 maart 1845; Nedroma bleef aan de Algerijnse kant van deze lijn.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Val van Aghouat (Laghouat) — opening van de poort naar de Sahara", "b161b32c"], "d": ["Generaal Pélissier belegerde Aghouat op 21 november 1852 met een macht van zesduizend man en op 4 december viel de stad na een bloedige bestorming. Aghouat was een oasestad die de overgang tussen de Tell en de Sahara bewaakte; haar val opende de Franse opmars naar de woestijnkaravaanroutes en bereidde de onderwerping van de Mzab-confederatie aan belasting binnen een jaar voor.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Annexatie van de regio Bogos (Keren) door Egypte", "b2ab83ce"], "d": ["Werner Munzinger Pasja, gouverneur van de provincie 'Oost-Soedan en de Rode Zeekust', door khedive Ismail aan de westkust van de Rode Zee opgericht, voegde in 1872 de regio Bogos, waar het Bilen-volk woont, en het centrum Keren bij Egypte. Dit was de duurzaamste opmars van Egypte naar de rand van het Abessijnse hoogland en leidde tot een grensgeschil met Abessinië dat twaalf jaar duurde.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Annexatie van het sultanaat Darfoer door Egypte — Zubayr Pasja trok El-Fasher binnen", "f41268ed"], "d": ["Zubayr Rahma Pasja, die sterk was geworden door de handel in ivoor en slaven, verstrooide op 25 oktober 1874 bij Manawashi met strijdkrachten die hij met Remington-geweren had uitgerust het Fur-leger; sultan Ibrahim sneuvelde in de slag. Zubayr trok op 2 november zonder gevecht El-Fasher binnen en de heerschappij van de Keira-dynastie, die sinds 1603 had geduurd, kwam feitelijk ten einde. Darfoer werd zo bij de Soedanese provincies van het Egypte van Mehmet Ali gevoegd; maar het verzet van de Keira-familie in de bergen duurde tot 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Annexatie van de Mzab-oases (Ghardaïa)", "9372959f"], "d": ["De Ibadi-steden van de Mzab hadden in 1852 ingestemd met het betalen van belasting aan Frankrijk, maar hun interne bestuur behouden; dertig jaar later, in 1882, werd de regio rechtstreeks bij Frans grondgebied gevoegd en werd Ghardaïa onder militair bestuur geplaatst. Zo kwam ook juridisch een einde aan de laatste autonome zone van de noordelijke Sahara.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Bombardement van Alexandrië en Britse landing", "18d57bf8"], "d": ["Toen de officiersbeweging onder leiding van Urabi Pasja de khedive onder controle bracht, greep Engeland in onder het voorwendsel van de veiligheid van de Suezroute. De vloot van admiraal Seymour bombardeerde op 11-12 juli 1882 de kustbatterijen van Alexandrië; na de brand en plundering in de stad gingen op 15 juli Britse troepen aan land. Het Ottomaanse Rijk kon deze operatie in een provincie waarover het juridisch soeverein was niet verhinderen en liet ook de oproep om aan de interventie deel te nemen onbeantwoord. Zo was de eerste stap gezet van een bezetting die tweeëndertig jaar zou duren.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Slag bij Tel el-Kebir — ontbinding van het leger van Urabi", "8e38fecf"], "d": ["Wolseley liet zijn troepen via het Suezkanaal bij Ismaïlia landen en door de woestijn marcheren; bij het ochtendgloren van 13 september 1882 overviel hij de Egyptische loopgraven bij Tel el-Kebir; de slag was in een uur voorbij. Urabi gaf zich de volgende dag over en de Britse cavalerie trok dezelfde dag Caïro binnen. Vanaf deze datum kwamen de financiën, het leger en de buitenlandse zaken van Egypte feitelijk onder Brits gezag; de Ottomaanse soevereiniteit duurde juridisch nog tot 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Conventie van La Marsa — voltooiing van het protectoraat over Tunesië", "71338640"], "d": ["Het Verdrag van Bardo (Qasr al-Said) van 12 mei 1881 had de buitenlandse zaken van Tunesië aan Frankrijk overgelaten maar het interne bestuur aan de bey; de Conventie van La Marsa, twee jaar later op 8 juni 1883 ondertekend, plaatste ook de financiële en bestuurlijke hervormingen onder Frans toezicht en voltooide het protectoraat. Het Ottomaanse Rijk hield zijn aanspraak op soevereiniteit over Tunesië aan en erkende de bezetting nooit, maar kon geen feitelijke tegenmaatregel nemen. Zo kwam Tunesië, sinds 1574 een Ottomaanse ocak, officieel onder Frans protectoraat.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Debacle van Shaykan — vernietiging van het leger van Hicks Pasja", "a0e08986"], "d": ["Hicks Pasja, een gepensioneerde Britse officier die het bevel voerde over een uit Caïro gestuurde Egyptische macht van ongeveer tienduizend man, werd op 5 november 1883 bij Shaykan door de Mahdistische strijdkrachten omsingeld terwijl hij zonder water en zonder gidsen door de woestijn van Kordofan trok, en het leger werd bijna volledig vernietigd. Deze nederlaag brak de ruggengraat van het Egyptische bestuur in Soedan: binnen een maand gaven Darfoer en Bahr al-Ghazal zich over en ging heel Kordofan over naar de Mahdi. De weg naar de val van Khartoem begint hier.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Overgang van Darfoer naar de strijdkrachten van de Mahdi — overgave van Slatin Pasja", "6d8992d4"], "d": ["Slatin Pasja, gouverneur-generaal van Darfoer, had sinds 1882 te maken met de mahdistische opstand van de Rizeigat-stam; omdat hij dacht dat de nederlagen van zijn soldaten werden toegeschreven aan zijn christen-zijn, werd hij in 1883 openlijk moslim en nam de naam Abd al-Qadir aan. Nadat het leger van Hicks Pasja in november 1883 in Kordofan was vernietigd, had verzet geen zin meer en op 23 december 1883 gaf hij zich over aan emir Madibbo. De kleine Egyptische garnizoenen in Darfoer volgden spoedig dezelfde weg; het tien jaar durende Turks-Egyptische bestuur was voorbij. Met deze gebeurtenis ging Djebel Marra (Darfoer) over naar het bestuur van de Mahdistische staat.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Overgang van Zeila en de Somalische kust onder Brits bestuur", "1d649502"], "d": ["Toen de Mahdi-opstand de Egyptische garnizoenen in Soedan en aan de Rode Zee deed instorten, moest Caïro zijn verre posten aan de Abessijnse kust ontruimen. Het Britse bestuur in Aden landde in 1884 troepen in Zeila en Berbera; het jaar daarop werden beschermingsverdragen gesloten met de Somalische stamhoofden en werd Brits Somaliland gesticht. Zeila, dat sinds 1559 bij de provincie Habesh hoorde, ging zo verloren.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Overgave van het garnizoen van Fasher aan de Mahdisten", "68f0760d"], "d": ["Ook na de overgave van Slatin op 23 december 1883 bleef het Egyptische garnizoen in het fort van Fasher weerstand bieden. Het garnizoen, dat tijdens een zeven dagen durende belegering de putten verloor, gaf zich op 15 januari 1884 over; de wapens werden neergelegd en het fort ging over naar de Mahdisten.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Verdrag van Hewett (Adwa) — Bogos aan Abessinië afgestaan", "0de1b701"], "d": ["Toen de Mahdi-opstand de Egyptische garnizoenen in Soedan omsingelde, sloot Engeland op 3 juni 1884 in Adwa een verdrag met Yohannes IV om de hulp van Abessinië te verkrijgen. Het tweede artikel van het verdrag gaf Bogos terug aan Abessinië, in ruil waarvoor Abessinië de evacuatie van de omsingelde garnizoenen via Massawa mogelijk maakte. Keren kwam zo uit twaalf jaar Egyptisch bestuur; vijf jaar later zou de regio bij Italiaans Eritrea worden gevoegd.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Heroverening van Dongola — begin van de expeditie langs de Nijl", "f63aa14f"], "d": ["Na de Italiaanse nederlaag bij Adwa liet Engeland het Egyptische leger onder Kitchener langs de Nijl naar het zuiden oprukken. Naarmate de spoorlijn in de woestijn vorderde, werd het bevoorradingsprobleem opgelost en op 23 september 1896 werd de provincie Dongola heroverd. Het elf jaar durende Mahdistische bestuur kwam hier ten einde; de expeditie zou nog twee jaar duren voordat zij Omdurman bereikte.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Slag bij Omdurman — ondergang van de Mahdistische staat", "28dff7b2"], "d": ["Het Brits-Egyptische leger van Kitchener, uitgerust met artillerie en machinegeweren, verstrooide op 2 september 1898 voor Omdurman in enkele uren de strijdkrachten van kalief Abdullahi al-Ta'aishi. De volgende dag werd Khartoem binnengetrokken en werd de vlag gehesen in het paleis waar dertien jaar eerder Gordon was gedood. De hoofdstad van de Mahdistische staat viel; de kalief werd eind 1899 tijdens een achtervolging gedood. De feitelijke heerschappij wisselt op deze datum van hand — 19 januari 1899 is de overeenkomst die het juridische kader van het bestuur vestigt. Door deze nederlaag van de Mahdistische staat ging Darfoer (El-Fasher, Nyala, Geneina, Kutum enz.) over naar het sultanaat Darfoer, dat Ali Dinar opnieuw had gevestigd.", "ad27827a"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Condominiumovereenkomst — gezamenlijk Brits-Egyptisch bestuur over Soedan", "8033c688"], "d": ["De overeenkomst die vier maanden na Omdurman in Caïro werd ondertekend, plaatste Soedan onder de naam 'Anglo-Egyptisch Soedan' onder gezamenlijk bestuur van de twee staten: twee vlaggen zouden samen worden gehesen en de gouverneur-generaal zou door de khedive worden benoemd met toestemming van Engeland. In de praktijk was het bestuur volledig in Britse handen. Het Ottomaanse Rijk, dat beweerde dat zijn rechten op Soedan via Egypte aan hemzelf toekwamen, werd geen partij bij de overeenkomst en erkende haar niet; maar bleef feitelijk buiten spel. Met deze overeenkomst gingen de Soedanese gebieden ten zuiden van de 22e breedtegraad (Dongola, Khartoem, Sennar, Kordofan, de kust van Suakin enz.) over naar het gezamenlijke Brits-Egyptische bestuur (Anglo-Egyptisch Soedan).", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Italiaanse landing bij Tobroek — eerste bezetting in Tripolitanië", "44780018"], "d": ["Italië verklaarde op 29 september 1911 de oorlog en zijn vloot blokkeerde op 25-26 september de kust. De eerste landoperatie vond op 8 oktober plaats bij Tobroek: het kleine Ottomaanse garnizoen trok zich terug naar het binnenland en de haven werd zonder gevecht bezet. Tobroek was de Ottomaanse haven die het dichtst bij de Egyptische grens lag; haar val opende de oostelijke flank van Cyrenaica en maakte de Italiaanse opmars langs de kust naar het westen gemakkelijker.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Overgave van de stad Tripoli aan de Italianen", "785091ad"], "d": ["Tripoli gaf zich op 9 oktober 1911 over na drie dagen bombardement. De Ottomaanse troepen kozen ervoor de stad niet te verdedigen maar zich terug te trekken naar Aziziya en Gharyan en in het binnenland het verzet te organiseren; dit verzet, waaraan Enver en Mustafa Kemal Bey deelnamen, hield de Italianen tot het einde van de oorlog opgesloten in de kuststrook. Hoewel de stad viel, bleef het binnenland van de provincie dus onder Ottomaanse controle.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Verlies van Derna door de Italiaanse landing", "f014c741"], "d": ["Na Tobroek was Derna, de tweede haven van Cyrenaica, aan de beurt; de stad werd op 16 oktober 1911 bezet. Het plateau rond Derna was het gebied waar de Senoessi-orde het sterkst was, en de strijders die op de jihadoproep van sjeik Ahmed Sharif waren samengekomen, hielden de Italianen omsingeld rond de haven. De bezetting bleef beperkt tot de stad en kon zich nooit naar het achterland uitbreiden.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Italiaanse landing bij Benghazi — verlies van het centrum van de sandjak Barka", "f9183c40"], "d": ["Benghazi, het centrum van Barka, werd op 21 oktober 1911 bezet met de vierde en belangrijkste landing aan de kust. Zo hield Italië drie weken na de oorlogsverklaring alle grote havens van de provincie Tripolitanië (Tripoli, Tobroek, Derna, Benghazi) in handen, maar kon in geen ervan het achterland binnendringen. Het resterende jaar van de oorlog verliep met vruchteloze uitvallen vanuit deze vier punten aan de kust naar het binnenland.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Het eenzijdige annexatiedecreet van Italië", "cfe3f9c2"], "d": ["Italië verklaarde bij decreet van 5 november 1911, terwijl de oorlog nog gaande was, dat het Tripolitanië en Barka had geannexeerd. Het Ottomaanse Rijk erkende dit niet en de oorlog duurde nog een jaar; de annexatie kreeg pas rechtsgeldigheid met het Verdrag van Ouchy van 18 oktober 1912. Het decreet verandert daarom de Ottomaanse kleur op de kaart niet — de juridische eigendom ligt tot 1912 bij de Ottomanen, de Italiaanse controle wordt als gearceerde bezetting weergegeven.", "23668758"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Vertrek van Süleyman de Wetgever naar de Wenen-veldtocht — de Habsburgse oorlog begon opnieuw", "f7afd2a9"], "d": ["Na Mohács was de Hongaarse troon in tweeën gedeeld; Ferdinand had in 1527 Buda ingenomen en Szapolyai uit de hoofdstad verdreven. De padisjah trok voor de vierde keer ten strijde om Szapolyai te steunen en de Habsburgse opmars te stoppen; vóór de veldtocht kreeg grootvizier İbrâhim Pasja de titel van seraskier en het beylerbeylik Rumelië, en alle planning werd met hem gedaan. Langs de weg vertraagden hevige regens de opmars van het leger; de veldtocht ging voort met de inname van Buda en de overgave daarvan aan Szapolyai en de belegering van Wenen.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Vernieuwing van de vrede met de Habsburgers — einde van de oorlog om Transsylvanië en Temesvár", "97071975"], "d": ["De oorlog die begon toen Transsylvanië in 1551 aan Ferdinand overging en die voortduurde met campagnes zoals de verovering van Temesvár en de belegering van Eger, werd afgesloten met het besluit de vrede met de Habsburgers voort te zetten. De overeenkomst vernieuwde wederzijds de oude verplichtingen van beide partijen; maar zij bracht geen oplossing voor de wanordelijkheden langs de grenzen en na de dood van Ferdinand in 1564 namen de gebeurtenissen in Transsylvanië weer toe.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["Laatste veldtocht van Süleyman de Wetgever — vertrek uit Constantinopel met Szigetvár en Eger als doel", "31277d21"], "d": ["Na de dood van Ferdinand in 1564 en de troonsbestijging van Maximiliaan II waren de gevechten aan de Transsylvanische grens toegenomen. In de veldtocht die de oude padisjah met Sokullu Mehmed Pasja plande, zouden de forten Szigetvár en Eger het doel zijn en de keizer zou worden geïntimideerd. Nadat hij had gebeden in het mausoleum van Eyüp Sultan, verliet hij Constantinopel met een grote ceremonie; op 15 mei bereikte hij Edirne, op de vijftigste dag van zijn tocht bereikte hij Belgrado. Dit was zijn laatste vertrek uit de hoofdstad, die hij niet meer zou zien.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Verdrag van Edirne — einde van de oorlogstoestand met de Habsburgers", "d08883e3"], "d": ["In aanwezigheid van Selim II, die na de veldtocht van Szigetvár in Edirne overwinterde, waren gezanten van de Habsburgers, de Safaviden, Polen, Frankrijk en Venetië aanwezig. Besloten werd de vrede met de Safaviden voort te zetten; het verdrag dat een einde maakte aan de oorlogstoestand met de Habsburgers werd ondertekend. In deze zaken was de invloed van grootvizier Sokullu Mehmed Pasja groot.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Besluit tot de Iraanse veldtocht — twee opperbevelhebbers aangesteld tegen de door de dood van Tahmasp geschokte Safaviden", "1f09b186"], "d": ["De Safaviden waren door de vergiftiging van Sjah Tahmasp I in 1576 als gevolg van twisten tussen leden van de dynastie en de staatsnotabelen in grote verwarring gestort; dit bepaalde de richting van de te openen veldtocht. Lala Mustafa Pasja kreeg de opdracht Iran binnen te vallen vanaf Erzurum, Koca Sinan Pasja vanaf Bagdad. Toen de twist tussen de twee viziers toenam, greep Sokullu in: Sinan Pasja werd ontslagen, Lala Mustafa Pasja kreeg via Georgië de verovering van Shirvan opgedragen. Dit besluit is de opening van de Osmaans-Safavidische oorlog van 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Cigalazâde Sinan Pasja trok ten strijde tegen Iran", "1e90763e"], "d": ["Terwijl de oorlog op twee fronten met Iran en Oostenrijk voortduurde, had Sjah Abbas Erevan belegerd en ingenomen, was Kars binnengetrokken, maar kon voor Akhaltsikhe worden gestopt. Cigalazâde Sinan Pasja, aangesteld als oostelijk opperbevelhebber, vertrok met vertraging uit Constantinopel en bereikte op 8 november Kars. Hoewel de situatie gunstig was, trok hij niet tegen de sjah op en overwinterde in Van, en toen de sjah aanviel, trok hij zich terug naar Erzurum; een veldtochtseizoen ging verloren.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Nederlaag van Cigalazâde Sinan Pasja bij het Urmiameer (Sufiyan)", "7438fec4"], "d": ["De positie van Sinan Pasja, die in het veldtochtseizoen van 1605 optrok om Tabriz te heroveren, werd geschokt doordat de beylerbey van Erzurum, Köse Sefer Pasja, apart van het hoofdleger optrok en gevangen werd genomen. Een plotselinge aanval van Sjah Abbas bracht het leger bij het Urmiameer een zware nederlaag toe; Sinan Pasja trok zich eerst terug naar Van, daarna naar Diyarbekir. Dat hij de beylerbey van Aleppo, Canbolatoğlu Hüseyin Pasja, liet executeren omdat die te laat hulp bracht, ontstak in Anatolië een grote opstand; na de dood van Sinan Pasja nam Sjah Abbas Ganja, Shirvan en Shamakhi in.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Veldtocht van Kuyucu Murad Pasja naar Tabriz — geen treffen bij de Acıçay", "3c0a0a5d"], "d": ["Grootvizier Kuyucu Murad Pasja, die de Celali-opstanden had onderdrukt en rust in Anatolië had hersteld, trok via Erzurum, Hasankale, Çaldıran en Hoy tegen Sjah Abbas op, van wie bekend was dat hij in Tabriz wachtte. De twee legers stonden bij de plek Acıçay ten noorden van Tabriz tegenover elkaar maar er was geen gevecht; de briefwisseling ging voort. Toen de winter naderde en munitie en proviand schaars werden, trok de pasja zich via Ahlat, Van en Bitlis terug naar Diyarbekir en stierf daar het volgende jaar, bezig met de voorbereiding van een nieuwe veldtocht (5 augustus 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["De Osmaans-Safavidische oorlog begon opnieuw — grootvizier Öküz Mehmed Pasja trok op naar het oosten", "ef32fa31"], "d": ["Toen na het Verdrag van Nasuh Pasja van 1612 geen bericht kwam van İncili Mustafa Çavuş, die als gezant naar Iran was gestuurd, kreeg grootvizier Mehmed Pasja de opdracht tot de veldtocht naar het oosten en stak, na zijn voorbereidingen te hebben voltooid, over naar Üsküdar. Net op het moment van vertrek kwam het bericht dat İncili Çavuş en de Iraanse gezant Burun Kasim Khan met een overeenkomst en geschenken Van hadden bereikt, maar de veldtocht werd niet uitgesteld. De grootvizier bracht de winter door in Aleppo.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Belegering van Erevan — na vijfenvijftig dagen zonder resultaat opgeheven", "64a4ecb6"], "d": ["De grootvizier, die in april 1616 met een groot leger uit Aleppo vertrok, bereikte via de weg Erzurum-Kars Erevan. In de veronderstelling dat het fort gemakkelijk zou capituleren, waren geen zware kanonnen meegebracht; de belegering duurde vijfenvijftig dagen zonder materiaal. Nadat janitsarenaga Muslu Ağa en Tekeli Mehmed Pasja waren gesneuveld, de soldaten onwillig waren en het seizoen vorderde, werd de belegering opgeheven en trok het leger zich terug naar Erzurum. Mehmed Pasja werd in november 1616 ontslagen, Halil Pasja volgde hem op.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Nederlaag bij Serav (Pul-i Shikaste) — veldtocht van Halil Pasja naar Iran", "d323ed03"], "d": ["Halil Pasja, die opperbevelhebber werd in plaats van Öküz Mehmed Pasja, trok in 1618 opnieuw tegen Iran op. De slag bij de plek Pul-i Shikaste tussen Tabriz en Ardabil eindigde met een nederlaag van het Osmaanse leger. Na deze nederlaag, in de bronnen ook de Slag bij Serav genoemd, werd in dezelfde maand het Verdrag van Serav ondertekend.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["Belegering van Bagdad door Hâfız Ahmed Pasja — duurde zeven maanden en twintig dagen, zonder resultaat", "764acb0a"], "d": ["De Osmanen, die Bagdad in 1623 hadden verloren, trokken onder bevel van grootvizier en opperbevelhebber Hâfız Ahmed Pasja op om de stad te heroveren. Toen in de in Kirkuk bijeengeroepen raad het voorstel om eerst de passen te bezetten niet werd aanvaard, belegerde het leger direct Bagdad. De pasja ging persoonlijk de loopgraven in; hoewel op de tweeënzeventigste dag de stad werd binnengedrongen via een opgeblazen mijn, werden de soldaten teruggeslagen. Toen Sjah Abbas in maart 1626 met 30.000 man te hulp kwam, zat het leger tussen twee vuren; bij de aanval van de sjah op 7 juni werden zware verliezen geleden. Toen de voorraden op waren en hitte en koorts de soldaten decimeerden, werd de belegering opgeheven en trok het leger zich terug naar Diyarbekir.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["Belegering van Bagdad door Hüsrev Pasja — na negenendertig dagen opgeheven", "18de5581"], "d": ["Grootvizier Hüsrev Pasja, die na de overwinning bij Mihriban (5 mei 1630) Hamadan was binnengetrokken en de stad in brand stak en verwoestte, keerde, in plaats van tegen Qazvin op te trekken, op besluit van de krijgsraad in Dergezin terug naar het eigenlijke doel, Bagdad. Het leger, dat begin augustus de omgeving van Bagdad bereikte, belegerde de stad op 6 oktober. Bij de uitval van het Iraanse garnizoen op 26 oktober en bij de algemene aanval van 9 november werden grote verliezen geleden; ook deze tweede belegering na het verlies van Bagdad werd zonder resultaat opgeheven. Het leger trok zich terug naar Mosul.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Lepanto werd krachtens Karlowitz aan de Osmanen teruggegeven", "9ca4f9dd"], "d": ["Lepanto, dat na lange tegenstand tijdens de oorlogen van 1683-1699 in juli 1687 met de forten ernaast aan Venetië viel, bleef tot een jaar na het Verdrag van Karlowitz in handen van de Venetianen en keerde daarna terug naar de Osmanen. Het fort aan de ingang van de Golf van Korinthe kwam zo vijftien jaar vóór de Morea weer onder Osmaans bestuur.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Topal Osman Pasja versloeg Nadir bij Dücum — belegering van Bagdad opgeheven", "7ae1fc9e"], "d": ["Tegen Nadir, die in januari 1733 Bagdad belegerde, versloeg het leger onder bevel van Topal Osman Pasja, dat Bagdad te hulp was gestuurd, bij Dücum nabij Samarra de troepen van Nadir; de gewonde Nadir trok zich terug naar Hamadan en de maandenlange belegering werd opgeheven. Maar de overwinning was van korte duur: Nadir trok aan het einde van hetzelfde jaar opnieuw Irak binnen en versloeg de Osmaanse troepen bij Akderbend ten noorden van Kirkuk; Topal Osman Pasja kwam tijdens deze gevechten om het leven en werd in Kirkuk begraven.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Nadir Sjahs veldtocht in Irak — de laatste Osmaans-Iraanse oorlog begon, Kirkuk viel", "ba014bf5"], "d": ["Nadir Sjah, die achttien maanden in Dagestan en Georgië was gebleven, begon in 1743, nadat zijn verzoek om erkenning van het Jafarisme als vijfde rechtsschool door de Osmanen was afgewezen, een nieuwe veldtocht tegen de Osmanen en trok met een groot leger Kirkuk binnen. Hetzelfde succes kon hij in Mosul niet behalen; hij moest de belegering opheffen. Dit is de laatste Osmaans-Iraanse oorlog, die eindigde met het Verdrag van Kerden van 1746.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Belegering van Kars door Nadir Sjah — duurde twee maanden, zonder resultaat", "a3ea61d9"], "d": ["De Safavidische prins Safi Mirza, die toevlucht bij de Osmanen had gezocht, maakte aanspraak op de Iraanse troon; volgens het plan zou de seraskier van Kars hem via Tabriz naar Isfahan brengen en op de troon zetten, en de Osmanen hadden drie fronten tegen Iran geopend. Daarop trok Nadir Sjah naar Kars en belegerde het fort. Van de twee maanden durende belegering behaalde hij geen resultaat.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Nederlaag bij Kağaverd — het leger van Yeğen Mehmed Pasja werd verstrooid", "7caf6f22"], "d": ["Het jaar na de belegering van Kars bracht Nadir Sjah bij de plek Kağaverd de Osmaanse troepen onder bevel van Yeğen Mehmed Pasja een nederlaag toe. Daarna keerde hij terug naar Isfahan. Zijn afzien van de aandrang op erkenning van het Jafarisme baande het jaar daarop de weg voor het Verdrag van Kerden.", "3992b8ed"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["Kufa werd gesticht", "617d0f35"], "d": ["Kufa werd in het algemeen als garnizoensstad gesticht in 17 (638); het werd het centrum van het Rashidun-kalifaat in Irak (de dag is onbekend).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["Hasan b. Ali liet het kalifaat aan Mu'awiya; Mu'awiya ontving de eed van trouw in Kufa, Kufa kwam onder Omajjadische heerschappij", "cc9c9de4"], "d": ["Hasan b. Ali, die kalief werd nadat Ali door Ibn Muljam in de moskee van Kufa als martelaar werd gedood (januari 661), liet het kalifaat aan Mu'awiya; Mu'awiya kwam naar Kufa en ontving de eed van trouw van het volk (25 Rabi' al-awwal 41 / 29 juli 661). De Rashidun-periode werd gesloten, de stad kwam onder Omajjadisch bestuur (de Zubayridische tussenperiode 680-691 is in de registratie niet afzonderlijk geschreven).", "6cadb24f"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["Kairouan werd gesticht (Uqba b. Nafi', Omajjaden)", "7409e9ae"], "d": ["De Omajjadische gouverneur Uqba b. Nafi' stichtte Kairouan in 670 als basis van Ifriqiya.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["Abd ar-Rahman b. Habib kwam in opstand: Kairouan kwam uit het Omajjadische bestuur", "4c7a0da0"], "d": ["Met de opstand van Abd ar-Rahman b. Habib in 745 kwam Kairouan uit het Omajjadische gouverneurschap; tot 761 Habibidische/Kharijitische tussenperiode (eigenaar als leemte verklaard).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["Het Abbasidische leger nam Kufa in", "0191709e"], "d": ["Het Abbasidische leger nam Kufa op 14 Muharram 132 (2 september 749) in; de stad ging van de Omajjaden over naar de Abbasiden.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["Muhammad b. al-Ash'ath, door de Abbasiden aangesteld, nam Kairouan in", "71af9f79"], "d": ["Muhammad b. al-Ash'ath nam Kairouan in het jaar 144 (761) namens de Abbasiden in.", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["Kalief al-Mansur begon met de bouw van Bagdad (Madinat as-Salam)", "844a94d5"], "d": ["De bouwwerkzaamheden van de aan de Tigris gestichte stad begonnen in 762; zij werd de permanente hoofdstad van de Abbasiden (de dag is onbekend, alleen het jaar is bevestigd).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["De Buyid Ahmad (Mu'izz ad-Dawla) trok Bagdad binnen; de stad kwam onder Buyidische heerschappij", "31accd4a"], "d": ["Ahmad trok op 11 Jumada al-awwal 334 (19 december 945) Bagdad binnen; kalief al-Mustakfi maakte hem amir al-umara, de stad kwam onder de heerschappij van de Buyiden (ook Kufa kwam in 945-1055 onder Buyidische heerschappij; voor Kufa is de dag van Bagdad als buur overgenomen).", "11f31be7"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Inname van Damietta op de Fransen — ontruiming van het fort Lesbe", "06b1e7b0"], "d": ["Een macht onder bevel van İbrahim Pasja uit het leger van de grootvizier werd naar Damietta gestuurd. Op de ochtend van 14 mei, toen de aanval op het fort Lesbe, dat Damietta beschermde, was voorbereid, bleek dat het fort door de Fransen was ontruimd en het garnizoen zich had teruggetrokken; ook de twee kleine forten die eraan verbonden waren, werden ingenomen. Damietta werd na Rosetta, dat in april was gevallen, de tweede stad aan de Nijlmonding die uit Franse controle kwam.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Overname van Caïro van de Fransen — capitulatie van Belliard", "7a11bb5e"], "d": ["Tijdens de gezamenlijke operatie van Ottomaanse en Britse troepen naar Egypte ondertekende generaal Belliard, de commandant van de Franse troepen in Caïro, de capitulatie. Samen met Caïro kwam ook Suez, dat de Fransen in november 1798 hadden ingenomen, uit Franse controle. De afsluiting van de bezetting zou twee maanden later in Alexandrië worden voltooid, de evacuatie uit het land zou tot oktober duren.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Overname van Alexandrië van de Fransen — capitulatie van Menou", "cd50663c"], "d": ["Generaal Menou, opperbevelhebber van het Oostelijke Leger, werd op 17 augustus in Alexandrië belegerd; op 21 augustus namen de Engelsen het fort Marabout bij de stad in en op 31 augustus ondertekende Menou de capitulatie van het leger. De terugkeer van de Franse troepen naar Frankrijk begon op 2 september. Zo eindigde de bezetting, die in juni 1798 met de landing in Alexandrië begon, in de stad waar zij begonnen was.", "22e807c1"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Polen schoof zijn Dnjepr-linie op — stichting van Kremenchuk", "1bc86966"], "d": ["Polen-Litouwen stichtte een nieuwe grensstad bij de kruising van de midden-Dnjepr, de doorgang van de Krim-invallen; vijfentwintig jaar later werd daar ook een fort aan toegevoegd. Zo daalde de controlelijn van Polen af tot de noordelijke oever van de Zaporozjer steppe en werd deze doorgang van de rivier voor het eerst aan een permanent garnizoen van een staat gebonden. De stad zou in de volgende eeuw als Kozakkenregimentscentrum in de orde van het Hetmanaat overgaan.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Verschijnen van Oeman op de Poolse grenslinie van Jedysan", "2e6551ab"], "d": ["Oeman kwam voor het eerst als nederzetting aan het zuidoostelijke uiteinde van de onder Pools bestuur staande regio Bratslav in documenten voor. Zijn ligging was op de naar het noorden reikende invalsroutes van het Krim-khanaat; de vestiging van een permanente stad hier toont aan dat de lege steppestrook tussen de twee staten van het noorden af begon te krimpen. De stad zou de twee eeuwen daarna de zuidelijkste grote Poolse nederzetting op deze lijn blijven.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Opschuiven van de steppeverdedigingslinie van Moskou — Tsjoehoejiv", "c68d36d3"], "d": ["De Kozakkenleider Jakiv Ostranycja en zijn mannen, die na de opstand in Polen toevlucht hadden gezocht in Moskou, stichtten een grensnederzetting aan de Donets. Dit was een van de eerste grote sprongen richting de steppe van de verdedigingslinie die Moskou tegen de Krim-invallen aanlegde; in de halve eeuw daarna volgden op dezelfde lijn achtereenvolgens steden als Soemy, Izjoem en Bachmoet. De nederzetting bleef tot 1765 als compagniescentrum onder het regiment van Charkov bestaan.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Stichting van Sloboda-Oekraïne — Soemy en de nederzettingsstrook in de steppe", "ab7abf59"], "d": ["Boeren en Kozakken van het regiment Bila Tserkva uit Oekraïne aan de rechteroever stichtten onder leiding van kolonel Herasym Kondratjev een nieuwe stad aan de Psel; vier jaar later versterkte de woiwode van Moskou het fort. Deze migratiegolf is het begin van de orde van Sloboda-Oekraïne, die de lege steppe aan de zuidgrens van Moskou voor bewoning openstelde: aan de nieuwkomers werd belastingvrijstelling verleend in ruil voor grenswacht. Soemy was van 1658 tot 1765 het centrum van het regiment dat zijn naam droeg.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Bouw van Yenikale — afsluiting van de Straat van Kertsj", "d9067015"], "d": ["Nadat Azov in 1700 aan Rusland was overgelaten, werd de enige poort van de Zwarte Zee naar de Azovzee een strategische grenslijn. Het Osmaanse Rijk liet tien kilometer ten noordoosten van de stad Kertsj, op de plek Akıntı Burnu, een nieuwe versterking bouwen die de doorvaart van de straat onder kanonbereik bracht; het fort kreeg de naam Yenikale (Nieuw Kasteel), wat het woord zelf is. Het fort bleef zeventig jaar lang het oostelijke slot van de Krim en werd met artikel negentien van het Verdrag van Küçük Kaynarca van 1774 samen met Kertsj aan Rusland afgestaan.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Fort Heilige Elisabeth — de zuidgrens van Rusland leunt tegen de Osmaans-Krim-invalslijn", "b9097272"], "d": ["Rusland bouwde op het grondgebied van de Zaporozjer Kozakken een nieuw fort met de naam Heilige Elisabeth. De uitdrukkelijke reden van het fort was de uit de Balkan afkomstige migranten die zich in Nieuw-Servië hadden gevestigd te beschermen tegen Osmaanse en Krim-invallen; de Russische grenslijn daalde dus voor het eerst tot midden in de steppe, tot op de invalsroutes. Deze voorpost werd twintig jaar later het vertrekpunt van de uitbreiding aan de noordelijke Zwarte Zee die met Küçük Kaynarca zou beginnen.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["Tweede Verdrag van Erzurum — grens op de Shatt al-Arab en het afstaan van de kust van Khuzestan", "5d1f9103"], "d": ["Het Osmaans-Iraanse grensgeschil, dat al meer dan een eeuw onopgelost was, werd na lange onderhandelingen onder Britse en Russische bemiddeling geregeld met het tweede verdrag dat in Erzurum werd ondertekend. De gehele waterweg van de Shatt al-Arab bleef bij het Osmaanse Rijk; daartegenover werden de nederzettingen aan de oostoever van de rivier — met inbegrip van de haven Muhammara en het eiland Abadan daartegenover — aan de Kadjaren gelaten. Zo ging de kuststrook van Khuzestan, die sinds de annexatie van Basra in 1546 als onder Osmaans bestuur stond, driehonderd jaar later verloren. Mehmed Hurşid Pasja, lid van de grenscommissie die werd ingesteld om de door het verdrag getrokken lijn ter plaatse vast te stellen, trok in 1848-1852 door het gebied en schreef de Seyâhatnâme-i Hudûd.", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Terugtrekking uit Tabriz — einde van een bezetting van een week en terugkeer via Kars-Bayburt", "fd1542e3"], "d": ["Yavuz Sultan Selim, die na de overwinning bij Çaldıran op 6 september Tabriz was binnengetrokken, bleef ongeveer een week in de stad; hij liet de schat van Sjah Ismail en een deel van de ambachtslieden en geleerden van de stad met hun gezinnen naar Constantinopel verhuizen. Hij wilde de winter in Karabach doorbrengen en het jaar daarop de veldtocht voortzetten, maar zag onder verzet van de janitsaren van dit plan af, en het leger keerde via Kars en Bayburt terug. Zo bleef Tabriz niet in Osmaanse handen: Çaldıran was een veldslagoverwinning, de blijvende gebiedswinst kwam het jaar daarop met de campagne van Kemah, Diyarbekir en Oost-Anatolië.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Aansluiting van Nusaybin, Derik en Silopi bij de Osmanen — de zuidelijke tak van Diyarbekir", "c3621d22"], "d": ["Nadat Âmid was overgenomen en het beylerbeylik Diyarbekir was gesticht, kwamen, doordat İdrîs-i Bitlisî de Koerdische beys in de streek voor zich won, ook Nusaybin, Derik en Silopi ten zuiden van de vlakte van Mardin onder Osmaans bestuur. Deze plaatsen werden georganiseerd als nahiye- en kazacentra van het nieuwe beylerbeylik; sommige, zoals Cizre, werden met de status van yurtluk-ocaklık aan de plaatselijke beys overgelaten. Zo bereikte de campagne in Oost-Anatolië, die na Çaldıran was begonnen, Boven-Mesopotamië (al-Jazira).", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Onafhankelijkheidsverklaring van Tsjecho-Slowakije — eerste opvolgerstaat van de Habsburgse erfenis", "8f40155f"], "d": ["Nadat Oostenrijk-Hongarije in de oorlog zijn kracht had verloren en door stakingen, demonstraties en opstanden in het land, verklaarde de Nationale Raad op 28 oktober 1918 de onafhankelijkheid van Tsjecho-Slowakije. Op basis van de verkiezingsstand van 1911 werd een voorlopige nationale vergadering gevormd; op 14 november 1918 trad de regering aan, met Masaryk als voorzitter. De nieuwe staat verwierf zijn plaats in het internationaal recht met het Verdrag van Saint-Germain-en-Laye (10 september 1919). Op de kaart verschijnt Tsjecho-Slowakije op 11 november 1918; de onafhankelijkheidsverklaring gaat daar twee weken aan vooraf. Met deze verklaring gingen Hradec Králové (Bohemen), Olomouc en Brno (Moravië) over naar Tsjecho-Slowakije.", "74de11eb"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Uitroeping van de Staat van Slovenen, Kroaten en Serven — het Kroatische Sabor verbrak de Habsburgse banden", "2e5ae559"], "d": ["Het Kroatische Sabor verklaarde op 29 oktober 1918 dat het alle staatsrechtelijke banden van Kroatië, Slavonië en Dalmatië met Oostenrijk-Hongarije verbrak; dezelfde dag werd in Ljubljana de oprichting van de Staat van Slovenen, Kroaten en Serven gevierd. In Bosnië en Herzegovina droeg het Oostenrijks-Hongaarse bestuur op 1 november 1918 de macht over aan de regering van de Nationale Raad. Deze staat bestond voort tot op 1 december 1918 in Belgrado het Koninkrijk der Serven, Kroaten en Slovenen werd uitgeroepen.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Stichting van de Republiek Oostenrijk — de Duitse kern van de Habsburgse erfenis", "1ec8b06f"], "d": ["Nadat op 29 oktober in Praag de oprichting van Tsjecho-Slowakije en in Zagreb die van de Staat van Serven, Kroaten en Slovenen was uitgeroepen, stichtten ook de Oostenrijkse Duitsers op 30 oktober de Republiek Oostenrijk. Dezelfde dag ondertekende het Osmaanse Rijk het Bestand van Moudros; het einde van de twee keizerrijken viel in de kalender naast elkaar.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Asterrevolutie — Károlyi werd minister-president, de monarchie in Hongarije begon uiteen te vallen (de volksrepubliek werd op 16 november uitgeroepen)", "d7780d2e"], "d": ["Toen de nederlaag van de Centrale Mogendheden duidelijk werd, namen in Hongarije de anti-monarchistische gevoelens toe en vond een verschuiving naar links plaats. Op 31 oktober 1918 werd graaf Mihály Károlyi, met radicale opvattingen, na de \"asterrevolutie\" minister-president, waarna de volksrepubliek werd uitgeroepen; Károlyi werd op 11 januari 1919 tot de feitelijke president gekozen.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Bestand van Villa Giusti — Oostenrijk-Hongarije legde de wapens neer, Trento en Triëst gingen naar Italië", "75da65fb"], "d": ["Het ondertekenen door keizer Karel van het bestand met de Italianen in Villa Giusti op 3 november 1918 versnelde het uiteenvallen van het keizerrijk. TDV registreert deze dag uitdrukkelijk als de wapenneerlegging van Oostenrijk: \"Oostenrijk, dat de nederlaag aanvaardde, legde op 3 november de wapens neer, Duitsland op 11 november.\" Op de kaart gaan Trento en Triëst deze dag van Oostenrijk over naar Italië — dit is de eerste territoriale overdracht van de ontbinding die op de kaart zichtbaar is. Met dit bestand kwamen Brixen, Cortina d'Ampezzo, Gorizia en Gradisca, ten zuiden van de lijn Brenner–Toblach–Julische Alpen, onder Italiaanse bezetting.", "11a74dbf"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Onafhankelijkheid van Polen — de Regentschapsraad droeg het bevel over het leger aan Piłsudski over", "e8b546cf"], "d": ["Józef Piłsudski keerde op 10 november 1918 terug naar Warschau. Op 11 november gaf de Regentschapsraad hem het bevel over het leger; enkele dagen later droeg hij hem ook de taak op de nationale regering te vormen.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["Het Servische leger bezette Pécs (Peçuy) — begin van de Servische bezetting van Baranya", "68f0695f"], "d": ["Pécs, dat vanwege zijn steenkoolmijnen strategisch belang had, kwam op 14 november 1918 onder Servische bezetting. De Servische bezetting van Pécs en de provincie Baranya duurde tot augustus 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["Het Servische leger bezette Timișoara (Temesvár) — begin van het Servische militaire bestuur van de Banaat", "3cc85350"], "d": ["Servische troepen bezetten Timișoara op 14 november 1918, ontbonden de nationale garde en namen het militaire en kort daarna ook het civiele bestuur van de Banaat op zich. Begin december trokken ook Franse troepen de stad binnen; het Roemeense bestuur werd pas in juli-augustus 1919 gevestigd.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Servische troepen trokken Szigetvár binnen — bezetting van het zuiden van Somogy", "a06b1907"], "d": ["Van het Servische leger dat voorbij de door de militaire overeenkomst van Belgrado getrokken lijn naar het noorden oprukte, trokken 220 soldaten onder bevel van Obren Petrović in de nacht van 18 op 19 november Szigetvár binnen, het districtscentrum van Somogy; ook de dorpen van het district werden door deze macht bezet. De bezetting duurde tot augustus 1921; Trianon liet Szigetvár bij Hongarije.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Stichting van het Koninkrijk der Serven, Kroaten en Slovenen en van Groot-Roemenië — dezelfde dag, twee staten", "6fd85345"], "d": ["Als gevolg van het uiteenvallen van Oostenrijk-Hongarije en de vereniging van de zich van het keizerrijk afscheidende Slaven met Servië werd op 1 december 1918 het Koninkrijk der Serven, Kroaten en Slovenen gesticht; ongeveer 250.000 km² grondgebied en 12.000.000 inwoners. De basis was gelegd in de Verklaring van Corfu van 20 juli 1917; op 26 oktober hadden de vergaderingen van Podgorica, op 28 oktober van Bosnië en Herzegovina en op 25 november van Novi Sad besloten zich aan te sluiten. Dezelfde dag ontstond Groot-Roemenië doordat Transsylvanië, Boekovina en Bessarabië zich op besluit van hun eigen volkeren aansloten. Op de kaart gaat het grondgebied van het Koninkrijk Servië over naar Joegoslavië. Met de stichting van het koninkrijk gingen alle gebieden van het Koninkrijk Servië (Niš, Skopje, Monastir, Ohrid, Pristina, Prizren, Peć enz.) over naar het Koninkrijk der Serven, Kroaten en Slovenen.", "4fd0ff67"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["Het Roemeense leger trok Brașov (Brassó) binnen en werd plechtig ontvangen", "4a917d27"], "d": ["Het Roemeense leger trok in december 1918 Brașov binnen; de Roemeense notabelen van de stad ontvingen het leger en generaal Berthelot plechtig.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["Het Italiaanse leger bezette Knin", "7949dd0f"], "d": ["Het Italiaanse leger bezette Knin op 19 december 1918. De bezetting duurde tot 4 april 1921, toen het Italiaanse leger zich na het Verdrag van Rapallo uit de stad terugtrok.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Tsjecho-Slowaakse troepen namen Košice (Kassa) in", "0989490f"], "d": ["Toen het 30e Infanterieregiment, dat de naam van Alois Jirásek droeg, de stad op 29 december 1918 bezette, werd Košice feitelijk bij de Tsjecho-Slowaakse Republiek gevoegd.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["Het Roemeense leger trok Szatmár (19 april) en Oradea (Varad, 20 april) binnen", "3ee2bd72"], "d": ["Op paaszaterdag 19 april 1919 ontving in Satu Mare de plaatselijke delegatie onder leiding van dr. Ilie Carol Barbul de eerste patrouille van de 2e Cavaleriedivisie onder bevel van kolonel Ressel op de Someș-brug. De volgende dag, 20 april 1919, trokken Roemeense troepen onder bevel van generaal Traian Moșoiu Oradea binnen.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Verdrag van Versailles — de teruggave van Elzas-Lotharingen aan Frankrijk werd juridisch vastgelegd", "3babdfcb"], "d": ["De Vredesconferentie van Parijs kwam op 18 januari 1919 bijeen en op 28 juni werd met Duitsland het Verdrag van Versailles ondertekend. Artikel 51 van het verdrag gaf Elzas-Lotharingen (Straatsburg, Metz, Colmar, Mulhouse), dat sinds 1871 Duits was, terug onder Franse soevereiniteit — maar bond de overdracht niet aan de ondertekeningsdag, maar met terugwerkende kracht aan het bestand van 11 november 1918. Dezelfde reeks conferenties bracht Saint-Germain met Oostenrijk (10 september 1919), Neuilly met Bulgarije (27 november 1919), Trianon met Hongarije (4 juni 1920) en Sèvres met het Osmaanse Rijk (10 augustus 1920) voort.", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Roemeense troepen bereikten Lugoj (Lugos) — Roemeens bestuur in het oosten van de Banaat", "f65fc73c"], "d": ["De trein met Roemeense troepen bereikte Lugoj op 22 juli 1919 om 14.00 uur; de stadsbevolking ontving het leger op het station, de prefect van Caraș-Severin, George Dobrin, hield de welkomstrede, generaal Jitianu antwoordde. In het deel van de Banaat dat aan Roemenië viel, werd het Roemeense bestuur in juli 1919 gevestigd; de juridische overdracht vond plaats met het Verdrag van Trianon in 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["Het Roemeense leger trok Timișoara (Temesvár) binnen — Roemeens bestuur in de stad gevestigd", "8728e1d1"], "d": ["In Timișoara, dat op 14 november 1918 door Servische en begin december door Franse troepen was binnengetrokken, trokken in de ochtend van 3 augustus 1919 de eerste eenheden van het Roemeense leger onder bevel van kolonel Virgil Economu binnen en werd het Roemeense bestuur in de stad gevestigd.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["Het leger van het Koninkrijk SHS trok Prekmurje binnen — Murska Sobota en Lendava kwamen onder Hongaars bestuur uit", "21b2ba08"], "d": ["Troepen van het Koninkrijk der Serven, Kroaten en Slovenen trokken op 12 augustus 1919 Prekmurje, voorbij de rivier Mura, binnen; het Hongaarse bestuur in de regio eindigde die dag. De juridische overdracht vond plaats met het Verdrag van Trianon in 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Verdrag van Saint-Germain — de inkrimping van Oostenrijk werd juridisch vastgelegd", "e7b722d5"], "d": ["Na de oorlog ondertekende Oostenrijk met de bondgenoten het Vredesverdrag van Saint-Germain. Volgens het verdrag erkent Oostenrijk de onafhankelijkheid van Hongarije, Tsjecho-Slowakije en Joegoslavië; het aanvaardt zich zonder toestemming van de Volkenbond niet met Duitsland te verenigen, de dienstplicht af te schaffen en het leger tot 30.000 man te beperken. Dit is ook het document waarmee Tsjecho-Slowakije zijn plaats in het internationaal recht verwierf. De overdracht op de kaart had een jaar eerder plaatsgevonden; dit verdrag bevestigde die. Met dit verdrag gingen Lvov, Yazlofça, Karviná en de kust van Dalmatië met de eilanden (Krk, Cres, Lošinj, Rab, Pag, Hvar, Korčula, Vis, Zadar, Šibenik, Knin) van Oostenrijk over naar de beschikking van de Hoofdmogendheden van de Geallieerden; Ungvár en Munkács (Karpaten-Roethenië) gingen naar Tsjecho-Slowakije.", "b4d5f306"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Verdrag van Neuilly — Bulgarije verloor West-Thracië en de Egeïsche kust", "01f2b8c8"], "d": ["Doordat de oorlog met een nederlaag eindigde, had tsaar Ferdinand een bestand moeten vragen en ten gunste van zijn zoon Boris moeten aftreden (29 september 1918). Met het Verdrag van Neuilly, dat de oorlog beëindigde, leed Bulgarije strategisch gebiedsverlies ten gunste van de Serven, verloor het geheel West-Thracië, moest het de Egeïsche kust aan Griekenland laten en bekrachtigde het de bepalingen van het Verdrag van Boekarest dat Zuid-Dobroedzja aan Roemenië gaf. Op de kaart staat de tegenhanger van deze overdracht niet op de verdragsdag, maar in mei 1920, toen het bestuur feitelijk van hand wisselde: Dedeağaç, Sofulu, Orestiada en Çirmen op 14 mei, Gümülcine, İskeçe, Dimetoka en Ferecik op 27 mei gaan naar Griekenland.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Verdrag van Trianon — Hongarije verloor twee derde van zijn grondgebied", "84aff507"], "d": ["Krachtens het Verdrag van Trianon, ondertekend drie maanden nadat Horthy op 1 maart 1920 tot regent was benoemd, leed Hongarije zware verliezen aan grondgebied en mensen: twee derde van zijn grondgebied van 283.000 km² (Kroatië niet meegerekend) en zestig procent van zijn bevolking, waaronder meer dan drie miljoen Hongaren, kwam buiten de grenzen te liggen; het leger werd teruggebracht tot 35.000 man. Op de kaart verschijnt het Regentschap Hongarije binnen deze verkleinde grenzen; ook Transsylvanië en Boven-Hongarije gaan precies op deze dag over naar de kleur van Roemenië en Tsjecho-Slowakije. Met dit verdrag gingen Bratislava, Kassa, Nitra en Komárom (Boven-Hongarije) juridisch over naar Tsjecho-Slowakije; Varad, Szatmár, Lugos, Gyulafehérvár en Brașov (Transsylvanië en het oosten van de Banaat) naar Roemenië; Subotica, Becskerek, Bač, Murska Sobota en Čakovec (Bačka, het westen van de Banaat, Prekmurje, Međimurje) naar het Koninkrijk der Serven, Kroaten en Slovenen.", "f7c54f07"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["De Banaat werd verdeeld, Temesvár werd aan Roemenië gelaten (Trianon art. 27/3 en 45)", "256b4aca"], "d": ["Het Verdrag van Trianon trok de Hongaars-Roemeense grens met art. 27/3 en met art. 45 deed Hongarije ten gunste van Roemenië afstand van al zijn rechten en titels op de gebieden van de voormalige monarchie voorbij deze grens; zo werd de vereniging van Transsylvanië, de Banaat, Crișana en Maramureș met Roemenië in het internationaal recht erkend. De regio Banaat werd tussen Roemenië en Servië verdeeld; de stad Timișoara werd bij het Koninkrijk Roemenië gevoegd. In Timișoara functioneerde het Roemeense bestuur feitelijk sinds 3 augustus 1919; het verdrag legde deze situatie juridisch vast.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["Het Italiaanse leger trok zich terug uit Knin", "a1d2e846"], "d": ["Na het Verdrag van Rapallo trok het Italiaanse leger zich op 4 april 1921 uit Knin terug; de bezetting die op 19 december 1918 was begonnen, eindigde.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Italië droeg Šibenik over aan het Koninkrijk SHS", "9d07b12a"], "d": ["De Italiaanse bezetting, die op 6 november 1918 was begonnen, eindigde op 12 juni 1921 met een ceremonie in aanwezigheid van militaire vertegenwoordigers van Italië en het Koninkrijk SHS.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Servische troepen trokken zich terug uit Szigetvár — de Hongaarse gendarmerie nam de stad over", "97781b77"], "d": ["Na de inwerkingtreding van Trianon begonnen de Servische troepen zich op 17 augustus uit Barcs en Szigetvár terug te trekken en namen alles mee wat te vervoeren was. Op 20 augustus omstreeks het middaguur trokken Hongaarse gendarmerie-eenheden binnen; in de middag zwoeren de gemeenteraad en de ambtenaren de eed en om vijf uur vond in het stadhuis de militaire overdracht plaats.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["De Servische bezetting van Pécs (Peçuy) eindigde — het Hongaarse Nationale Leger trok de stad binnen", "f437115a"], "d": ["Servische troepen begonnen het gebied op 18 augustus 1921 te ontruimen; op 20-21 augustus werd het bestuur van de stad en de provincie overgedragen aan vertegenwoordigers van de Hongaarse regering, en op 22 augustus trokken eenheden van het Hongaarse Nationale Leger de stad binnen.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["Het Oostenrijkse Bundesheer trok Burgenland binnen — het door Trianon aan Oostenrijk gelaten gebied werd feitelijk overgenomen", "7bfd6915"], "d": ["Trianon (1920) en Saint-Germain (1919) hadden de Duitstalige strook van West-Hongarije aan Oostenrijk gelaten; de eerste poging tot overname op 28 augustus 1921 mislukte door het verzet van Hongaarse onregelmatige troepen. Na het Protocol van Venetië (13 oktober 1921) keurde de Algemene Commissie van de Geallieerden op 11 november de intocht van het Bundesheer goed en twee dagen later begon de overname van Noord-Burgenland; het zuiden werd op 6 december 1921 overgenomen, het gebied van Sopron bleef door een volksstemming bij Hongarije.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["Constantinopel werd plechtig geopend; het centrum van het keizerrijk verschoof feitelijk naar het oosten", "e4d78842"], "d": ["De door Constantijn I gestichte nieuwe hoofdstad werd op 11 mei 330 plechtig geopend; Constantinopel werd de hoofdstad van het Byzantijnse (Oost-Romeinse) Rijk.", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["Bevelhebber Jawhar as-Siqilli trok Fustat binnen en veroverde Egypte; de Ikhshididen kwamen ten einde", "fd0410b1"], "d": ["Jawhar as-Siqilli trok namens de Fatimidische kalief al-Mu'izz li-Din Allah Fustat binnen (17 Sha'ban 358 / 6 juli 969); Egypte ging van de Ikhshididen over naar de Fatimiden, het gebied waar Caïro zou worden gesticht kwam onder Fatimidische heerschappij.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["Abu'l-Dhawwad nam Mosul in; de Uqaylidische dynastie werd gesticht", "c3032f55"], "d": ["De Uqaylid Abu'l-Dhawwad Muhammad b. al-Musayyab nam Mosul in (380 / 990); van het snijvlak van Hijri 380 ∩ 990 is de eerste dag, 31 maart 990, gekozen (Hijri-Gregoriaanse tabel, ±1-2 dagen), de dag staat niet in de bron.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["Afonso Henriques nam Lissabon (Ushbuna) in; de stad werd het centrum van het nieuwe Koninkrijk Portugal", "24fddde8"], "d": ["Ushbuna werd op de Almoraviden veroverd en ging naar Portugal (27 Jumada al-awwal 542 / 24 oktober 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["Jaume I nam de stad Mallorca (Medina Mayurqa) in", "47fd675c"], "d": ["De koning van Aragon Jaume I nam de stad Mallorca op de moslims in; Palma ging over naar de Kroon van Aragon.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["Muhammad b. Yusuf Ibn al-Ahmar stichtte de Nasridische staat in Granada", "23f66f33"], "d": ["De Nasridische staat werd gesticht met Granada als centrum (26 Ramadan 635 / 12 mei 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["Verdrag van Stensby: de Teutoonse Orde gaf Noord-Estland (Reval) terug aan de Deense koning Valdemar II", "b64c584d"], "d": ["Met de overeenkomst die in juni 1238 in Stensby op Seeland werd bereikt, keerden Reval en Noord-Estland terug onder Deense heerschappij (de dag staat niet in de bron).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["Overgavecontract van Valencia: Jaume I nam de stad in", "977120b3"], "d": ["Valencia kwam op 28 september 1238 met een overgavecontract aan de koning van Aragon Jaume I (plechtige intocht op 9 oktober).", "c3465b4f"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["De stammen rond Ta'if kwamen onder Wahhabitische invloed — Turaba en Khurma maakten zich los van het sjarifaat van Mekka", "d3b644be"], "d": ["De stammen rond Ta'if die aan Sjarief Ghalib van Mekka waren gebonden, kwamen in 1801 onder Wahhabitische invloed; de emir van Diriyah gaf hen onder het bestuur van de bedoeïenensjeik Uthman al-Mudayfi, de zwager en vijand van de Sjarief. Ook de oases Turaba en Khurma in het oosten gingen in deze gordel naar de Saoedische zijde. Dit was de voorloper van de inname van Ta'if in februari 1803 en daarna Mekka door de Wahhabieten.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["De Egyptische garnizoenen trokken zich terug uit Turaba, Bisha en Ranya in het zuiden van de Hidjaz", "72b87aa1"], "d": ["In de maanden nadat Tusun Pasja vrede had gesloten met de Wahhabieten en in november 1815 naar Caïro was teruggekeerd, brak in het zuiden van de Hidjaz onrust uit; de garnizoenen van Mehmet Ali Pasja moesten zich terugtrekken uit Bisha, Ranya en Turaba. Het vertrek van İbrahim Pasja uit Caïro in augustus 1816 voor een nieuwe veldtocht volgde op deze terugtrekking. Wie Turaba tot de val van Diriyah (1818) bestuurde, staat niet in de bron.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["Het Egyptische garnizoen trok zich terug uit Sulaymiyya in Kharj en bereikte Manfuha — het zuiden van Nadjd bleef zonder leiding", "2743f70d"], "d": ["Het Egyptische garnizoen dat İbrahim Pasja na de vernietiging van Diriyah in Sulaymiyya in Kharj had geplaatst, liet vóór zijn vertrek op het terugtrekkingsbevel van de Pasja op een feestmaal de vier sjeiks van Dilam doden en werd door bedoeïenen omsingeld. Het gered garnizoen bereikte op 13 augustus 1819 Manfuha en de mars naar Qasim begon. In het zuiden van Nadjd bleef geen centraal gezag over; de pogingen van de familie Saoed brachten tot 1824 geen resultaat.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Şehirköy keerde terug onder Ottomaanse heerschappij — dood van Đurađ Branković", "e37156d1"], "d": ["Şehirköy, in 1443 door het kruisvaardersleger veroverd en na het Verdrag van Edirne-Szeged van 1444 door Murad II aan de Serviërs gelaten, keerde in 1456 met de dood van de Servische despoot Đurađ Branković terug onder Ottomaanse heerschappij. In hetzelfde jaar en om dezelfde reden kwam ook Niš definitief onder Ottomaans bestuur; zo werd de lijn van de Nišava-vallei die naar de weg naar Sofia leidt voltooid. Het verdrag was voor tien jaar ondertekend en na Varna (1444) en het Tweede Kosovo (1448) duurde het leven van het Despotaat slechts zo lang als dat van Branković.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Selim de Norse vertrok uit Edirne voor de Çaldıran-veldtocht", "1f7921f7"], "d": ["Selim de Norse, die zijn zoon prins Süleyman in Manisa als plaatsvervanger in Constantinopel achterliet, vertrok uit Edirne voor zijn veldtocht tegen de Safawidische staat. Het leger zou Anatolië doortrekken langs de lijn Sivas-Erzincan-Erzurum en eind augustus bij Çaldıran de troepen van Sjah Ismail ontmoeten.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Kızıkermen (Gazi Kerman) en de rechteroever van de Dnjepr kwamen onder directe Ottomaanse controle", "56a28224"], "d": ["Het fort Kızıkermen en de rechteroever van de Dnjepr, die het khanaat van de Krim sinds het midden van de 15e eeuw in handen had, kwamen op deze datum onder directe controle van het Ottomaanse Rijk; het fort veranderde in een Ottomaanse voorpost aan de noordelijke rand van de steppe. Anders dan het gebied van het khanaat van de Krim rond Bachtsjisaraj en Or Kapı was het bestuur van Kızıkermen rechtstreeks Ottomaans.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Prozorovski bezette Or Kapı — de Russische troepen bleven tot de annexatie in Or Kapı", "afdfe804"], "d": ["Toen generaal Prozorovski, die optrok om Şahin Giray op de troon van de Krim te plaatsen, de Perekop-lijn bereikte, hadden Devlet Giray, de kaymakam en de Tataren zich uit de stad teruggetrokken; Prozorovski bezette het fort Or en de Perekop-lijn zonder strijd. De Russen vestigden zich in Or Kapı en bleven daar tot de annexatie van de Krim in 1783.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Bezetting van Anapa door de Russen (derde beleg)", "e6a7d6d5"], "d": ["Het fort Anapa, in 1781 gebouwd onder bestuur van Ferah Ali Pasja, werd tijdens de oorlog drie keer door de Russen belegerd; aan het einde van het derde beleg werd het op 26 juli 1791 bezet. De bezetting was tijdelijk — omdat met het Verdrag van Iași (1792) de oude grenzen in de Kaukasus werden aanvaard, werd het fort aan het Ottomaanse Rijk teruggegeven.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Overgave van Anapa door Osman Pasja aan de Russen", "3ccbdd1d"], "d": ["In de openingsfase van de Ottomaans-Russische oorlog van 1828-29 werd Anapa belegerd en gaven de Ottomaanse troepen in het fort onder bevel van Osman Pasja zich op 24 juni 1828 over aan de Russen. Deze keer was de overgave blijvend: met het Verdrag van Edirne dat het jaar daarop werd ondertekend (14 september 1829) kwamen Anapa en de Kaukasus officieel uit de Ottomaanse heerschappij.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Turgut Reis werd beylerbey van Tripolitanië — het eyalet breidde zich in het oosten uit tot Tobroek en Derna", "160fa43c"], "d": ["Na de verovering van Tripoli in 1551 kwam Turgut Reis in Cemaziyelevvel 963 (maart 1556) met de titel beylerbey naar Tripoli. Tijdens zijn negen jaar durende gouverneurschap werkte hij aan de opbouw en versterking van het eyalet, bracht het Ottomaanse bestuur in het zuiden tot Fezzan en nam, de grenzen naar het oosten uitbreidend, Tobroek en Derna aan de kust van Barka in. Zo omvatte het eyalet Tripolitanië een kuststrook tot aan de Egyptische grens.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Het Tsarenrijk Moskou nam Astrachan in — de Beneden-Wolga kwam onder Russische controle", "d02abd83"], "d": ["Het Tsarenrijk Moskou nam in 1556 ook Astrachan in en deed daarmee, in de bewoordingen van de TDV, 'een zet die voor de toekomst zeer belangrijke gevolgen zou hebben'; met de bezetting van het khanaat Astrachan kwam de Beneden-Wolga onder Russische controle. Hoewel Devlet Giray, de khan van de Krim, deze bezettingen wilde voorkomen, slaagde hij daar niet in. De Ottomanen antwoordden hierop in 1569 met de Astrachan-veldtocht; maar toen zij er niet in slaagden de controle over de regio van de Beneden-Wolga te verkrijgen, lieten zij de strijd met het Tsarenrijk Moskou aan de khan van de Krim over.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Verovering van Kostajnica en Novi — twee forten aan de Una-lijn", "2093e452"], "d": ["Kostajnica, in de zomer van 1556 belegerd door Malkoç Bey, werd met meer dan 60 soldaten verdedigd door kapitein Pankracije Lusthaller; het fort werd slechts een dag na het begin van het beleg, op 16 juli, overgegeven en Lusthaller werd beschuldigd van het verkopen van het fort. Kort daarna werd ook Novi ingenomen en in brand gestoken; zo kwamen de twee belangrijkste forten aan de Una in één slag in Ottomaanse handen. In hetzelfde jaar werd in Wenen de Hofkriegsrat opgericht, die de verdediging van de grens vanuit het centrum zou leiden.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Maku ging naar de Ottomanen — Mahmudi Ivaz Bey kreeg opdracht een fort te bouwen", "5932ad38"], "d": ["In het jaar 1574 gaf het Ottomaanse Rijk Ivaz Bey, het hoofd van de Koerdische Mahmudi-stam, opdracht Maku op de Iraniërs te veroveren en daar een fort te bouwen. Dit fort aan de oostelijke punt van het eyalet Van nam in de Ottomaanse tijd een belangrijke plaats in bij de gebeurtenissen in de regio.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Het eerste Ottomaanse papiergeld (kaime) werd uitgegeven", "d2e5e192"], "d": ["Tijdens het zoeken naar inkomsten voor de schatkist in de eerste jaren van de Tanzimat werd op voorstel van Arif Hikmet Bey, die later sjeik-ul-islam zou worden, de kaime-praktijk, een verbeterde vorm van het esham-stelsel, aanvaard. De eerste kaimes ter waarde van in totaal 160.000 lira (32.000 buidels) werden vanwege de dringende geldbehoefte zonder op het drukken te wachten met de hand geschreven, tijdens de tijd van minister van Financiën Sâib Pasja waarschijnlijk in juni 1840 uitgegeven. Deze papieren, met de waarde van contant geld, hadden een omloopduur van acht jaar en een rente van 12,5% per jaar; zij hadden geen dekking, alleen voor de rente werd een tegenwaarde uit de inkomsten van de douane van Constantinopel aangewezen. Het publiek stond niet positief tegenover dit geld waaraan het niet gewend was en de met de hand geschreven kaimes werden al snel het doelwit van valsemunters.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Inname van Malakka door de Portugezen", "e1556746"], "d": ["Malakka, gesticht in de jaren 1390, was de drukste haven van de regio in de zeehandel tussen China, India en het Westen en, als centrum van het Sultanaat Malakka, ook het belangrijkste brandpunt van de verspreiding van de islam naar de omliggende eilanden geworden. De Portugees Afonso de Albuquerque nam de stad op 10 augustus 1511 in; de stad werd geplunderd, haar moskeeën, dynastieke graven en andere stenen gebouwen werden gesloopt om de stenen voor de bouw van een fort te gebruiken. Malakka onder Portugees bestuur kon zijn vroegere handelsoverwicht niet handhaven; moslimkooplieden wendden zich tot de haven van het Sultanaat Aceh op Sumatra. Naar aanleiding van de aanvallen die de op Malakka gevestigde Portugezen op Aceh uitvoerden, vroeg de Acehse sultan Alauddin Riayat Sjah in 1565 Süleyman de Grote om hulp.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Sjahverdi, heerser van Luristan, verklaarde trouw aan Sjah Abbas", "85791f94"], "d": ["Sjahverdi, heerser van Luristan, die in 1589 gehoorzaamheid aan de Ottomanen had betuigd en onderworpen was aan de beylerbey van Bagdad, moest volgens het verhaal van de Safawidische historicus Iskandar Beg Munshi in het jaar 1000 (1591-92) zijn trouw aan de Safawidische kroon verklaren. Dezelfde bron schrijft dat hij in deze jaren heen en weer ging tussen de twee partijen, de gouverneurs van Hamadan lastigviel en invallen deed in Borujerd, en dat Sjah Abbas in het jaar 1002 (1593-94) Khorramabad bezette en een gouverneur in de stad benoemde. De TDV Islam Ansiklopedisi plaatst echter de volledige aansluiting van Luristan, dat met het Verdrag van Constantinopel van 1590 aan het Ottomaanse bestuur was gebonden, bij de Safawiden in het jaar 1603. De twee tradities geven verschillende data; dit item geeft de trouwverklaring uit de Safawidische traditie, het item van 1603 toont het definitieve verlies. Op de kaart is er met dit item geen eigenaarswisseling: Luristan verschijnt tot 1603 aan de Ottomaanse kant.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Definitieve overgang van Luristan naar de Safawiden", "4c5cf67b"], "d": ["Luristan, dat met het Verdrag van Constantinopel (Ferhad Pasja) van 1590 aan het Ottomaanse bestuur was gebonden, werd door Sjah Abbas I in 1603 volledig aan de Safawiden gebonden. De Safawidische historicus Iskandar Beg Munshi schrijft echter dat Khorramabad eerder, in 1002 (1593-94), door Sjah Abbas was bezet en dat een Safawidische gouverneur in de stad was benoemd; dit verschil tussen de twee tradities is niet opgelost. In hetzelfde jaar kwam ook het Ottomaanse fort Nahavand ten noorden van Luristan in handen van Sjah Abbas; de gouverneur van Hamadan, Hasan Khan, maakte het fort met de grond gelijk.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["De Catalaanse Compagnie trad in Byzantijnse dienst — begin van de Anatolische veldtocht", "6623e7db"], "d": ["Het Byzantijnse Rijk, dat in West-Anatolië land verloor aan de Turkse beyliks, nam de Catalaanse afdeling van ongeveer 6500 man onder bevel van Roger de Flor als huurlingen in dienst. Volgens het lemma Bizans van de TDV kwam de afdeling in 1303 het rijk te hulp en bevrijdde het jaar daarop Alaşehir, dat door de Germiyanoğulları werd belegerd. De compagnie begon echter al snel de plaatsen waar zij doortrok te plunderen; Byzantium liet haar naar Thracië oversteken en liet in 1305 Roger de Flor doden.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["De heerser van Hadramaut en Shihr erkende de Ottomaanse heerschappij — terugkeer van de Indische veldtocht van Hadım Süleyman Pasja", "b5cb9363"], "d": ["Hadım Süleyman Pasja, die van het beleg van Diu terugkeerde, deed op 27 november 1538 de haven van Shihr aan; toen de heerser van Hadramaut en Shihr de Ottomaanse heerschappij aanvaardde, ging hij door naar Aden. Hadramaut werd georganiseerd als een aan Jemen gebonden sandjak, maar de leiders van de Kathiri-stam bleven het bestuur in de regio in handen houden. Deze vazalstatus duurde tot de Ottomaanse terugtrekking uit Jemen in 1635.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Het vorstendom Mingrelië (Dadiani) werd aan de Ottomaanse invloedssfeer gelaten", "ea54e8ea"], "d": ["Met de bepalingen van het Verdrag van Amasya die Georgië verdeelden, werd het vorstendom Dadiani (Mingrelië en Svaneti) in West-Georgië, samen met Imereti en Guria, aan de Ottomaanse invloedssfeer gelaten. Op de kaart verschijnt Zugdidi, het centrum van Mingrelië, vanaf deze dag als een aan de Ottomanen onderworpen vorstendom; de feitelijke gehoorzaamheidsverklaring zou in 1578 volgen.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Overgang van het atabegaat Akhaltsikhe onder Ottomaans bestuur — Altunkale, Hırtıs en Akhalkalaki", "024bb326"], "d": ["Direct na de overwinning van Lala Mustafa Pasja op de Safawidische voorhoede bij Çıldır kwamen ook de gebieden in handen van de Georgische atabegs onder Ottomaans bestuur. Dedis Imedi, die Altunkale en omgeving in handen had, en zijn zonen betuigden gehoorzaamheid; de sandjakbey van Ardahan nam Çıldır en Tümük, andere Ottomaanse eenheden namen Hırtıs en Akhalkalaki in. Aan Manuchihr en zijn broer werd elk een sandjak gelaten, de rest van het land van het atabegaat werd aan direct bestuur gebonden. Akhaltsikhe zou daarna het centrum worden van het nieuw gevormde eyalet Çıldır; Manuchihr, die naar Constantinopel was gekomen en moslim was geworden en de naam Mustafa had aangenomen, zou op 1 juli 1579 aan het hoofd van dit eyalet worden geplaatst.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Kılıç Ali Pasja bouwde het fort Faş (Poti) — Ottomaanse basis aan de monding van de Rioni", "f729ba95"], "d": ["Kapudan-ı derya Kılıç Ali Pasja bouwde op 26 juli 1579 het fort Faş op de plaats waar de rivier Rioni (Faş) in de Zwarte Zee uitmondt.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Het eyalet Gori werd gesticht — direct Ottomaans bestuur in het westen van Kartli", "9a7c8bc5"], "d": ["In 1578 hadden de Georgische beys in de gebieden Gori en Mukhrani zich aan de Ottomanen onderworpen. In 1587 werd in het westen van Kartli het eyalet Gori gesticht en de regio aan direct Ottomaans bestuur gebonden. Het fort Gori, dat tijdens de opstand van de Georgiër Simon verloren was gegaan, werd in 1601 teruggenomen; het Ottomaanse bestuur eindigde in 1603 met de veldtocht van Sjah Abbas.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["De invallen van Michaël de Dappere op de Donauforten — Roese verbrand, Brăila ingenomen, Silistra geplunderd", "d0b83f6a"], "d": ["Michaël de Dappere, woiwode van Walachije, die zich bij de Heilige Liga had aangesloten, viel in de winter van 1594-95 de forten en steden langs de Donau aan die rechtstreeks onder Ottomaans bestuur stonden. Volgens het lemma Rusçuk van de TDV nam hij in februari 1595, hoewel hij het fort niet kon innemen, de stad in en stak haar in brand. Volgens het lemma İbrail nam hij İbrail aan de linkeroever van de Donau in en de stad bleef tot 1601 in zijn handen; het lemma Murad III schrijft ook dat het Walachijse leger het fort van İbrail in brand stak en tot Silistra reikte. Volgens een tahrir-register dat in het lemma Silistra wordt vermeld, stak het Walachijse leger in het voorjaar van 1595 de Donau over en plunderde Silistra; het fort van de stad werd verwoest en was lange tijd onbruikbaar. In dezelfde zomer zou Koca Sinan Pasja een veldtocht tegen Walachije ondernemen.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Sjah Abbas nam Tbilisi terug — einde van het Ottomaanse bestuur in Kartli en Kachetië", "a6995ea8"], "d": ["Sjah Abbas I nam in 1603 Tbilisi terug van de Ottomanen en riep Kartli uit tot khanaat; ook in Kachetië werd Safawidisch bestuur gevestigd. Het Ottomaanse bestuur in Oost-Georgië, dat met de veldtocht van Lala Mustafa Pasja in 1578 was begonnen, kwam zo ten einde; Tbilisi zou pas in 1723 opnieuw in Ottomaanse handen komen.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Het fort Faş (Poti) werd verwoest door de troepen van Imereti, Guria en Mingrelië", "3c3d4ed7"], "d": ["Het fort Faş werd in 1640 met de grond gelijk gemaakt door de Imeretische troepen waaraan de vorsten van Guria en Mingrelië deelnamen. De Ottomaanse aanwezigheid aan de monding van de Rioni werd onderbroken tot het fort in 1724 opnieuw werd gebouwd.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["De Pruth-veldtocht begon — in de Ottomaans-Russische oorlog van 1710-1711 vertrok het leger uit Constantinopel", "3161364b"], "d": ["De Russische aanval op Ottomaans gebied, het feit dat tsaar Peter zich niet hield aan de bepalingen van het Verdrag van Constantinopel van 1700 en de aansporingen van Devlet Giray, de khan van de Krim, hadden Ahmed III ertoe gebracht Rusland de oorlog te verklaren. Volgens het lemma Ahmed III van de TDV begon deze oorlog, die later de Pruth-veldtocht zou worden genoemd, feitelijk met het vertrek van het Ottomaanse leger uit Constantinopel op 9 april 1711. Het leger onder bevel van Baltacı Mehmed Pasja rukte, verenigd met de Krim-troepen, op naar de rivier de Pruth; de veldtocht zou in juli eindigen met het insluiten van het Russische leger aan de oever van de Pruth.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Begin van de herbouw van het fort Faş (Poti)", "0afbc4b0"], "d": ["Met het besluit van 23 december 1723 werd in maart 1724 begonnen met de herbouw van het verwoeste fort Faş; de bouw werd in 1729 voltooid.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["De regio Khoy, Kapan en Karadağ kwam opnieuw onder Ottomaans bestuur", "c52c94d1"], "d": ["Tijdens de Iraanse veldtocht die in 1723 begon, kwamen Khoy en de regio Kapan en Karadağ op 6 mei 1724 opnieuw onder Ottomaans bestuur en werden in 1728 in het Ottomaanse tahrir geregistreerd. De atlas beschouwt ook Kotur, 40 km ten zuidwesten van Khoy, op deze dag als van de Safawiden naar de Ottomanen overgegaan (keten van Khoy overgenomen: Uluerler 2015, Turkish Studies 10/5, p. 6; een voor Kotur specifieke dag staat niet in de bron — verklaarde benadering).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nadir trok Shamakhi binnen — het centrum van Sjirvan kwam uit Ottomaanse handen", "778a4988"], "d": ["Nadir trok op 17 augustus 1733 Shamakhi binnen, dat met het Verdrag van Constantinopel van 24 juni 1724 samen met het centrale deel van Sjirvan aan het Ottomaanse aandeel was gevallen. Het Ottomaanse bestuur in de Kaukasus ontbond hierna snel; Gandja en Tbilisi gingen in 1735 verloren.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimatum aan de Russische gezant — de laatste stap naar de Ottomaans-Russische oorlog van 1787-1792", "cb389693"], "d": ["De spanning die na de annexatie van de Krim door Rusland in 1783 was blijven bestaan, brak los toen duidelijk werd dat het Russische consulaat in Alexandrië de Mamelukse beys in Egypte tegen de Ottomanen ophitste. Volgens het lemma Abdülhamid I van de TDV overhandigde Reisülküttab Süleyman Feyzi Efendi op 27 juli 1787 aan de Russische gezant in Constantinopel een ultimatum van zeven artikelen. Zonder het antwoord van Rusland af te wachten werd het oorlogsbesluit genomen en binnen enkele weken uitgeroepen; het doel van de oorlog was de herovering van de Krim.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Russische troepen namen het fort Faş (Poti) in — de monding van de Rioni ging verloren", "c1241b5a"], "d": ["Tijdens de Ottomaans-Russische oorlog van 1806-1812 mislukte de Russische aanval van mei 1809; het fort werd echter op 27 november 1809 aan de Russen overgegeven.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Krachtens het Verdrag van Boekarest werd het fort Faş (Poti) aan de Ottomanen teruggegeven", "6a3a8a0a"], "d": ["Krachtens het Verdrag van Boekarest van 1812 werd het fort Faş op 19 december 1812 aan het Ottomaanse Rijk overgedragen.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Het fort Faş (Poti) kwam voor de tweede keer in Russische handen — bleef met het Verdrag van Edirne bij Rusland", "682d58f0"], "d": ["Aan het begin van de Ottomaans-Russische oorlog van 1828-1829 werd het fort Faş op 26 juni 1828 aan de Russen overgegeven. Met het Verdrag van Edirne van 14 september 1829 werd Poti samen met Akhaltsikhe, Akhalkalaki en Anapa aan Rusland gelaten.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["De Britten bezetten Nasiriyya — het Eufraat-front", "669b979e"], "d": ["De Britse troepen die vanuit Basra langs de Eufraat oprukten, versloegen op 24 juli 1915 de Ottomaanse eenheden en bezetten de volgende dag Nasiriyya. Basra was in november 1914 gevallen; Nasiriyya was nog ongeveer acht maanden in Ottomaanse handen gebleven.", "bd125229"]},
"OLAYLAR_P0049:1919-04-12:0":{"b": ["Britse bezetting van Kars — de Regering van de Zuidwestelijke Kaukasus werd ontbonden", "9004afc9"], "d": ["Krachtens de bepaling van de Wapenstilstand van Mudros om zich terug te trekken tot de grenzen van 1914 had het Ottomaanse leger Kars ontruimd. De bevolking van de regio richtte op 5 november 1918 de Islamitische Raad van Kars op tegen Armeense en Georgische aanvallen en veranderde deze in januari 1919 met een congres in de Voorlopige Nationale Regering van de Zuidwestelijke Kaukasus. Volgens het lemma Kars van de TDV bezetten de Britten Kars op 12 april 1919 en ontbonden deze regering, arresteerden haar leden en stuurden hen in ballingschap, en lieten de controle over de stad aan de Armeniërs.", "06392190"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Italiaanse bezetting van Antalya", "328331da"], "d": ["Nadat de Wapenstilstand van Mudros was gesloten, vestigden de Entente-mogendheden zich in bezettingszones in Anatolië, terwijl Italië zich op Zuidwest-Anatolië richtte. Volgens het lemma Antalya van de TDV werden de stad en omgeving op 29 april 1919, op grond van de bepalingen van de wapenstilstand, door de Italianen bezet. De bezetting zou ongeveer twee jaar duren.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Bevrijding van Maraş — de Fransen ontruimden de stad", "a57d884e"], "d": ["Maraş, dat de Britten op 22 februari 1919 hadden bezet, was op 29 oktober 1919 met een overeenkomst tussen de twee staten aan de Fransen gelaten. Het gedrag van de Armeniërs in de Franse troepen en het neerhalen van de Turkse vlag op het fort deden de bevolking in opstand komen; in de stad werden de Müdafaa-i Hukuk-vereniging en de Kuva-yi Milliye georganiseerd. Volgens het lemma Kahramanmaraş van de TDV ontruimden de Fransen aan het einde van de gevechten op 11 februari 1920 de stad en begonnen zich terug te trekken in de richting van İslahiye, en Maraş werd op 11-12 februari bevrijd. In 1925 kreeg de stad de Onafhankelijkheidsmedaille.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Bevrijding van Urfa — het Franse garnizoen verliet de stad", "c889488c"], "d": ["In Urfa, dat in maart 1919 door de Britten en ongeveer zeven maanden later door de Fransen was bezet, kwam de bevolking op 7 februari 1920 in opstand tegen de bezettingstroepen. Volgens het lemma Şanlıurfa van de TDV stemden de Fransen na twee maanden gevechten op 10 april 1920 in met de ontruiming van Urfa onder de voorwaarden van een overeenkomst en verlieten de volgende dag de stad.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["De operatie van het Oostelijke Front begon — Kâzım Karabekir ging tot de aanval over tegen Armenië", "151678df"], "d": ["Doordat het Verdrag van Sèvres Erzurum, Trabzon, Van, Bitlis en Bingöl aan Armenië liet en de Armeense aanvallen in de regio toenamen, gaf de regering van de TBMM op 20 september 1920 toestemming voor de operatie. Volgens het lemma Kâzım Karabekir van de TDV begon Karabekir, commandant van het Oostfront, de oostelijke operatie op 28 september door zijn eenheden die de passen van de Soğanlı-berg hielden het bevel tot de aanval te geven. Sarıkamış, Göle en Kağızman werden ingenomen; de operatie zou een maand later worden voortgezet met de bevrijding van Kars.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Bevrijding van Kars — het Oostelijke Front trok Kars binnen", "4e578071"], "d": ["Volgens het lemma Kars van de TDV trok Kâzım Karabekir Pasja op 30 oktober 1920 Kars binnen en werd de stad bevrijd van het Armeense bestuur waarvan de Britten in 1919 de controle hadden losgelaten. Het lemma Karabekir benadrukt dat dit de tweede bevrijding van Kars was: de stad was voor het eerst in april 1918 aan de Armeniërs ontnomen. Het Oostelijke Front rukte op en nam op 7 november Gyumri in; de oorlog eindigde met het Verdrag van Gyumri van 3 december 1920.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Inname van Gyumri — het Oostelijke Front rukte op naar het binnenland van Armenië", "cfddf791"], "d": ["De troepen van Kâzım Karabekir Pasja, die na de bevrijding van Kars de operatie voortzetten, namen op 7 november 1920 Gyumri in. De besprekingen met de Armeniërs, die met een wapenstilstand instemden, werden in Gyumri gevoerd en de oorlog eindigde met het op 3 december 1920 ondertekende Verdrag van Gyumri.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Inname van Iğdır", "6e952d2e"], "d": ["Het Oostelijke Front nam vijf dagen na de inname van Gyumri, op 12 november 1920, ook Iğdır in. Iğdır werd met het Verdrag van Gyumri van 3 december 1920 aan Turkije gelaten.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Einde van de verdediging van Antep — de stad werd na tien maanden verzet aan de Fransen overgelaten", "e080af8b"], "d": ["Antep, waar de Britten op 17 december 1918 binnentrokken, was op 5 november 1919 aan de Fransen gelaten; het eerste verzet op de lijn Antep-Kilis stond onder leiding van Şahin Bey. Volgens het lemma Gaziantep van de TDV bood de bevolking van de stad van 1 april 1920 tot 7 februari 1921 weerstand aan de Franse troepen; toen het verzet werd gebroken, trokken de verdedigende troepen zich terug en kreeg Frankrijk op 9 februari de stad in handen. De TBMM had drie dagen eerder, op 6 februari 1921, aan de stad, die tien maanden de bezetting had weerstaan, de titel gazi verleend. Antep zou na het Verdrag van Ankara op 25 december 1921 worden ontruimd.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Bevrijding van Ardahan en Artvin", "b9e50d5e"], "d": ["Na het Verdrag van Gyumri richtte het Oostelijke Front zich op het deel van de elviye-i selase dat in Georgische handen was. Volgens het lemma Ardahan van de TDV werd aan het einde van de strijd met Georgische en Armeense benden op 23 februari 1921 samen met Artvin ook de sandjak Ardahan bevrijd. Het lemma Kâzım Karabekir schrijft dat met deze zet de gebieden van de elviye-i selase, met uitzondering van de kazas Çürüksu, Ajaria en Batumi, werden teruggenomen.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Verdrag van Moskou — de TBMM en Sovjet-Rusland legden de oostgrens vast", "78d46573"], "d": ["Tussen de regering van de TBMM en Sovjet-Rusland werd op 16 maart 1921 het Verdrag van Moskou ondertekend. Volgens het lemma Kars van de TDV bleef Kars met dit verdrag en met de grensregelingen van het Verdrag van Kars van 13 oktober 1921 binnen de grenzen van de nieuwe Turkse staat. Volgens het lemma Ahıska werd Akhaltsikhe met dit verdrag aan het gouvernement Tbilisi van de Georgische Socialistische Sovjetrepubliek gebonden. De oostgrens zou zeven maanden later worden vastgelegd met het Verdrag van Kars dat met de republieken van Zuid-Kaukasië werd ondertekend. Met dit verdrag werden Batumi en Ajaria (Khulo, Sarpi, Murvaneti, Makhalakaouri) aan Sovjet-Georgië gelaten.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["De Italianen begonnen Antalya te ontruimen", "f7a4eaa7"], "d": ["Volgens het lemma Antalya van de TDV eindigde de Italiaanse bezetting, die sinds 29 april 1919 duurde, toen de Italianen op 1 juni 1921 de stad begonnen te ontruimen. Antalya en omgeving kwamen zo uit de bezetting zonder de militaire uitkomst van de Nationale Strijd af te wachten.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Raad van Cetin — de Kroatische edelen kozen na Mohács de Habsburger Ferdinand tot koning van Kroatië", "55fc9d7e"], "d": ["Toen na de dood van de Hongaars-Kroatische koning Lodewijk II bij Mohács de troon vacant was, kwamen de Kroatische edelen op 31 december 1526 in Cetin bijeen en riepen op nieuwjaarsdag de Oostenrijkse aartshertog Ferdinand tot koning uit. In de bewoordingen van de TDV deden de Kroaten deze keuze onafhankelijk van de Hongaarse edelen; het verkiezingsdocument was gebaseerd op het argument dat men tegenover de Ottomaanse invallen niet van de christelijke staat mocht losraken. Zo werden de Kroatische forten naast Ottomaans Bosnië aan de kroon van het Huis Habsburg gebonden; volgens de TDV was Bihać het hoofdcentrum van deze lijn toen de Habsburgers in de jaren 1530 de Kroatische grensregio begonnen te organiseren.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Het korte Ottomaanse bestuur van Bihać — na de val van Mohács en Jajce", "fd4118fe"], "d": ["Na de overwinning bij Mohács namen de Ottomanen in Bosnië Jajce, het centrum van de Hongaarse bufferzone, en Banja Luka in. Volgens het lemma Bihaç van de TDV kwam Bihać na de inname van het fort Jajce in het jaar na Mohács korte tijd opnieuw onder bestuur van de Ottomanen. Wanneer en hoe het fort verloren ging, staat niet in de bron; de TDV noteert slechts dat de Habsburgers in de jaren 1530, bij de organisatie van de Kroatische grensregio, het in christelijke handen zijnde Bihać tot hoofdcentrum maakten. De blijvende verovering van Bihać zou in 1592 plaatsvinden met de veldtocht van Hasan Pasja, beylerbey van Bosnië.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Einde van het Franse bestuur in Dubrovnik — Oostenrijkse troepen trokken de stad binnen, de voormalige Ottomaanse tribuutplichtige", "38d42444"], "d": ["Volgens de TDV hadden de Fransen de Republiek Dubrovnik, die sinds 1365 onder Ottomaanse bescherming stond, op 27 mei 1806 door de inname van de stad beëindigd. In de winter van 1813-1814 kwam de bevolking van de stad tegen de Fransen in opstand; de Oostenrijkse generaal-majoor Milutinović, die op 3 januari 1814 met twee Kroatische bataljons in Gruž aankwam, omsingelde het garnizoen; na vier dagen bombardement stuurde het Franse garnizoen een gezant naar de generaal. Bij het ochtendgloren van 28 januari trokken Oostenrijkse en Britse troepen vanuit Gruž de stad binnen; op 31 januari begon in de regio een voorlopig Oostenrijks bestuur te functioneren. De aansluiting van de stad bij Oostenrijks gebied werd op het Congres van Wenen van 1815 definitief.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Uitroeping van het Koninkrijk Servië — het voormalige aan de Ottomanen onderworpen vorstendom werd een koninkrijk", "7d90e712"], "d": ["Het vorstendom Servië, dat in 1878 zijn onafhankelijkheid verkreeg en in hetzelfde jaar ook het Ottomaanse Niš innam, werd onder Milan Obrenović tot koninkrijk omgevormd. Met het eerste artikel van de in Belgrado uitgevaardigde wet werd het vorstendom uitgeroepen tot Koninkrijk Servië en vorst Milan werd koning onder de naam Milan I; de wet werd op dezelfde dag in de officiële krant Srpske novine gepubliceerd. Zo nam Servië, dat tot 1878 een aan de Ottomanen gebonden vorstendom was, met de koningstitel zijn plaats in op de Balkan. Met deze uitroeping werd het gehele vorstendom Servië (Belgrado, Niš, Jagodina, Vranje, Leskovac, Kurşumlija, Şehirköy enz.) het Koninkrijk Servië.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["Britse civiele mandaatadministratie in Palestina gevestigd — einde van het militaire bestuur in de van de Ottomanen genomen gebieden", "c0d7b76a"], "d": ["Met de inname van Gaza en daarna Jeruzalem door generaal Allenby in 1917 was de vierhonderd jaar durende Ottomaanse heerschappij in Palestina geëindigd en was Jeruzalem in 1917-1920 onder Brits militair bestuur gebleven. De Conferentie van San Remo van 1920 gaf Palestina aan het Britse mandaat; Engeland vestigde vanaf juli 1920 een civiele mandaatadministratie in de regio en begon het land te besturen via een hoge commissaris. Aan het hoofd van het civiele bestuur stond hoge commissaris Herbert Samuel. De Arabische opstanden en Joods-Arabische conflicten die in hetzelfde jaar begonnen, zouden de gehele mandaatperiode kenmerken. Met deze gebeurtenis kwam Tiberias (Palestina) onder Brits civiel mandaatbestuur.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Het Koninkrijk Egypte werd uitgeroepen — sultan Ahmed Fuad nam de titel koning aan", "c6ad08d1"], "d": ["Engeland had op 18 december 1914 de soevereiniteitsrechten van het Ottomaanse Rijk over Egypte eenzijdig opgeheven en het land onder zijn bescherming genomen. Toen de onderhandelingen tussen Engeland en Egypte na de oorlog geen resultaat opleverden, verklaarde Engeland op 28 februari 1922 met opnieuw een eenzijdige verklaring Egypte tot onafhankelijke staat. Sultan Ahmed Fuad nam op 15 maart 1922 de titel koning (malik) aan en in Egypte werd de monarchie uitgeroepen. De TDV beschouwt deze onafhankelijkheid als formeel; de grondwet van de koninklijke orde zou op 19 april 1923 in werking treden.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Het fort Hacıbey (Kachibey) kwam uit Litouwse handen", "382b51e3"], "d": ["De haven Kachibey aan de noordwestkust van de Zwarte Zee was aan het begin van de 15e eeuw door de Litouwse groothertog Vytautas versterkt. In 1480 kwam het fort uit Litouwse handen en kreeg de naam Hacıbey. De kust kwam aan het einde van de 15e eeuw onder controle van het aan de Ottomanen onderworpen khanaat van de Krim; de aansluiting van de regio bij de directe Ottomaanse bestuurlijke organisatie is van 1538.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Het gramota van Ivan IV aan de Donkozakken — de eerste betrouwbare vermelding van het Donkozakkenleger", "16c0732e"], "d": ["Informatie over de aanwezigheid van kozakken aan de Don begint in het midden van de 16e eeuw. Volgens de Russische militaire encyclopedie wordt de anciënniteit van het Donkozakkenleger gerekend vanaf 1570: in dat jaar stuurde tsaar Ivan IV een gramota aan de kozakken die aan de Noordelijke Donets woonden, waarin hij hen vroeg Ivan Novosiltsev, die via Azov als gezant naar de Ottomaanse sultan werd gestuurd, te helpen en beloofde hen daarvoor te belonen. Dit is de eerste betrouwbare vermelding van de dienst van de Donkozakken aan de Moskovische staat. Het belangrijkste centrum van de kozakken werd eerst Boven-Razdory, daarna Tsjerkassk.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moskou vestigde in Voronezj een voorgeschoven garnizoen tegen de steppe", "89c941fe"], "d": ["Aan het einde van de 16e eeuw waren het huidige Sloboda-Oekraïne en het bovenstroomse bekken van de Don een onbewoonde wilde steppe waar de Tataren doorheen trokken bij hun invallen op Moskou. De Moskovische regering vestigde in deze steppe een reeks voorgeschoven garnizoenen; Voronezj werd als een daarvan in 1585 gesticht. Het fort werd in de daaropvolgende decennia, samen met Belgorod en Koersk, een van de eerste schakels van de zuidelijke verdedigingslinie van Moskou.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moskou vestigde Belgorod, Oskol en Koersk als voorgeschoven garnizoenen in de steppe", "4ff3e225"], "d": ["De Moskovische regering schoof de zuidgrens tegen de Krim-invallen naar voren en stichtte in 1596 Belgorod, Oskol en Koersk als garnizoenspunten in de wilde steppe. Belgorod werd vanaf deze datum een vestingstad en het centrum van de 300 kilometer lange Belgorod-verdedigingslinie die zich in de volgende eeuw zou uitstrekken.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["De sandjak Siirt werd van Diyarbakır overgebracht naar het vilayet Bitlis — de kaza Eruh en het dorp Şırnak ook aan Bitlis gebonden", "3922d040"], "d": ["Toen na de Tanzimat van het eyaletstelsel op het vilayetstelsel werd overgestapt, werd de sandjak Siirt, die aan het vilayet Diyarbakır gebonden was gebleven, in 1884 overgebracht naar het vilayet Bitlis. Volgens het lemma Şırnak van de TDV kwamen de gebieden waar het huidige Şırnak ligt zo binnen de kaza Eruh, gebonden aan de sandjak Siirt van het vilayet Bitlis. Şırnak was toen een klein dorp van de kaza Eruh; de naam verschijnt tegen het einde van de 19e eeuw in de registers, dat het kazacentrum werd, blijft voorbehouden aan de eerste jaren van de Republiek. Deze gebieden waren na de Çaldıran-veldtocht in 1514 bij de Ottomanen gevoegd en bestuurd binnen de sandjak Siirt van het eyalet Diyarbakır.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Mosul en Kirkuk kwamen in Safawidische handen — na de val van Bagdad", "86e176c8"], "d": ["Sjah Abbas, die na de gebeurtenissen die begonnen met de opstand van Bekir Subaşı Bagdad innam, stuurde zijn commandant Karchagay Khan met zijn troepen naar Mosul en Kirkuk. Çerkez Ahmed Pasja, gouverneur van Mosul, kon de stad enkele dagen verdedigen; Mosul kwam, net als Kirkuk, onder Iraanse heerschappij en Qasim Khan werd tot gouverneur benoemd. Toen Sipahi Küçük Ahmed, die het bevel voerde over de voorhoede van Hafız Ahmed Pasja, voor Mosul verscheen, liet Qasim Khan de stad achter en trok zich terug naar Bagdad, maar met de tegenoperatie van Sjah Abbas kwam Mosul in 1624 opnieuw in Safawidische handen.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Bevrijding van Mosul van de Safawiden — de Bagdad-veldtocht van Hafız Ahmed Pasja", "1f9ca4a1"], "d": ["Murad IV stuurde het leger onder bevel van grootvizier Hafız Ahmed Pasja naar Bagdad. Terwijl het leger in de buurt van Diyarbakır was, joeg de voorhoede van Çerkez Hasan, beylerbey van Karaman, de pro-Iraanse aanhangers die bij Altınköprü verzameld waren tot Kirkuk achterna en nam de regio, inclusief Kirkuk, onder controle; de Safawiden konden Mosul ook deze keer niet lang vasthouden. Hafız Ahmed Pasja bereikte begin september eerst Mosul en daarna Kirkuk en belegerde op 13 november 1625 Bagdad; het beleg bleef zonder resultaat en Bagdad bleef in Safawidische handen. Het lemma Kerkük van de TDV koppelt de herovering van de stad op de Safawiden echter aan 1630 en Hüsrev Pasja.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Hüsrev Pasja liet het fort Gülanber in Shahrizor herbouwen — het beylerbeylik Shahrizor", "9511853c"], "d": ["Grootvizier Hüsrev Pasja, die voor de Bagdad-veldtocht uittrok, bleef door hevige regenval lange tijd in Mosul en richtte zich daarna op Shahrizor. Met de herbouw van het fort Gülanber, dat bij de invasie van Sjah Abbas op zijn bevel was verwoest, werd begonnen; Shahrizor werd opnieuw centrum van een beylerbeylik gemaakt en Arnavud Mustafa Pasja werd als beylerbey in het fort achtergelaten. Hüsrev Pasja onderwierp de stammen in de regio, nam het fort Mihriban in en bracht op 5 mei 1630 bij dit fort het Safawidische leger zware verliezen toe.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaş Bey nam in de Tundzja-vallei Yeni Kızılcaağaç (Elhovo) en Yambol in", "2c2aebea"], "d": ["Tijdens de operatie van Murad I tegen Bulgarije en Byzantium werd Kara Timurtaş Bey naar de Tundzja-vallei gestuurd; hij nam Yeni Kızılcaağaç en Yambol in en keerde met veel buit terug naar Edirne.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Het vorstendom Dejanović (Kostadin-ili) werd een Ottomaanse vazal", "54b8dd6c"], "d": ["Toen de Servische staat door de nederlaag bij de Maritsa (Çirmen) uiteenviel, stichtten de broers Jovan en Konstantin Dejanović hun eigen vorstendom met als centrum Velbužd (later Köstendil genoemd), dat Štip, Strumica, Dojran en de regio Veles omvatte. Toen Jovan kort daarna stierf, erkende Konstantin de heerschappij van Murad I en werd een Ottomaanse vazal; het vorstendom leefde met deze band semi-onafhankelijk. Toen Konstantin in 1395 bij Rovine aan de zijde van Yıldırım Bayezid sneuvelde, kwam zijn land zonder strijd onder Ottomaans bestuur en werd het onder de naam Kostadin-ili een sandjak.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["De Servische despoot Stefan Lazarević nam Şehirköy (Pirot) in", "87e1ecb3"], "d": ["Terwijl de strijd tussen Musa Çelebi, die tijdens het Interregnum over Rumelië heerste, en zijn broer Çelebi Mehmed voortduurde, nam de Servische despoot Stefan Lazarević het fort Şehirköy aan de weg tussen Niš en Sofia in en hield het in handen tegen de aanval van Musa Çelebi. Het jaar daarop, met de dood van Musa, liet Çelebi Mehmed het fort officieel aan zijn vazal Stefan; de Ottomanen namen Şehirköy pas in 1428 terug na de dood van Lazarević.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Herceg Novi (Castelnuovo) werd door Andrea Doria ingenomen", "a8276ff1"], "d": ["Andrea Doria, commandant van de tegen de Ottomanen verenigde bondgenootschappelijke vloot, nam aan de Adriatische kust het fort Herceg Novi (Castelnuovo) in het zuiden van Dalmatië in. In hetzelfde jaar hadden de Venetianen in Dalmatië ook enkele in Ottomaanse handen zijnde steden ingenomen en hadden de Ottomaanse troepen met andere forten geantwoord. Het fort werd een jaar later teruggenomen; omdat de Ottomaanse soevereiniteit juridisch voortduurde, wordt deze tussenperiode op de kaart met een gearceerde bezettingslaag weergegeven.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Herceg Novi (Castelnuovo) door Barbarossa Hayreddin Pasja teruggenomen", "1e5b49ae"], "d": ["De Ottomanen, die na de overwinning bij Preveza ook in de Midden-Middellandse Zee de overhand hadden gekregen, richtten zich op het fort Nova (Castelnuovo) aan de Adriatische kust, dat Andrea Doria een jaar eerder had ingenomen. Aan het einde van de operatie die Barbaros Hayreddin Pasja en Gazi Husrev Bey, bey van Bosnië, gezamenlijk uitvoerden, werd het fort teruggenomen en eindigde de bezetting.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["De Opper-Egypte-veldtocht van Desaix — de Franse divisie bereikte Minya, Asyut en Girga", "8ff8e4fe"], "d": ["Terwijl Napoleon in Caïro zat, rukte de divisie van generaal Desaix, de Mamelukse troepen achtervolgend, in de Nijlvallei naar het zuiden op: zij bereikte op 21 december 1798 Minya, op eerste kerstdag Asyut en op 29 december Girga. Met deze mars, die in februari 1799 Aswan bereikte, kwam de vallei tussen Caïro en Aswan onder Franse controle.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleon bezette El Arish — begin van de Syrische veldtocht", "69dc52ce"], "d": ["Het Franse leger dat Egypte bezette, nam bij zijn mars naar Syrië El Arish aan de Sinaï-kust in.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["El Arish op de Fransen teruggenomen", "c25e48a7"], "d": ["El Arish, dat Napoleon in februari 1799 bezette, werd aan het einde van december van hetzelfde jaar door het leger van grootvizier Yusuf Ziya Pasja teruggenomen.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Nederlaag bij Stavuchany en overgave van Chotyn aan de Russen (Ottomaans-Russische oorlog van 1736-1739)", "657d82d2"], "d": ["In de veldtocht van 1739 trok het Russische hoofdleger onder bevel van maarschalk Münnich door Pools grondgebied Moldavië binnen en bracht bij Stavuchany nabij Chotyn het leger van serasker Veli Pasja een zware nederlaag toe. Direct na deze slag gaf het fort Chotyn zich over aan de Russen en trok het Russische leger begin september Iași binnen. Doordat Oostenrijk echter een afzonderlijke vrede sloot, eindigde de oorlog met het in dezelfde maand ondertekende Verdrag van Belgrado.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Het Russische leger stak de Dnjestr over en trok Moldavië binnen (Ottomaans-Russische oorlog van 1768-1774)", "938bd834"], "d": ["Ongeveer zes maanden na de oorlogsverklaring verzamelde het Russische hoofdleger zich onder bevel van prins Golitsyn in Podolië. Op de oproep van Dositej, metropoliet van Moldavië, om Moldavië onder Russische bescherming te plaatsen, stak Golitsyn de Dnjestr over en probeerde Chotyn in te nemen voordat hij naar Iași zou marcheren. Deze eerste poging mislukte, het leger keerde wegens voedselgebrek terug naar Podolië; Chotyn viel pas in september 1769.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Het Russische Oekraïense leger stak bij Mogilev de Dnjestr over en trok Moldavië binnen (Ottomaans-Russische oorlog van 1787-1792)", "822c7361"], "d": ["In de oorlog die in 1787 met de Ottomaanse oorlogsverklaring begon, vormde Rusland twee legers: terwijl het leger van Potjomkin Özi belegerde, zou het Oekraïense leger van Roemjantsev tussen de Dnjestr en de Boeg Bender bedreigen en de verbinding met Oostenrijk houden. Roemjantsev detacheerde een colonne ter ondersteuning van de Oostenrijkers die Chotyn belegerden, stak met zijn hoofdmacht bij Mogilev de Dnjestr over en trok Moldavië binnen. Zo begon de Moldavische poot van de Russische operatie die zich naar Izmajil en de Donau zou uitstrekken.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Het Russische leger stak zonder oorlogsverklaring de Dnjestr over en begon de bezetting van de Donauvorstendommen (Ottomaans-Russische oorlog van 1806-1812)", "2094a4d9"], "d": ["In oktober 1806 kreeg generaal Michelson bevel Moldavië en Walachije te bezetten; de oorlog was nog niet officieel verklaard. De Russische troepen begonnen de Dnjestr over te steken en de commandanten van de forten Chotyn, Bender, Akkerman en Kilia gaven hun forten zonder gevecht over. Alleen de bewaker van Izmajil boog niet voor de Russische overreding. De oorlogsverklaring van de Hoge Poort kwam na deze bezetting.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Akkerman door de Russen ingenomen (1806)", "25aed8d6"], "d": ["Een week nadat het Russische leger zonder oorlogsverklaring de Dnjestr was overgestoken, werd Akkerman door de troepen van prins Kantakuzino ingenomen; de Tataren in de stad verlieten de stad. Akkerman werd met het Verdrag van Boekarest van 1812 samen met Bessarabië aan Rusland gelaten.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Miloradovitsj trok Boekarest binnen — Russische bezetting van Walachije", "62e4a8e1"], "d": ["Toen het Russische leger Moldavië binnentrok, stuurde Mustafa Pasja, bewaker van Roese, een macht naar Boekarest en deze macht hield de stad. De afdeling van generaal Miloradovitsj verdreef hen uit de stad; de Ottomaanse macht trok zich terug naar Giurgiu. Boekarest bleef vanaf deze datum tot het Verdrag van Boekarest van 1812 onder Russische bezetting.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Overgave van Silistra aan de Russen", "d687d04b"], "d": ["Silistra, dat in de herfst van 1809 het beleg van Bagration had doorstaan, werd in de veldtocht van 1810 op bevel van opperbevelhebber Kamenski opnieuw belegerd. Het belegeringswerk, dat eind mei begon, duurde enkele dagen en het fort gaf zich over op voorwaarde dat het garnizoen vrij mocht vertrekken. In dezelfde dagen werd Razgrad bij storm ingenomen en viel Hezargrad. De Russen hielden Silistra een jaar; in het voorjaar van 1811 liet Koetoezov de muren opblazen en liet het fort achter.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Overgave van Nikopol en Turnu aan de Russen zonder weerstand", "e297a862"], "d": ["Na de overgave van Roese en Giurgiu marcheerde opperbevelhebber Kamenski langs de rivier naar het westen om de Donauforten tot aan de Servische grens in te nemen. Nikopol en Turnu aan de overkant gaven zich zonder weerstand over; Russische afdelingen namen Plevna, Lovech en Selvi in en sloopten de versterkingen. De Russen hielden Nikopol zes maanden en lieten het fort in april 1811 opgeblazen achter.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Slag bij Roese en het slopen van Roese door Koetoezov en zijn terugtrekking naar de linkeroever van de Donau", "6af4bf85"], "d": ["Begin juni viel de grootvizier, die uit Şumnu was uitgetrokken, het Russische leger voor Roese aan, werd verslagen en trok zich terug naar zijn versterkte stelling in het zuiden. Koetoezov vond het ondanks de gewonnen slag gevaarlijk in Roese te blijven; hij liet de versterkingen van het fort slopen en bracht al zijn troepen over naar de linkeroever van de Donau. De grootvizier nam het ontruimde Roese opnieuw in. Zo duurde de Russische greep op de stad, die Kamenski op 26 september 1810 na een bloedig beleg had overgenomen, negen maanden. Volgens het register van de TDV gaf Koetoezov voor zijn vertrek bevel de versterking rond de stad en het middeleeuwse fort op te blazen; bij de brand die ontstond, werden van de achtendertig moskeeën die in 1810 in de stad waren twaalf en van de acht mescids twee volledig verwoest. De oversteek van de Donau door het Ottomaanse leger in de herfst van hetzelfde jaar zou eindigen met het beleg van Slobozia.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Het Russische 6e Infanteriekorps stak de Pruth over en trok de Donauvorstendommen binnen (Ottomaans-Russische oorlog van 1828-1829)", "9d9aaaad"], "d": ["Na de Russische oorlogsverklaring ging het leger van maarschalk Wittgenstein tot de operatie over. Het 6e Infanteriekorps stak de Pruth over en trok Moldavië en Walachije binnen, zijn voorhoede onder bevel van generaal Geismar richtte zich op Klein-Walachije. Enkele dagen later belegerde het 7e Korps Brăila; het 3e Korps maakte zich ondertussen klaar om tussen Izmajil en Reni de Donau over te steken. De Donauvorstendommen zouden tot 1834 onder Russische bezetting blijven.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Overgave van Silistra aan Diebitsch — Russische bezetting die tot 1836 zou duren", "55e28ab1"], "d": ["Aan het begin van de veldtocht van 1829 koos de nieuwe Russische opperbevelhebber Diebitsch Silistra als eerste doel. Het garnizoen weerstond hardnekkig de belegeringswerken onder leiding van generaal Schilder; Diebitsch liet een deel van zijn troepen bij het beleg achter en marcheerde achter de grootvizier aan. Het beleg duurde voort en het fort gaf zich over. De Russen hielden Silistra ook na het einde van de oorlog tot 1836 in handen.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Ontruiming van Silistra door de Russen", "4fe2afaf"], "d": ["Na het Verdrag van Edirne van 1829 ontruimden de Russen Silistra niet en hielden het fort tot 1836 in handen. Na het vertrek van de Russische soldaten liet gouverneur Selim Pasja midden in de voor de helft verwoeste stad een grote moskee met één koepel bouwen.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Het Russische leger stak de Pruth over en begon de bezetting van de Donauvorstendommen (Walachije-Moldavië) — de weg naar de Krimoorlog", "77862041"], "d": ["Toen de eisen van Mensjikov in het geschil over de heilige plaatsen in Jeruzalem door de Hoge Poort werden afgewezen, gaf tsaar Nicolaas I bevel de aan de Ottomanen gebonden Donauvorstendommen te bezetten 'als onderpand totdat Turkije aan onze gerechtvaardigde eisen voldoet'. De voorhoede van het leger onder bevel van prins Gortsjakov stak de Pruth over en trok twaalf dagen later Boekarest binnen; daarna verspreidde de hoofdmacht zich in drie colonnes over de vorstendommen. Deze zonder oorlogsverklaring uitgevoerde bezetting leidde tot een diplomatieke crisis in Europa en in oktober 1853 tot de Ottomaanse oorlogsverklaring; de Russen ontruimden de vorstendommen pas in de zomer van 1854 onder druk van Oostenrijk.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["De Mushasha'iyya vestigden zich in Hawiza — begin van het Mushasha'i-bestuur in Khuzestan", "674d0173"], "d": ["Muhammad b. Falah, die optrad met de aanspraak de Mahdi te zijn, wist zich onder de Mahdi-stammen te handhaven en slaagde er het jaar daarop in zich te vestigen in Hawiza, dat onder controle van de Timoeriden stond. De stad werd het centrum van de Mushasha'i-dynastie, die in Khuzestan zou heersen.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Sjah Ismail onderwierp Hawiza — de Mushasha'iyya werden vazalgouverneurs van de Safaviden", "7e245f4d"], "d": ["Sjah Ismail liet enkele leden van de Mushasha'i-dynastie, die hij van ketterij beschuldigde, ombrengen en bracht het gebied van Hawiza onder zijn eigen bestuur. De Mushasha'i-leiders zetten hun bestaan daarna voort als gouverneurs die aan de Safaviden onderworpen waren.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["De forten Pasin, Çöregel en Oltu werden op de Safaviden veroverd — tussen Erzurum en Kars", "68f297aa"], "d": ["Tijdens de Irakeyn-veldtocht van Süleyman de Wetgever werden de forten Pasin, Çöregel en Oltu tussen Erzurum en Kars op de Safaviden veroverd.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Özdemir Pasja nam de haven van Massawa in", "4cc1d4ad"], "d": ["Özdemir Pasja, beylerbey van het eyalet Habesh, nam na de inname van de Dahlak-eilanden op 2 april 1557 de stad Massawa aan de overkant in; daarna kwam ook Arkiko onder Ottomaans bestuur. Zo kwam de belangrijkste haven van Abessinië aan de Rode Zee in Ottomaanse handen.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Het Graafschap Nice werd bij Frankrijk gevoegd", "a140cab2"], "d": ["Na de aansluiting van Savoye in november 1792 bekrachtigde de Franse Nationale Conventie op 31 januari 1793 de aansluiting van het Graafschap Nice, dat bij het Koninkrijk Sardinië hoorde, bij Frankrijk; de regio werd het departement Alpes-Maritimes. Nice keerde na de nederlaag van Napoleon met het Eerste Verdrag van Parijs van 30 mei 1814 terug naar Sardinië.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Slag bij Rafa — Britse en Anzac-cavalerie namen de stellingen bij Magruntein en Rafa in", "5053c8ef"], "d": ["De Anzac Mounted Division, de Imperial Camel Corps Brigade en een Britse yeomanrybrigade van de Egyptian Expeditionary Force, die de Sinaï was overgestoken, vielen de Osmaanse stelling bij Magruntein, ongeveer een kilometer ten zuiden van Rafa, aan, die met schansen werd gehouden. Na een zware strijd brak de doorbraak van de Nieuw-Zeelanders en de kameeltroepen de Osmaanse verdediging; de stelling en het nabijgelegen Rafa werden ingenomen en de Britse troepen bereikten de grens van Palestina.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Winteroffensief van Kâzım Karabekir: samen met Erzurum werd Hasankale (Pasinler) heroverd", "27df4879"], "d": ["Na de ontbinding van het Russische leger gingen de Osmaanse strijdkrachten onder bevel van Kâzım Karabekir Pasja in het oosten tot actie over; ondanks de zware winteromstandigheden heroverden zij Erzincan, Erzurum en Hasankale ten oosten van Erzurum. Het offensief reikte op 25 april 1918 tot Kars.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Britse bezetting van Eskişehir", "8e349037"], "d": ["Na de Wapenstilstand van Mudros begonnen de Entente-mogendheden de spoorwegknooppunten van Anatolië onder controle te brengen. Volgens het lemma Eskişehir van de TDV werd de stad op 23 januari 1919 door de Britten bezet. De Britse troepen ontruimden Eskişehir op 20 maart 1920.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Landing van de Italianen aan de kusten van Zuidwest-Anatolië — Marmaris, Bodrum, Kuşadası", "15d6fb7a"], "d": ["Italië, dat zich op de Vredesconferentie van Parijs uit de conferentie had teruggetrokken uit protest tegen de pro-Griekse houding van zijn bondgenoten, liet na Antalya troepen aan land gaan aan de zuidwestkust. Volgens de TDV werden Marmaris op 5 mei, Bodrum op 11 mei en Kuşadası op 13 mei door de Italianen bezet. In dezelfde dagen gingen ook de Grieken bij Fethiye aan land; de rivaliteit van de twee staten over West-Anatolië bereidde de weg naar de bezetting van İzmir voor.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Intocht van de Griekse troepen in Manisa en Aydın", "a4230775"], "d": ["Het Griekse leger dat op 15 mei bij İzmir aan land was gegaan, verspreidde zich snel over het binnenland. Volgens het lemma Manisa van de TDV trokken de Griekse troepen op 26 mei 1919 de stad binnen; volgens het lemma Aydın werd Aydın de volgende dag, 27 mei, bezet. De bezetting van Manisa zou tot september 1922 duren.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Italiaanse bezetting van Burdur — terugtrekking van de compagnie die naar Isparta optrok", "874e9d6d"], "d": ["De Italianen die Antalya hadden bezet, rukten op naar het binnenland. Volgens het lemma Isparta van de TDV bezetten de Italiaanse troepen op 28 juni Burdur en trokken op 15 augustus met een compagnie soldaten naar Isparta. Toen de bevolking van Isparta het voorstel om de wapens in te leveren afwees en liet weten dat zij zich zou verzetten, trokken de Italianen zich de volgende dag terug.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Korte bevrijding van Aydın en de herbezetting op 4 juli", "753c739f"], "d": ["Tegen de Griekse bezetting werden rond Ödemiş, Nazilli en Aydın nationale strijdkrachten georganiseerd. Volgens het lemma Aydın van de TDV werd de op 27 mei 1919 bezette stad op 30 juni korte tijd bevrijd, maar op 4 juli opnieuw door de Grieken bezet. De stad bleef daarna tot 7 september 1922 bezet.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Italiaanse bezetting van Muğla", "a4f5a926"], "d": ["Italië breidde zijn bezetting aan de zuidwestkust uit naar het binnenland. Volgens het lemma Muğla van de TDV werd de stad op 23 juli 1919 door de Italianen bezet. De bezetting van Muğla duurde tot 5 juli 1921.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Begin van het Franse militaire bestuur in West-Thracië", "5801e6de"], "d": ["West-Thracië, dat in handen was van het Bulgarije dat de Eerste Wereldoorlog had verloren, werd tijdens de vredesonderhandelingen onder controle van de Entente-mogendheden gebracht. Volgens het lemma Batı Trakya van de TDV werd de regio op 15 oktober 1919 door Franse troepen bezet; de Vereniging voor Rechtsverdediging van West-Thracië verplaatste in deze periode haar centrum naar Gümülcine. Het Franse bestuur duurde tot de regio in mei 1920 krachtens het besluit van San Remo aan Griekenland werd gelaten.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Ontruiming van Eskişehir door de Britten", "6820e164"], "d": ["Eskişehir, dat sinds januari 1919 onder Britse bezetting stond, werd volgens het lemma Eskişehir van de TDV op 20 maart 1920 door de Britten ontruimd. De stad werd enkele maanden later, in juni 1920, het centrum van het Westelijke Front dat de TBMM had gevormd.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Het Griekse zomeroffensief — bezetting van Akhisar, Soma, Balıkesir en Alaşehir", "f096d2b4"], "d": ["Nadat de geallieerden het Griekse leger toestemming hadden gegeven de Milne-lijn te overschrijden en op te rukken, begon een groot Grieks offensief in West-Anatolië. Volgens het lemma Millî Mücadele van de TDV namen de Griekse eenheden, die op 22 juni in drie colonnes optrokken, Akhisar, Kırkağaç, Soma en Balıkesir in. In het zuiden werd op 26 juni Alaşehir en op 3 juli Nazilli bezet.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Griekse bezetting van Bursa", "7c2b32a1"], "d": ["De noordelijke colonne van het zomeroffensief richtte zich na Balıkesir op de Marmara. Volgens de lemma's Bursa en Millî Mücadele van de TDV werd Bursa op 8 juli 1920 door de Grieken bezet. De oneerbiedigheid jegens de mausolea van de eerste Ottomaanse heersers veroorzaakte in het hele land grote reactie.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Bezetting van Oost-Thracië door het Griekse leger — Edirne en Kırklareli", "9eb3bda1"], "d": ["Griekenland begon, voordat het Verdrag van Sèvres was ondertekend, ook Oost-Thracië feitelijk in te nemen. Volgens het lemma Millî Mücadele van de TDV nam het Griekse leger op 20 juli heel Thracië in; deze ontwikkeling bracht in Constantinopel de sultan ertoe twee dagen later de Saltanat Şûrası bijeen te roepen. Kırklareli werd op 26 juli bezet en ook Edirne kwam in dezelfde maand onder Grieks bestuur.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Intocht van het Rode Leger in Nachitsjevan", "6dcb9005"], "d": ["De Britten, die begin 1919 de regio waren binnengetrokken, hadden de Araks-Republiek ontbonden en in de zomer van hetzelfde jaar Nachitsjevan verlaten. Volgens het lemma Nahçıvan van de TDV trok het Rode Leger op 28 juli 1920 Nachitsjevan binnen en gaf het bestuur aan de communisten, waarna de Socialistische Sovjetrepubliek Nachitsjevan werd gesticht. De status van de regio werd met het in 1921 in Kars ondertekende verdrag vastgesteld als een aan Azerbeidzjan gebonden autonome eenheid.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Griekse bezetting van Uşak", "74ad2713"], "d": ["Het Griekse leger zette zijn opmars voort om het door Ankara niet erkende Verdrag van Sèvres te laten aanvaarden. Volgens de lemma's Uşak en Millî Mücadele van de TDV werd na Gediz op 29 augustus 1920 ook Uşak bezet. Mustafa Kemal Pasja had de Kuva-yi Milliye-eenheden in de stad ongeveer een maand vóór deze bezetting geïnspecteerd.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Griekse bezetting van İnegöl en Yenişehir", "4a0460e7"], "d": ["De Griekse eenheden in Bursa begonnen naar het oosten, in de richting van Eskişehir, op te rukken. Volgens het lemma Millî Mücadele van de TDV werden İnegöl en Yenişehir op 25 oktober 1920 ingenomen. Toen bleek dat de Griekse opmars niet met milities kon worden gestopt, werd het westelijke front opnieuw georganiseerd op basis van een regulier leger.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Einde van de Italiaanse bezetting van Burdur (jaar)", "609123c8"], "d": ["Burdur, dat op 28 juni 1919 door de Italianen was bezet, maakte volgens het lemma Burdur van de TDV tussen 1919 en 1921 een korte Italiaanse bezetting mee. De bron geeft de dag van de ontruiming niet; op de kaart eindigt de bezetting aan het begin van het jaar 1921. Italië trok zich in de zomer van 1921 volledig terug uit zijn bezettingsgebied in Anatolië.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Tweede offensief van het Griekse leger — bezetting van Bilecik, Afyon en Adapazarı", "9ae146e2"], "d": ["Het Griekse leger, dat na de nederlaag bij Eerste İnönü nieuwe troepen bij İzmir aan land liet gaan, ging opnieuw tot de aanval over voordat de door de Conferentie van Londen erkende termijn was verstreken. Volgens het lemma Millî Mücadele van de TDV bezetten de Grieken op 23 maart Bilecik en Afyon. In het noorden werd ook Adapazarı op 25 maart door de Grieken bezet.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Ontruiming van Batumi door de Turkse troepen", "ba5745dc"], "d": ["Toen de Britten in juli 1920 uit de Kaukasus vertrokken, hadden zij Batumi ontruimd en had de Georgische regering de stad in beslag genomen. Volgens het lemma Batum van de TDV liet het Verdrag van Moskou, dat op 16 maart 1921 met Sovjet-Rusland werd ondertekend, Batumi aan Georgië. De Turkse troepen ontruimden de stad op 28 maart 1921 en Batumi werd het centrum van de binnen Georgië gestichte Autonome Republiek Ajarië.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Herovering van Afyon — de gevechten van Aslıhanlar", "2bbba17b"], "d": ["Na het Griekse offensief dat op 1 april bij Tweede İnönü tot staan werd gebracht, werd aan het zuidelijke front Afyon op 7 april heroverd. Het lemma Millî Mücadele van de TDV vat dit samen als 'na een zware nederlaag bij Aslıhanlar werd Afyon op 7 april heroverd'; militair-historische studies plaatsen de gevechten van Aslıhanlar-Dumlupınar echter na de ontruiming van Afyon, tussen 8 en 15 april, en schrijven dat het tactische overwicht aan de Griekse kant bleef — de twee verhalen komen niet overeen, beide zijn gegeven. De overwinning bij İnönü werd met meetings in het hele land, voorop in Constantinopel, gevierd.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Bevrijding van İzmit — na Adapazarı", "cec60e36"], "d": ["Adapazarı, dat in maart 1921 door de Grieken was bezet, werd volgens het lemma Adapazarı van de TDV op 21 juni heroverd. Volgens het lemma İzmit van de TDV werd ook İzmit, dat op 6 juli 1920 eerst door de Britten en daarna door de Grieken was bezet, op 28 juni 1921 bevrijd. De Grieken staken bij hun vertrek uit de stad het bazaargedeelte in brand.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Bevrijding van Muğla van de Italiaanse bezetting", "143ddf98"], "d": ["Italië begon in de zomer van 1921 zich terug te trekken uit zijn bezettingsgebied in Anatolië; de ontruiming van Antalya was op 1 juni begonnen. Volgens het lemma Muğla van de TDV werd Muğla, dat sinds 23 juli 1919 onder Italiaanse bezetting stond, op 5 juli 1921 bevrijd.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Ontruiming van Eskişehir — het Griekse leger trok Eskişehir, Kütahya en Bilecik binnen", "a948a74d"], "d": ["Het Turkse leger, dat in de gevechten van Kütahya-Eskişehir onvoorbereid werd betrapt, trok zich op bevel van Mustafa Kemal Pasja terug ten oosten van de Sakarya. Volgens de lemma's van de TDV trokken de Grieken op 20 juli 1921 Eskişehir, op 21 juli Kütahya en op 22 juli Bilecik binnen. De Griekse koning Konstantijn zat op 28 juli in Kütahya een krijgsraad voor en het leger maakte zich klaar voor een aanval in de richting van Ankara.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Terugtrekking van de Italiaanse troepen uit Marmaris en Kuşadası", "1d672994"], "d": ["De Italianen, die sinds mei 1919 langs de kust van Zuidwest-Anatolië aanwezig waren, ontruimden na hun toenadering tot de regering in Ankara het bezette gebied stap voor stap. Antalya en Bodrum waren in de zomer van 1921 ontruimd; de laatste Italiaanse troepen verlieten eind april 1922 ook Kuşadası en Marmaris.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Het Grote Offensief begon", "efba4bd3"], "d": ["Na een voorbereiding van een jaar na Sakarya ging het Turkse leger aan het Afyon-front tot het algemene offensief over. Volgens de lemma's Millî Mücadele en Kütahya van de TDV begon het Grote Offensief op de ochtend van 26 augustus 1922 bij Afyon en werd het verzet van het Griekse leger in korte tijd gebroken.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Bevrijding van Afyon", "beaeef23"], "d": ["Op de tweede dag van het offensief werd het Griekse front voor Afyon doorbroken. Volgens het lemma Afyonkarahisar van de TDV werden aan het einde van het Grote Offensief, dat Atatürk persoonlijk leidde, de Griekse troepen in de pan gehakt en werd de stad op 27 augustus 1922 bevrijd. Deze dag wordt gevierd als de bevrijdingsdag van Afyon.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["De Slag van de Opperbevelhebber — bevrijding van Kütahya", "376d3118"], "d": ["De hoofdmacht van het Griekse leger werd tussen Afyon en Dumlupınar omsingeld. Volgens het lemma Millî Mücadele van de TDV werd de omsingelingsoperatie op 30 augustus voltooid met de Slag van de Opperbevelhebber, die Opperbevelhebber Mustafa Kemal Pasja persoonlijk leidde. Volgens het lemma Kütahya van de TDV bevrijdde op dezelfde dag een cavaleriedivisie Kütahya, dat door de zich terugtrekkende Griekse troepen in brand was gestoken en verwoest.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Bevrijding van Uşak", "0f2d44d1"], "d": ["Na de Slag van de Opperbevelhebber trokken de resten van het Griekse leger zich terug naar het westen, in de richting van İzmir. Volgens het lemma Uşak van de TDV werd Uşak, dat sinds 29 augustus 1920 bezet was, op 1 september 1922 bevrijd met de intocht van de nationale strijdkrachten in de stad. Bij de brand die de terugtrekkende bezettingstroepen aanstichtten, brandde ongeveer driekwart van de stad af.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Bevrijding van Eskişehir", "f442de5c"], "d": ["Aan de noordflank van het Grote Offensief moesten de Griekse troepen ook Eskişehir verlaten. Volgens het lemma Eskişehir van de TDV werd de stad, die sinds 20 juli 1921 bezet was, na de overwinning van 30 augustus op 2 september 1922 bevrijd. Aan het einde van de dertien maanden durende bezetting was het bazaargedeelte in brand gestoken en was de stad voor de helft verwoest.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Bevrijding van Bilecik", "35dbd49b"], "d": ["Volgens het lemma Bilecik van de TDV werd de stad tijdens de Nationale Strijd driemaal door de Grieken bezet; de derde bezetting, die op 22 juli 1921 begon, eindigde op 6 september 1922. Bij de brand die de Griekse troepen bij het ontruimen van de stad aanstichtten, brandde het grootste deel van de huizen, winkels en het regeringsgebouw af.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Bevrijding van Aydın", "ef1280b5"], "d": ["Toen het Turkse leger İzmir naderde, trokken ook de Griekse troepen in de Meander-vallei zich terug. Volgens het lemma Aydın van de TDV werd de stad op 7 september 1922, gedeeltelijk verwoest en met een sterk verminderde bevolking, door de Turkse troepen bevrijd. De terugtrekkende Grieken hadden het grootste deel van de stad in brand gestoken.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Herovering van Bursa", "6ad1da0b"], "d": ["Na de bevrijding van İzmir rukte het Turkse leger in het noorden op naar de kusten van de Marmara. Volgens het lemma Bursa van de TDV werd de stad, die sinds 8 juli 1920 onder Griekse bezetting stond, op 10-11 september 1922 heroverd. Dat het leger vanhier naar Çanakkale optrok, bracht de Britten in verwarring en opende de weg naar de besprekingen van Mudanya.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Overname van Oost-Thracië — Kırklareli en Tekirdağ", "2a08d65c"], "d": ["De Wapenstilstand van Mudanya voorzag in de ontruiming van Oost-Thracië door het Griekse leger en de overdracht aan Turkije; Refet Pasja, belast met de overname van Thracië, kwam op 19 oktober naar Constantinopel. Volgens de TDV werd Kırklareli, dat sinds 26 juli 1920 bezet was, op 10 november 1922 teruggenomen en werd ook Tekirdağ overeenkomstig de wapenstilstand op 13 november aan de Turken teruggegeven. Zo werd Oost-Thracië zonder strijd bij Turks grondgebied gevoegd.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna voegde de streken Tokat, Kayseri en Samsun bij zijn gebied", "4a088f9f"], "d": ["Emir Eretna, die als Ilkhanidisch gouverneur macht had verworven in Anatolië, wist de steun van de Mamlukse sultan an-Nasir Muhammad opnieuw te winnen en breidde in 1339 zijn grenzen uit en voegde de streken Tokat, Kayseri en Samsun bij zijn gebied. Ook de streek Zamantı ten oosten van Kayseri kwam in deze periode onder het bestuur van Eretna. Het beylik riep in 1341 bij de dood van an-Nasir zijn onafhankelijkheid uit.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Dulkadirid Halil Bey breidde zijn grenzen uit tot Zamantı", "aa911e87"], "d": ["Nadat Mehmed Bey op jonge leeftijd aan het hoofd van het beylik van Eretna was gekomen, werd het zwakker en namen de Turkmeense invallen vanuit het zuiden in het Eretna-gebied toe. In 1360 nam Ömer Bey, een van de Turkmeense leiders, Malatya in, terwijl de Dulkadirid Halil Bey de grenzen van zijn beylik uitbreidde tot Zamantı, ten oosten van Kayseri. Zo kwam de streek Zamantı tussen Elbistan en Kayseri in handen van de Dulkadiriden, en het beylik hield dit gebied in handen tot de Osmaanse annexatie van 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Bayezid Yıldırım nam Constantinopel opnieuw nauw in belegering", "244834ca"], "d": ["Constantinopel, dat sinds 1391 met tussenpozen geblokkeerd was, werd in het voorjaar van 1394 door Bayezid Yıldırım opnieuw nauw ingesloten. De betrekking met Byzantium, dat sinds 1371 schatting aan de Osmanen betaalde en militaire hulp zond, veranderde zo in openlijke vijandschap. De belegering werd opgeheven door het opkomende gevaar van Timoer en de Slag bij Ankara in 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Vrede tussen Murad II en Byzantium — Byzantium stemde ermee in opnieuw schatting te betalen", "6474d704"], "d": ["Murad II, die in 1422 Constantinopel belegerd had tegen Byzantium dat Düzmece Mustafa steunde, ondertekende op 22 februari 1424 een vredesverdrag met de Byzantijnse keizer. Met dit verdrag stemde Byzantium ermee in opnieuw schatting aan de Osmanen te betalen en de plaatsen die het na 1402 aan de kusten van de Marmara, de Egeïsche Zee en de Zwarte Zee had veroverd, terug te geven, met uitzondering van de kastelen Silivri en Terkos; de jaarlijkse schatting waarvan het in 1403 door het verdrag met Emir Süleyman was bevrijd, keerde zo terug. Byzantium zette deze toestand voort tot de verovering van Constantinopel in 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["De forten Bayburt en Kığı werden door de Safaviden overgedragen — Erzincan en Bayburt aan Bıyıklı Mehmed Bey gegeven", "2c7fd65e"], "d": ["Terwijl Yavuz Sultan Selim, op terugweg uit Tabriz na de overwinning bij Çaldıran, in het legerkamp was, kwam het bericht dat de forten Bayburt en Kığı waren overgedragen. Bıyıklı Mehmed Bey, de sanjakbey van Trabzon, en Mustafa Bey, de sanjakbey van Yanya, namen Bayburt, dat werd verdedigd door Kara Maksud-i Sultani, een van de emirs van Sjah Ismail, in oktober 1514 in. Erzincan, dat zonder strijd onder Osmaanse heerschappij kwam, werd samen met Bayburt op 23 oktober 1514 als beylerbeylik aan Bıyıklı Mehmed Bey gegeven en Bayburt werd tot sanjakcentrum gemaakt.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Yavuz Sultan Selim keerde van de Tabriz-veldtocht terug naar Amasya en overwinterde daar", "49d51f94"], "d": ["Yavuz Sultan Selim, die negen dagen in Tabriz bleef, zag wegens voedseltekorten en de onwil van de soldaten ervan af de winter in Iran door te brengen en keerde via Kars en Bayburt terug. De padisjah, die het Ramadanfeest in Niksar vierde, bereikte Amasya en overwinterde daar. Hij was van plan het volgende jaar opnieuw tegen de Safaviden op te trekken; in Amasya begon de druk van de janitsaren om naar Constantinopel terug te keren, en de veldtocht werd in het voorjaar van 1515 voortgezet met de verovering van Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Walachije, Moldavië en Transsylvanië kwamen gezamenlijk tegen de Osmanen in opstand", "e71d3ee9"], "d": ["Medio 1594 besloten de drie vorstendommen ten noorden van de Donau — Walachije, Moldavië en Transsylvanië — gezamenlijk tegen de Osmanen op te treden. De Moldavische woiwode Aron Tiran trad toe tot de Heilige Liga, gevormd door de Oostenrijkse keizer en paus Clemens VIII, en stelde zichzelf onder het Vorstendom Transsylvanië; de Walachijse woiwode Mihai Viteazul sloot zich uit ongenoegen over de zware belastingdruk bij de beweging aan. Op 13 november 1594 braken in Walachije en Moldavië gelijktijdig opstanden tegen het Osmaanse bestuur uit, en met steun van Transsylvanië sloeg de beweging over naar het zuiden van de Donau, het Osmaanse grondgebied in. Volgens de TDV Islam Ansiklopedisi opende dit drievoudige bondgenootschap het noordelijke front van de Osmaans-Habsburgse Lange Oorlog (1593-1606), die in dezelfde jaren voortduurde.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Verovering van het fort Ostrovica in de Una-vallei", "5c6cc91b"], "d": ["Ostrovica, in handen van de Frankopanen en andere Kroatische edelen, lag op een steile bergrug die de noordelijke en zuidelijke delen van de Una-vallei verbond. Het kwam in 1523 onder Ottomaans bestuur en droeg tot 1878 een Ottomaans garnizoen. Het fort verwierf zijn eigenlijke belang na Karlowitz (1699): vanwege de nabijheid van de Venetiaanse en Oostenrijkse grens werd het uitgebreid en werd het het centrum van de kapetanija Stara Ostrovica; de stad Kulen Vakuf werd aan het begin van de 18e eeuw aan de voet ervan gesticht.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Verovering van de forten Udbina en Krbava — Lika komt onder Ottomaans bestuur", "5fe329d3"], "d": ["De vlakte van Krbava was in 1524 ontruimd, in Udbina was alleen het garnizoen van Karlović overgebleven. Karlović behaalde in april 1527 voor het fort een laatste overwinning, maar eind mei kwamen Udbina, samen met de forten Mrsinj en Komić, in handen van de pasja van Bosnië. In hetzelfde jaar werd de omgeving van Gospić aan de Senković-aga's gegeven. Lika en Krbava werden daarna deel van de sandjak met Obrovac als centrum, die in 1580 de naam Kırka kreeg.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Definitieve overgang van Drežnik en de župa Drežnik onder Ottomaans bestuur", "6624ad14"], "d": ["Drežnik, sinds 1323 in handen van de Frankopanen, was in 1578 tijdelijk door de Ottomanen gehouden. In 1592 kwamen het fort en de hele župa Drežnik definitief onder Ottomaans bestuur; in hetzelfde jaar viel ook Bihać. Drežnik was in de 18e eeuw aan de kapetanija Ostrožac gebonden.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Inname van het fort Cetin door de Ottomanen", "98815f97"], "d": ["Cetin, sinds het midden van de 16e eeuw het sleutelfort in de verdediging van de regio Slunj tegen de Ottomanen, kwam in 1636 na herhaalde belegeringen onder Ottomaans bestuur. Deze eerste Ottomaanse periode duurde twee jaar.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Terugkeer van het fort Cetin naar de Habsburgse zijde", "690f9f84"], "d": ["Cetin, dat in 1636 in Ottomaanse handen was gekomen, keerde in 1638 terug naar de Kroatisch-Habsburgse grensverdediging en bleef dat tot 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin werd opnieuw een Ottomaans fort", "e1750675"], "d": ["Cetin werd in 1670 opnieuw een Ottomaans fort en werd in de 18e eeuw grondig versterkt: het middeleeuwse fort werd omringd door muren met bastions. Het fort hield tot 1790 de noordwestelijke punt van de Bosnische grens.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Verlies van Lika en Krbava — Udbina en Gospić kwamen in handen van de Habsburgse grenstroepen", "01277a38"], "d": ["In de oorlog die na de nederlaag bij Wenen voortduurde, namen de Kroatische grenstroepen onder bevel van Herberstein, generaal van Karlovac, in 1689 Udbina in; ook Gospić kwam in hetzelfde jaar uit het Ottomaanse bestuur. Het meer dan 160 jaar durende Ottomaanse Lika kwam ten einde, de ontruimde plaatsen werden met een nieuwe Kroatische bevolking bevolkt en Udbina werd tot de Vrede van Svisjtov (1791) een belangrijk fort van de grensverdediging tegen de Ottomanen.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Inname van Drežnik door Oostenrijk — het westelijke front van de Slag bij Dubica", "05d5e5f1"], "d": ["In de Ottomaans-Oostenrijkse oorlog van 1788-1791 namen de Habsburgse troepen Drežnik ten westen van Bihać in. Met artikel 4 van het Verdrag van Svisjtov bleven Drežnik en Cetin onder Habsburgs bestuur en keerden nooit meer terug naar Bosnië.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Inname van het fort Cetin door Oostenrijk", "df182480"], "d": ["In 1790 viel het Habsburgse leger Cetin, Bužim en Velika Kladuša aan en nam Cetin in. De door de gouverneur van Bosnië uitgeroepen mobilisatie en tegenaanval konden het fort niet terugnemen; artikel 4 van het Verdrag van Svisjtov liet Cetin aan de Habsburgers. De Bosnische grenskrijgers namen het fort in 1809 en 1813 met korte overvallen opnieuw in.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik voor het eerst vermeld — de grens met Byzantium begon bij Bilecik", "7b69f743"], "d": ["In de gebeurtenissen van het jaar 683 die door Neşrî worden overgeleverd, wordt Bilecik genoemd als de plaats waar de grens tussen het uc-beylik van Osman Bey en Byzantium begon. Dit is de eerste bekende vermelding van de nederzetting in de geschiedenis; het is niet haar stichting.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Munt op naam van Ghazan Khan in Burdur — eerste bekende getuigenis van de stad", "01974ddc"], "d": ["De Hamididen werden in het jaar 699 onder Ilkhanidische druk gedwongen in Burdur munten op naam van Ghazan Khan te laten slaan. Deze munt is de eerste geschreven/gedateerde getuigenis van Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum vermeld in het rijk van Eretna — eerste bekende getuigenis van de stad", "bf7bd67f"], "d": ["Bij de dood van Eretna Bey in moeharram 753 wordt Çorum ook genoemd onder de steden die onder zijn heerschappij stonden. De stichting van de stad is onbekend; deze vermelding is de vroegste gedateerde getuigenis die gevonden kon worden.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Brăila voor het eerst vermeld — privilegeoorkonde van Vlaicu Vodă voor kooplieden uit Brașov", "0b3517a7"], "d": ["De Walachijse woiwode Vladislav verleende de kooplieden uit Brașov een oorkonde die hun gemak bood bij het vervoer van goederen over de weg via Brăila. Deze oorkonde is de eerste bekende geschreven getuigenis van Brăila; de plaats wordt hier nog niet als stad genoemd, maar als het uiteinde van de weg aan de Donau. Het is niet de stichtingsdatum.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Chisinau voor het eerst vermeld in een oekaze van de Moldavische woiwode", "a50799d7"], "d": ["De naam Chisinau komt voor het eerst voor in een oekaze van 1420 van de Moldavische woiwode Alexandru. De stad bleef lange tijd een kleine Moldavische stad; toen zij in 1812 samen met Bessarabië aan Rusland overging, werd zij provinciecentrum.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galați voor het eerst vermeld in een document van een Moldavische woiwode", "a31af8a2"], "d": ["De Moldavische woiwode Ștefan II stelde twee wagens van het Humor-klooster, die vis uit Galați brachten, vrij van douanerechten. Dit document is de met zekerheid bekende eerste geschreven getuigenis van Galați; de nederzetting kan eerder als vissersdorp aan de oever van de Donau hebben bestaan.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["De naam Mostar komt voor het eerst voor in een document uit Dubrovnik", "a599bc55"], "d": ["De naam Mostar komt voor het eerst voor in een document uit Dubrovnik van 3 april 1452; de nederzetting lag op het grondgebied van het Hertogdom Herzegovina. De Osmaanse verovering vond plaats in 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["De Hünkâr-moskee in Sarajevo — vroegste gedateerde getuigenis van de nederzetting", "ad697a7d"], "d": ["Isḥak Bey, de sanjakbey van Bosnië, liet in de eerste moslimnederzetting in het Saray-veld een paleis voor zichzelf bouwen, de Hünkâr-moskee op naam van Mehmed de Veroveraar en daarnaast een bad. De moskee is gedateerd op 862 (1458); het is het vroegste gedateerde bouwwerk van Sarajevo dat bekend is.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["De waqf-oorkonde van Isḥak Bey — de stadskern van Sarajevo werd als waqf geschonken", "0b364229"], "d": ["Uit de waqf-oorkonde van Isḥak Bey van djoemada al-awwal 866 (februari 1462) blijkt dat naast de moskee en het bad ook een zawiya, een mevlevi-klooster, een imaret, een brug over de Miljacka, het Kolobara-han op de overkant, een bedesten, een karavanserai en winkels werden gebouwd. Het document is de waqf-basis van de stad; de nederzetting bestond al voor die tijd.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı staat voor het eerst geregistreerd in een akıncı-register", "3b1c839e"], "d": ["De oudste gegevens over de stad gaan terug tot het jaar 877 (1472): een akıncı-register in de Nationale Bibliotheek van Sofia vermeldt de nederzetting.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka voor het eerst vermeld in een instructie van koning Vladislav II", "0ebc6288"], "d": ["De naam Banja Luka komt voor het eerst voor in een instructie van 6 februari 1494 van de Hongaars-Kroatische koning Vladislav II; de streek behoorde via het banaat Jajce tot de Hongaarse kroon. De Osmaanse verovering vond plaats in de winter van 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["De bevolking van Basra voltooit de verhuizing naar de huidige plek — het oude Basra wordt verlaten", "20f96eac"], "d": ["De bevolking was na verloop van tijd gaan wonen in het huidige Basra, dat zij veiliger vond tegen bedoeïenenaanvallen en waar zij gemakkelijker aan water kon komen; de overgang naar de nieuwe plek was voltooid in het jaar 900 (1494-95). Het oude Basra, gesticht in de tijd van Omar, lag ongeveer 25 km van de huidige stad.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Khan liet aan de Çürüksu het Khanpaleis bouwen — de basis van Bachtsjisaraj", "0792497c"], "d": ["In het dal, dat het zomerse jacht- en rustgebied was van de gouverneurs van de Gouden Horde en de eerste Krim-khans, liet Mengli Giray Khan I aan de Çürüksu het paleis bouwen dat nu bekendstaat als het Khanpaleis, en legde zo de basis van Bachtsjisaraj. De stad ontwikkelde zich rond het paleis en langs het smalle dal van de Çürüksu, werd tegen het einde van de 16e eeuw bloeiend en werd het centrum van het Krim-khanaat.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["De Zaporozjer Kozakken stichtten de eerste Sich op het eiland Chortytsja", "e6ca0dd9"], "d": ["Prins Dmytro Vyšnevetskyj stichtte de eerste Zaporozjer Sich op het eiland Klein Chortytsja in de Dnjepr. Het fort werd in 1558 door de Krim-Tataren belegerd en verwoest; de Sich werd later naar eilanden in het zuiden verplaatst. Term: de «Sich» (Oekraïens Sič) is het met boomstammen en grachten versterkte hoofdkamp van de Zaporozjer Kozakken op de Dnjepr-eilanden; het is het hoofdkwartier, de plaats van de raad (Rada) en het centrum van de gekozen legerleider (koševyj), en geen hoofdstad van een staat.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["De Bazavloek-Sich werd gesticht", "fcd507ae"], "d": ["Nadat de Tataren de Tomakivka-Sich hadden verwoest, stichtten de Zaporozjer Kozakken een nieuwe Sich op het eiland Bazavloek, op de plek waar de Dnjepr samenvloeit met de armen Tsjortomlyk, Pidpilna en Skarban. De Sich werd in 1638 verwoest door een Poolse veldtocht na de onderdrukking van de Kozakkenopstand. Term: de «Sich» (Oekraïens Sič) is het met boomstammen en grachten versterkte hoofdkamp van de Zaporozjer Kozakken op de Dnjepr-eilanden; het is het hoofdkwartier, de plaats van de raad (Rada) en het centrum van de gekozen legerleider (koševyj), en geen hoofdstad van een staat. Op dit tijdstip bestaat het «Hetmanaat» nog niet (1648); de naam Zaporozje betekent «voorbij de stroomversnellingen», en de Sich-en liggen aan de steppegrens stroomafwaarts van de stroomversnellingen van de Dnjepr. Er is geen etnische verwantschap met de Kozakken van Kazachstan: de Zaporozjer Kozakken zijn een Oost-Slavische (Oekraïense), orthodoxe gemeenschap; alleen het van Turkse oorsprong zijnde woord «kazak» (vrije krijger) is gemeenschappelijk.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["De Mykytyn Rih-Sich voor het eerst vermeld", "61e22abc"], "d": ["De naam van de vierde Sich, gesticht in Mykytyn Rih op de plek van het huidige Nikopol, komt voor het eerst voor in 1628; in 1648 werd zij door Bohdan Chmelnytskyj ingenomen. Dit is de eerste bekende getuigenis van de plaats, niet haar stichting.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["De Tsjortomlyk-Sich werd gesticht", "4b6e8197"], "d": ["De Zaporozjer Kozakken stichtten de Tsjortomlyk-Sich, ook wel 'Oude Sich' genoemd, op de landtong waar de Dnjepr samenvloeit met de rivier Tsjortomlyk. De Sich werd op 25 mei 1709 door het Russische leger verwoest omdat zij Mazepa hadden gesteund.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Charkov werd gesticht door Kozakkenmigranten", "288b303c"], "d": ["Aan de noordrand van de Wilde Steppe, op de plek waar de rivieren Lopan en Charkov samenvloeien, stichtten Kozakkenmigranten van de rechteroever van de Dnjepr een nederzetting. Charkov werd al snel het centrum van het aan Moskou gebonden Sloboda-Oekraïne.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["De Zaporozjer Kozakken stichtten met toestemming van de Krim-khan de Oleški-Sich", "ed26f29d"], "d": ["Nadat een Russische aanval de Sich in Kamenka had doen ontruimen, vestigden de Zaporozjer Kozakken zich met toestemming van de Krim-khan op khanaatsgebied in Oleški, aan de linkeroever van de rivier Konka. Na het Verdrag van de Proet voegden ook de Kozakken van Gordijenko zich bij hen. De khan stond niet toe dat de Sich muren en kanonnen had.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["De Oleški-Sich werd geplunderd en verlaten", "52361709"], "d": ["De pro-Russische Samara-Kozakken overvielen de Oleški-Sich, plunderden haar en staken de barakken in brand. De Sich werd niet herbouwd; de Kozakken keerden in 1730 terug naar Kamenka en stichtten in 1734, na een eed van trouw aan Rusland, de Nieuwe Sich.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Aan de Wolga werd het fort Stavropol gesticht", "eb087a50"], "d": ["Aan de Midden-Wolga werd het fort Stavropol gesticht voor de Kalmukken die het christendom hadden aanvaard (het huidige Toljatti).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir Sjah neemt Kandahar in en laat de oude stad verwoesten", "9cc23e6b"], "d": ["De Afsharidische heerser Nadir Sjah nam Kandahar, dat in handen was van de Ghilzai-Afghanen, in na een lange belegering. De stad werd verwoest en haar bevolking verhuisde naar Nadirabad, gesticht ten zuidoosten van de oude plek; het oude Kandahar is nooit meer een stad geworden.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["In de Azov-Mozdok-linie werd het fort Stavropol gesticht", "7fd9b9f1"], "d": ["Na Küçük Kaynarca werden in de Azov-Mozdok-versterkingslinie, die werd aangelegd om de steppe tussen de Koeban en de Terek te controleren, tien forten gebouwd; Stavropol was er een van. Het fort werd later het centrum van het gouvernement Kaukasië en van het gouvernement Stavropol.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Aan de monding van de Dnjepr werd de werf van Cherson gesticht", "115f2c34"], "d": ["Aan de monding van de Dnjepr, die na Küçük Kaynarca aan Rusland overging, werd in de buurt van de versterking Aleksandr-sjants, die in 1737 was gebouwd en snel verwoest, een werf gesticht en Cherson genoemd. De stad werd in 1784 kazacentrum en in 1803 gouvernementscentrum.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Grieken uit de Krim stichtten Marioepol aan de kust van de Azovzee", "4e3af209"], "d": ["Grieken uit de Krim stichtten Marioepol op de plek waar de Kalmius in de Azovzee uitmondt. De stad werd in 1784 kazacentrum onder het gouvernement Jekaterinoslav.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Jekaterinoslav werd verplaatst naar de huidige plek aan de Dnjepr", "ec361381"], "d": ["Jekaterinoslav, dat Potjomkin in 1778 had gesticht op de plek waar de rivieren Kilčen en Samara samenvloeien, werd in 1783 wegens zijn ongezonde ligging naar de huidige plek verplaatst.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["In de baai van Achtiar werd de Russische marinehaven Sebastopol gesticht", "01058a25"], "d": ["Na de annexatie van de Krim door Rusland in 1783 werd de baai waar het Krim-Tataarse dorp Achtiar (Akyar) lag gekozen voor een militaire haven; de haven werd het jaar daarop gesticht en kreeg de naam Sebastopol. De stad werd in 1804 de hoofdhaven van de Russische Zwarte Zeevloot.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Aan de monding van de Zuidelijke Boeg werd de versterking Nikolajev gesticht", "d57e52b9"], "d": ["Op de plek waar de Zuidelijke Boeg en de Ingoel samenvloeien, werd op bevel van vorst Potjomkin een versterking gesticht. In 1788 werd hier een werf geopend en de nederzetting werd een van de scheepsbouwcentra van de Zwarte Zeevloot.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Aan de Molotsjna werd de grensnederzetting gesticht die de kern van Melitopol werd", "637d5817"], "d": ["Na de annexatie van de Krim werd aan de oever van de rivier Molotsjna een grensnederzetting gesticht. De nederzetting kreeg in 1816 de naam Novooleksandrivka en werd in 1841 onder de naam Melitopol tot stad gemaakt.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Novotsjerkassk, het nieuwe centrum van het Donkozakkenleger, werd gesticht", "bf5709fd"], "d": ["Het bestuurlijk centrum van het Donkozakkenleger verhuisde van Tsjerkassk, dat tot dan toe het centrum was, naar Novotsjerkassk, gesticht op de plek Birjoetsji Koet tussen de rivieren Aksaj en Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa genoteerd in Burckhardts reis door Nubië", "6efc72ec"], "d": ["De Zwitserse reiziger J. L. Burckhardt schrijft in zijn dagboek van 6 maart 1813 dat hij door Wadi Halfa trok en dat daar enige handel werd gedreven. Het is de eerste gedateerde getuigenis die gevonden kon worden.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Aan de kust van de Azovzee werd de aanlegplaats Berdjansk gesticht", "908ac3cf"], "d": ["Op initiatief van vorst Michail Voronzov werd Berdjansk gesticht op de plek waar de rivier Berda in de Azovzee uitmondt. De nederzetting werd in 1835 stad en in 1842 kazacentrum.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["De bevolking van Malatya blijft in de wijngaarden van Aspuzu — de kern van het moderne Malatya", "d1dba159"], "d": ["Het Osmaanse algemeen hoofdkwartier tegen het Egyptische leger van Ibrahim Pasja werd in de zomer van 1838 van Mezraa naar Malatya verplaatst. De inwoners van Malatya, die in hun zomerhuizen in Aspuzu woonden, keerden na het vertrek van het leger niet terug naar hun winterhuizen in de verwoeste oude stad; Aspuzu werd de kern van het moderne Malatya. Het oude Malatya (Battalgazi) bleef kleiner voortbestaan.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van wordt op een nieuwe plek gesticht — de verwoeste oude stad wordt verlaten", "6d278578"], "d": ["Van werd op 2 april 1918 van de bezetting bevrijd. De teruggekeerden herstelden het tijdens de oorlogsjaren verwoeste oude Van aan de oever van het meer niet, maar stichtten ongeveer 7 km landinwaarts van de oever een nieuwe stad op de plaats van de oude wijken Norşen en Arak. De oude stad werd verlaten.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Marash ging naar de Mamelukken — Bilban al-Tabakhi, naib van Aleppo, nam het terug van de Armeniërs", "03171265"], "d": ["Marash, dat sinds 1258 in handen van het Koninkrijk Armenië van Cilicië was, was in 1293 met het verdrag dat sultan Khalil met de Armeniërs sloot kort aan de Mamelukken gegaan en na hun terugtrekking opnieuw in handen van de Armeniërs gevallen. In 697 (1298) nam Bilban al-Tabakhi, de naib van de Mamelukken in Aleppo, de stad terug. Marash bleef daarna als Mamelukks gebied tot de opkomst van de Dulkadırlı's.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Het Byzantijnse Rijk werd tribuutplichtig aan de Ottomanen", "615df998"], "d": ["Na de overwinning bij Çirmen (1371) stemde de Byzantijnse keizer Johannes V in de winter van 1372 ermee in tribuutplichtig te worden aan Murad I: hij zou jaarlijks tribuut betalen en troepen leveren voor de veldtochten van de sultan. Byzantium bleef vanaf deze datum tot 1403 een aan de Ottomanen gebonden vazalstaat; de blokkade van Yıldırım Bayezid van 1391 verhoogde het tribuut. Na de nederlaag bij Ankara bevrijdde het verdrag van Gallipoli (1403) met Süleyman Çelebi Byzantium van het tribuut; met het verdrag met Murad II in 1424 begon het tribuut opnieuw.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Yıldırım Bayezid voegde na de dood van Barquq Besni, Darende en Divriği bij Ottomaans gebied", "8e57d7e6"], "d": ["Nadat na de dood van de Mamelukse sultan Barquq (juni 1399) de bestuurlijke zaken van de Mamelukkenstaat in de war waren geraakt, trok Yıldırım Bayezid naar het Eufraatbekken en voegde, samen met Malatya, Besni (Behisni), Darende en Divriği bij Ottomaans gebied. Sivas was hiervoor, na de dood van Kadı Burhaneddin in de zomer van 1398, aan de Ottomanen gelaten. Divriği was sinds 1391 onder Mamelukse heerschappij en was een voorpost die bij het eyalet Aleppo hoorde. Het Ottomaanse bestuur duurde hier niet lang: vanwege het naderende gevaar van Timoer werd Divriği in 1401 opnieuw aan de Mamelukken gegeven, en de definitieve overgang van de stad onder Ottomaans bestuur vond plaats na Marj Dabiq in 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni ging tijdens de veldtocht van Timoer naar Sivas en Malatya naar de Mamelukken", "4853da9a"], "d": ["Besni, dat Yıldırım Bayezid in 1398 samen met Sivas, Darende en Malatya had genomen, kwam in 1400, toen Timoer Sivas en Malatya innam, in handen van de Mamelukken. Timoer nam op 27 september 1400 na een hevig beleg ook Besni in; toen hij zich uit de regio terugtrok, kwam Besni opnieuw onder Mamelukse heerschappij en bleef (afgezien van een Dulkadir-tussenperiode) Mamelukks tot Selim de Norse het in augustus 1516 innam.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği werd vanwege het gevaar van Timoer opnieuw aan de Mamelukken gegeven", "97196b1f"], "d": ["Divriği, dat Yıldırım Bayezid in 1398 van de Mamelukken had genomen, werd in 1401, toen Timoer Anatolië naderde, opnieuw aan de Mamelukken overgelaten. Daarom verschijnt Divriği na de verwoesting van Sivas door Timoer (1400) op de kaart in Mamelukse kleur; in dezelfde maanden nam Bayezid in het oosten Erzincan en Kemah in, dat wil zeggen dat het Mamelukse gebied lag tussen de Ottomaanse gebieden in het westen (Sivas) en het noordoosten (Kemah). Divriği ging pas na Marj Dabiq in 1516 definitief naar de Ottomanen.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["De Mamelukse sultan Sjeik nam Antep en Darende terug van de Dulkadırlı's", "f90c9508"], "d": ["De Mamelukse sultan Sjeik, die zich zorgen maakte over de vriendschap van de Dulkadırlı's met de Ottomanen, trok in 1414 ten strijde; hij nam Antep en Darende terug, die hij eerder uit eigen beweging aan de Dulkadırlı's had gegeven.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadıroğlu Mehmed Bey nam Darende terug en voegde ook Besni bij zijn gebied", "df914dcb"], "d": ["Dulkadıroğlu Mehmed Bey nam in 1418 Darende terug, dat de Mamelukken in 1414 hadden genomen, en voegde ook Besni bij zijn gebied.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["De Mamelukken versloegen de Dulkadırlı's bij Antep; Besni keerde terug onder Mamelukse heerschappij (bij benadering)", "72742430"], "d": ["Het Mamelukse leger versloeg de Dulkadırlı's in 1436 bij Antep, Mehmed Bey trok zich terug naar Akdağ. Het jaar waarin Besni naar de Mamelukken terugkeerde, staat niet in de bron; Besni was in 1418 bij Dulkadir gevoegd en was naar de Mamelukken teruggekeerd voordat Şehsuvar Bey het in 1465 van de Mamelukken nam. De atlas geeft Besni samen met deze nederlaag in het naburige centrum Antep terug aan de Mamelukken (verklaarde benadering).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Şehsuvar Bey nam Besni van de Mamelukken (bij benadering)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), door Mehmed de Veroveraar benoemd tot bey van Dulkadir, nam Besni, Gerger, Birecik en Rumkale, die in handen van de Mamelukken waren, in; de Mamelukken werden in de herfst van 1467 bij Turnadağı en in het voorjaar van 1468 nabij Antep verslagen.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Yeşbek versloeg Şehsuvar Bey; Besni keerde terug onder Mamelukse heerschappij (bij benadering)", "4d856aee"], "d": ["In het voorjaar van 1471 versloeg Emir Yeşbek Şehsuvar Bey bij de beek Savron; de Mamelukken namen Kadirli en Kozan terug. Şehsuvar werd in 1472 in Caïro terechtgesteld en de Mamelukken plaatsten Şahbudak opnieuw aan het hoofd van het beylik. Ook Besni kwam met deze terugkeer onder Mamelukse heerschappij (TDV besni: 'kwam tegen het einde van de 15e eeuw opnieuw in handen van de Mamelukken').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["De troepen van Ferdinand bezetten Szolnok en versterkten het", "6c8416e6"], "d": ["Terwijl de Ottomanen zich voorbereidden op de bouw van een fort bij Szolnok aan de Tisza, kwamen de troepen van Ferdinand I hen voor: halverwege september 1550 bezetten zij Szolnok en halverwege oktober was het fort verdedigbaar gemaakt. Zo kwam Szolnok, dat tot het land van Isabella behoorde, een jaar vóór de overgang van Transsylvanië aan Ferdinand in Habsburgse handen; de Ottomanen namen het fort in 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transsylvanië kwam onder Habsburgs bestuur: de raad van Kolozsvár erkende de afstand van Isabella", "8458a566"], "d": ["Na de overeenkomst van Martinuzzi met Ferdinand ondertekende koningin Isabella namens de jonge koning János Zsigmond op 19 juni 1551 in het fort van Szászsebes de afstandsverklaring die haar werd opgelegd. De op 26 juli in Kolozsvár bijeengekomen Transsylvaanse landdag erkende deze afstand en de heerschappij van koning Ferdinand; het Habsburgse leger van generaal Castaldo trok Gyulafehérvár (Transsylvaans Belgrado) binnen. Zo kwam het aan de Ottomanen gebonden Transsylvanië onder een Habsburgs bestuur dat vijf jaar zou duren.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Het Habsburgse bestuur in Transsylvanië eindigde: Transsylvanië werd opnieuw een aan de Ottomanen gebonden woiwodschap", "721a482a"], "d": ["Doordat János Zsigmond minderjarig was, trachtten de Habsburgers in 1551 via de priester van Kroatische afkomst Martinuzzi (Fráter György), die tot zijn voogd was benoemd, de heerschappij over Transsylvanië te verkrijgen; Gyulafehérvár, Kolozsvár, Brassó en Segesvár bleven vijf jaar onder Habsburgs bestuur. De Ottomanen verhinderden deze toestand en Transsylvanië werd opnieuw een aan hen gebonden tribuutplichtige woiwodschap. Transsylvanië behield daarna in de 16e en 17e eeuw gedurende ongeveer 150 jaar zijn status, gebaseerd op uitgebreide autonomie in interne zaken en gebondenheid aan Constantinopel in buitenlandse zaken.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt en Tokaj gingen naar de zijde van Szapolyai", "587c782d"], "d": ["Na de terugkeer van Isabella en János Zsigmond naar Transsylvanië in 1556 belegerden aanhangers van Szapolyai in 1556 Nagyvárad. In 1557 namen de aristocraten van de Boven-Tisza de belangrijkste koninklijke forten — Várad, Huszt en Tokaj — in; in handen van Ferdinand bleven alleen Gyula en Világos over. Várad werd daarna het bolwerk van het Vorstendom Transsylvanië en bleef dat tot de Ottomanen het in 1660 innamen.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi nam Szatmár — de noordpunt van Transsylvanië ging naar de Habsburgers", "2256bb27"], "d": ["Szatmár, dat in 1561 door het overlopen van Menyhért Balassa naar de Habsburgers was gegaan, had István Báthory in de herfst van 1564 met een overval heroverd en bij Transsylvanië gevoegd. De Habsburgse commandant Lazarus von Schwendi ging in februari 1565 tot de tegenaanval over: Tokaj viel op 9 februari, Szerencs vier dagen later en Szatmár kwam vrijwel zonder verzet in handen van de keizerlijke troepen.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["De troepen van Bocskai namen Szatmár in", "e93b098b"], "d": ["Terwijl de Bocskai-opstand zich naar Noordoost-Hongarije verspreidde, nam Gyulaffy het door hem belegerde Szatmár op 21 januari 1605 in. De Vrede van Wenen van 23 juni 1606 liet het comitaat Szatmár levenslang aan Bocskai; omdat er geen mannelijke erfgenaam was, keerde het comitaat met de dood van Bocskai op 29 december 1606 terug naar het koninkrijk.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Dood van István Bocskai — het comitaat Szatmár keerde terug naar het koninkrijk", "3721bb9b"], "d": ["De vorst van Transsylvanië István Bocskai stierf op 29 december 1606 in Kassa. De Vrede van Wenen (23 juni 1606) had hem de comitaten, waaronder Szatmár, levenslang gelaten, met terugkeer naar het koninkrijk in geval van het ontbreken van een mannelijke erfgenaam; met deze bepaling ging het comitaat Szatmár terug naar het Habsburgs-Hongaarse koninkrijk. Transsylvanië ging op zoek naar een nieuwe vorst.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor nam het comitaat Szatmár onder zijn controle", "80263da1"], "d": ["Met de Hongaarse veldtocht van Bethlen Gábor in de herfst van 1619 kwam het comitaat Szatmár onder controle van de vorst van Transsylvanië; in november 1619 sprak hij het comitaat per brief aan. Het voorlopige verdrag van 23 januari 1620 en de Vrede van Nikolsburg lieten zeven comitaten, inclusief Szatmár, levenslang aan Bethlen. Na Bethlens dood (15 november 1629) werd de teruggave van de comitaten aan het koninkrijk op 30 maart 1630 voltooid.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Voltooiing van de teruggave van de zeven comitaten van Bethlen Gábor aan het koninkrijk", "31b5968f"], "d": ["De Vrede van Nikolsburg had zeven comitaten van Opper-Hongarije, inclusief Szatmár, levenslang aan Bethlen Gábor gelaten. Na Bethlens dood op 15 november 1629 begon de teruggave van de comitaten aan het koninkrijk met de instructie van 30 november 1629 en werd op 30 maart 1630 voltooid.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I Rákóczi nam Szatmár over", "f398635b"], "d": ["Tijdens de veldtocht van 1644 van György I Rákóczi, vorst van Transsylvanië, ging het Duitse garnizoen van Szatmár in dienst van Rákóczi over en kwam het fort in handen van Transsylvanië. De Vrede van Linz van 16 december 1645 liet het fort aan de erfgenamen van Rákóczi zolang een Rákóczi op de troon van Transsylvanië zat.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Verlies van Nitra — De Souches nam het fort terug", "c71bf012"], "d": ["Nitra, dat na de verovering van Uyvar in 1663 na korte weerstand was overgegeven, werd op 15 april 1664 door de keizerlijke commandant De Souches belegerd; het fort gaf zich op 3 mei 1664 over. Omdat de Vrede van Vasvár de ingenomen plaatsen liet zoals zij waren, bleef Uyvar Ottomaans terwijl Nitra in Habsburgse handen bleef.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Verlies van Léva", "f311920e"], "d": ["De Souches belegerde na Nitra op 9 juni 1664 Léva; op 13 juni werd de capitulatie ondertekend en op 14 juni was het fort in handen van de keizerlijke troepen. De Slag bij Léva (Garamszentbenedek) van 19 juli 1664 veranderde het eigendom niet; zij eindigde ermee dat de Habsburgers Léva en Nitra behielden.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Dorosjenko droeg Tsjyhyryn over aan Samojlovitsj", "3b538237"], "d": ["Petro Dorosjenko, hetman van Rechteroever-Oekraïne onder Ottomaanse bescherming, droeg zijn hoofdstad Tsjyhyryn op 19 september 1676 over aan Samojlovitsj, hetman van Linkeroever-Oekraïne, en aan Russische troepen. De Ottomanen zetten Dorosjenko af en plaatsten Joeri Chmelnytsky in zijn plaats; een belegering in 1677 om het Russische garnizoen uit Tsjyhyryn te verdrijven mislukte, het fort werd pas op 21 augustus 1678 ingenomen.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Overgave van de forten van het Banaat van Transsylvanië (Temesvár, Lippa, Lugos, Karánsebes) aan Ferdinand, koning van Hongarije", "0e354976"], "d": ["In 1551 trok het Habsburgse leger onder bevel van generaal Castaldo Transsylvanië binnen; koningin Isabella en haar zoon moesten afstand doen van hun rechten op de Hongaarse troon. Martinuzzi stuurde met toestemming van Castaldo halverwege juli 1551 Endre Báthory om de forten Temesvár, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek en Csanád namens Ferdinand over te nemen. De zuidelijke forten van het onder Ottomaanse bescherming staande Transsylvanië kwamen zo in Habsburgse handen; de veldtochten van Süleyman van 1551-1552 zijn het antwoord hierop.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Benoeming van Petrovics Péter tot sandjakbey van Lugos en Karánsebes", "bcbe73e4"], "d": ["Op aandringend verzoek van Isabella en Petrovics besloot Süleyman de jonge János Zsigmond naar Transsylvanië terug te brengen. Met een brief uit Aleppo van 7 april 1554 beval hij Transsylvanië het kind naar zijn land terug te brengen; ook beval hij de woiwodes van Walachije en Moldavië hierbij Petrovics te helpen, die hij in dezelfde periode tot sandjakbey van Lugos en Karánsebes benoemde. Het in 1552 veroverde Lugos werd zo als Ottomaanse sandjak aan Petrovics gegeven.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Opheffing van het beleg van Lippa — de aanval van de ban van Lugos op Temesvár", "be03430e"], "d": ["In het voorjaar van 1596 belegerde de pasja van Temesvár Lippa. In de nacht van 10 op 11 mei vielen op bevel van György Palatics, ban van Lugos van Transsylvanië, de soldaten van György Buday de voorsteden van Temesvár aan en staken ze in brand; ook het feit dat György Borbély in het fort al zijn kanonnen liet afvuren, deed de pasja geloven dat er hulp was gekomen. De pasja trok zich op 11 mei terug van Lippa om zijn eigen centrum te beschermen. Lugos was op dat moment in handen van het Vorstendom Transsylvanië.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Bezetting van Orsova door de Oostenrijkse troepen onder bevel van Veterani", "1b4a4f6c"], "d": ["In de veldtocht van 1688 trok generaal Veterani, nadat hij Karánsebes had ingenomen, tegen Orsova op en bezette dit ook. De bron geeft geen dag van bezetting; de jaarbasis 1 januari 1688 is gebruikt.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Herovering van Orsova door Thököly en de Ottomaanse troepen", "c5645da9"], "d": ["Naar Orsova, dat Veterani in 1688 had bezet, trokken na de inname van Vetislan Thököly en de Ottomaanse pasja's op. Na onbeduidende gevechten trok Thököly op 15 juli 1689 Orsova binnen. Heissler, die op het bericht van gevaar kwam, zag dat de macht tegenover hem goed was uitgerust met munitie en schepen en trok zich terug om Transsylvanië te beschermen. Ook de aanval van Herbeville in augustus voor de stad kon Orsova niet terugnemen.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Het sandjak Lugos kwam onder Habsburgse bezetting (1691-1695)", "c8bcd6bd"], "d": ["Het sandjak Lugos bleef tussen 1691 en 1695 onder Habsburgse (Duitse) bezetting; Mustafa II veroverde het op 22 september 1695 opnieuw. In het oude register was de periode 1689-1695 een verklaarde leemte; het deel 1691-1695 wordt nu als Habsburgs ingekleurd, 1689-1691 blijft een leemte. De datum is alleen als jaar overgenomen.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Het fort Lugos kwam onder Habsburgs bestuur", "6a9d401f"], "d": ["Het sandjakfort Lugoj, dat aan het eyalet Temesvár was gebonden, was sinds 1695 in Ottomaanse handen; met de overgave van het eyaletcentrum na het beleg van 1716 werd het aan de Habsburgse Monarchie overgelaten. Het oude register plaatste de overdracht op de jaarbasis 1 januari 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Inname van Orsova door het Habsburgse leger (veldtocht van 1717)", "7a4faffe"], "d": ["In de veldtocht van 1717 kwam generaal Splényi op 27 augustus voor Orsova en nam de stad gemakkelijk in; zo kwam Orsova, dat Mercy in 1716 niet had kunnen innemen, in Habsburgse handen. Omdat de honingraten aan de Donauoever eromheen (inclusief het Đerdap-deel aan de Servische oever) aan het dichtstbijzijnde nederzettingspunt Orsova zijn gebonden, worden zij met de eigenaar ervan ingekleurd. De datum is alleen als jaar overgenomen; de exacte dag is niet bevestigd.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Overgang van de palanka Orsova naar de Ottomanen — terugtrekking van de bewaker naar Ada Kaleh", "de759b16"], "d": ["Bij het begin van de veldtocht van 1738 viel Hacı Mehmed Pasja, bewaker van Vidin, de Erzsébet-schans aan de Donau aan. Op 8 mei 's middags trok een sipahi-afdeling van 4-5 duizend man vanaf de linkeroever van de Donau naar Orsova en viel de palanka Orsova aan; de Oostenrijkse bewaker, die ongeveer honderd man verloor, trok zich terug naar Nieuw-Orsova, dat wil zeggen het eilandfort Ada Kaleh. Na de gevechten bij Mehadia in juli kwam ook Ada Kaleh in augustus 1738 in Ottomaanse handen; het Verdrag van Belgrado van 1739 erkende de toestand.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II nam Aladža Hisar in, Niš en Şehirköy keerden terug naar de Ottomanen", "54af926a"], "d": ["Na de kinderloze dood van de Servische despoot Stefan Lazarević (1427) trad Murad II op door te beweren dat hij op grond van het huwelijk van Yıldırım Bayezid met een Servische prinses de rechtmatige erfgenaam van Servië was, en nam Aladža Hisar in (1428). In hetzelfde jaar namen de Ottomanen na de dood van Lazarević ook het fort Şehirköy terug — de stad was in 1412 door Stefan genomen en tegen Musa Çelebi verdedigd. Volgens het lemma nis van de TDV namen de Ottomanen in hetzelfde jaar (831/1428) ook Niš terug. Zo kwam de lijn die de dalen van de Grote Morava en de Nišava met elkaar verbond onder Ottomaanse controle.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Het kruisvaardersleger nam Şehirköy in — de Nišava-tak van de 'Lange Veldtocht'", "fdf6140c"], "d": ["Het kruisvaardersleger onder leiding van koning Vladislaus en de Servische despoot Đurađ Branković nam in 1443 Şehirköy in. In het vervolg van dezelfde veldtocht zouden de Ottomaanse troepen in november bij de Izladi-pas worden verslagen. Şehirköy was na het Verdrag van Szeged (1444) door Murad II opnieuw aan de Serviërs gegeven, maar ging in 1456 na de dood van Đurađ Branković naar de Ottomanen.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Definitieve Ottomaanse heerschappij in de regio Aladža Hisar gevestigd", "9715382a"], "d": ["Aladža Hisar, dat in 1444 met het verdrag met de Hongaarse afgevaardigden aan Branković werd gelaten, kwam in de jaren na de overwinning bij Varna opnieuw onder Turkse heerschappij. Deze tweede verovering van de stad wordt niet gedocumenteerd met een oorlogsregister maar met een financieel register: de timar-registers van enkele dorpen die bij Aladža Hisar horen, dateren uit eind 1453/begin 1454; dit is echter slechts dorpsgetuigenis — in 1454 werden de Ottomaanse troepen in de omgeving van Aladža Hisar verslagen, in 1455 werd Aladža Hisar als grens aan Branković gelaten. Volgens de TDV werd de definitieve Ottomaanse heerschappij in de regio in 1458 gevestigd.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Stichting van het Despotaat van de Morea — Manuel Kantakouzenos in Mistra", "87660b82"], "d": ["De Byzantijnse keizer Johannes Kantakouzenos gaf zijn zoon Manuel in de Morea een afzonderlijk bestuursgebied; zo ontstond het Despotaat van de Morea met Mistra als centrum. Manuel regeerde tot 1380; in deze periode bloeiden de Byzantijnse cultuur en kunst vooral in Mistra. Het despotaat duurde tot de verovering door Mehmed de Veroveraar in 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despoot Konstantinos nam Patras van de Franken", "cb0dd18c"], "d": ["Konstantinos, despoot van de Morea (in 1449 de laatste Byzantijnse keizer), nam Patras terug van de Latijnen; zo werd ook deze belangrijke haven in het noordwesten van het schiereiland bij het despotaat gevoegd. Patras kwam in 1458 tijdens de Morea-veldtocht van Mehmed de Veroveraar onder Ottomaanse heerschappij.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić Kosača 'Hertog van St. Sava' — de geboorte van Herzegovina", "cc67061f"], "d": ["Stjepan Vukčić Kosača, die Hum en Trebinje in één vorstendom verenigde, kwam in opstand tegen de koning van Bosnië en riep zichzelf uit tot 'Herzog (hertog) van St. Sava'; de titel werd in 1448 door keizer Frederik III verleend. De naam Herzegovina ('het land van de hertog') komt van deze titel. Herzegovina ging vanaf 1466 stukje bij beetje over naar de Ottomanen, werd in 1470 sandjak; de overgebleven gebieden werden begin 1482 toegevoegd.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Vrede van Krakau — de staat van de Duitse Orde werd omgevormd tot het Hertogdom Pruisen", "78666ddd"], "d": ["Albrecht van Brandenburg, grootmeester van de Duitse Orde, tekende, omdat hij geen hulp vond tegen Polen, de Vrede van Krakau. De Ordestaat (Ordensstaat) werd onder Poolse leenheerschap een erfelijk en wereldlijk hertogdom dat overging op het Huis Brandenburg. Het centrum was Königsberg; Albrecht stichtte hier in 1544 de Albertus-Universiteit. Het hertogdom werd in 1701 omgevormd tot het Koninkrijk Pruisen.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Uitroeping van de Republiek Oostenrijk — einde van de Habsburgse monarchie", "c84f316c"], "d": ["Op de dag nadat keizer Karel I zich op 11 november uit de staatszaken had teruggetrokken, nam de Voorlopige Nationale Vergadering de wet over de staats- en regeringsvorm aan en werd de republiek uitgeroepen. De plaats van Habsburgs Oostenrijk werd ingenomen door de Eerste Republiek met Wenen als centrum. Met deze uitroeping werden Wenen, Linz, Salzburg, Innsbruck, Klagenfurt, Bregenz en de andere Duits-Oostenrijkse steden grondgebied van de Republiek Oostenrijk (Deutschösterreich).", "2dcc1399"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batumi onder heerschappij van het Koninkrijk/de Koninkrijken Georgië — gedateerde getuigenis in de bron", "62cd2833"], "d": ["De bron toont de stad Batumi op deze datum onder het bestuur van het Koninkrijk/de Koninkrijken Georgië; het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["De Marwanid Nasr ad-Dawla voegde Âmid bij zijn emiraat", "9fbc8c85"], "d": ["De Marwanidische emir Nasr ad-Dawla Ahmad voegde Âmid (Diyarbekir) bij het grondgebied van het emiraat; het jaar daarop nam hij ook Urfa in.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Maragha kwam onder Seltsjoekse heerschappij", "c011cac9"], "d": ["Maragha, dat in handen was van de Rawwadiden, kwam met de veldtocht van Tughril Bey naar Azerbeidzjan onder Seltsjoekse heerschappij.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tughril Bey trok Bagdad binnen", "38af55c2"], "d": ["Tughril Bey, die op uitnodiging van kalief al-Qa'im bi-Amr Allah naar Bagdad kwam, maakte een einde aan de Buyidische heerschappij.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mosul kwam in handen van de Seltsjoeken", "20b8da93"], "d": ["Mosul ging samen met Irak over naar de Seltsjoeken; ondanks de korte bezetting door al-Basasiri bleef het vier jaar in Seltsjoekse handen.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mosul opnieuw bij de Uqayliden", "8b7c0603"], "d": ["Mosul kwam in 1061 opnieuw onder Uqaylidische heerschappij; ook na de Seltsjoekse verovering van 1084 gaf Malik-Shah de stad terug aan de Uqaylidische emir.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alp Arslan maakte een einde aan het sjahdom van Nachitsjevan", "5620360e"], "d": ["Alp Arslan, die de Rawwadiden versloeg, schafte het door de Dulafiden gestichte sjahdom van Nachitsjevan af.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["Emir Saltuk veroverde Erzurum", "f52c09dd"], "d": ["Na Manzikert gaf Alp Arslan de omgeving van Erzurum als iqta' aan Emir Saltuk; Saltuk nam in hetzelfde jaar de stad in en het beylik van de Saltukiden werd gesticht (volgens Yinanç 1080).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Danishmend Ghazi veroverde Sivas", "348d7ad3"], "d": ["Danishmend Ghazi, die Sivas innam dat na Manzikert als iqta' aan hem was gegeven, stichtte hier de kern van de dynastie (de verovering is omstreden; er is ook een overlevering van 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Philaretos nam Malatya in", "9c80e3bd"], "d": ["Philaretos, die in Cilicië een Armeens vorstendom stichtte, nam Malatya in door zich voor te doen als vertegenwoordiger van Byzantium en bestuurde het via gouverneurs (Gabriel e.a.).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["Emir Danishmend veroverde Tokat", "c9321fb6"], "d": ["Na de overwinning bij Manzikert nam Emir Danishmend Tokat op Byzantium in.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["De Seltsjoeken namen Hasankeyf van de Marwaniden", "4fa9d559"], "d": ["In de tijd van Malik-Shah maakten de Seltsjoeken een einde aan de Marwanidische heerschappij en namen ook Hasankeyf in.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["De zoon van Fakhr ad-Dawla nam Âmid in, Marwanidische heerschappij eindigde", "ecaf6b03"], "d": ["Za'im ar-Ru'asa, de zoon van Fakhr ad-Dawla Ibn Jahir, die door Malik-Shah was aangesteld, nam Âmid van de Marwaniden in.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutush nam Diyarbekir in", "469b8ebc"], "d": ["Tutush, die na de dood van Malik-Shah aanspraak maakte op het sultanaat, nam de regio Diyarbekir in en nam de laatste Marwanidische emir Mansur gevangen.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["De Turkmeense bey Sadr begon te regeren in Âmid", "3d67b786"], "d": ["Na de dood van Tutush kwam de Turkmeense bey Sadr aan de macht in Âmid; zijn opvolger Inal stichtte de dynastie van de Inalogullari.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kerbogha nam Mosul in", "462a238f"], "d": ["De Seltsjoekse emir Kerbogha nam Mosul van de Uqayliden in. (Dhu al-Qa'da 489 / november 1096; de atlas schrijft, de registratie volgend, in jaarprecisie.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksar onder heerschappij van de Danishmendiden — gedateerde getuigenis in de bron", "81181870"], "d": ["De bron toont de stad Niksar op deze datum onder het bestuur van de Danishmendiden; het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["De Danishmendid Gümüştegin Ghazi nam Malatya in", "87f1166c"], "d": ["Gümüştegin Ghazi nam Malatya na een belegering in.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kilij Arslan I nam Malatya over", "eca366d5"], "d": ["Na de dood van Gümüştegin voegde Kilij Arslan I Malatya na een belegering van ruim twee maanden bij het Seltsjoekse grondgebied.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["De Mazyadid Sadaqa stierf in Nu'maniya, Hilla ging naar de Seltsjoeken", "e5ecea7c"], "d": ["Muhammad Tapar versloeg Sadaqa; zijn zoon Dubays werd gevangen genomen en kreeg geen toestemming terug te keren naar Hilla.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["Ilarslan heroverde Elbistan op Tancred", "923962c2"], "d": ["Ilarslan, de atabeg van Tughril Arslan, de malik van Malatya, heroverde Elbistan, dat Tancred, de prins van Antiochië, had ingenomen.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["De Artukid Belek kwam aan de macht in Harput", "83425a6e"], "d": ["Belek b. Bahram, kleinzoon van Artuk Bey, kwam aan de macht in Harput en stichtte zijn beylik met Palu als centrum.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Niğde onder heerschappij van de Anatolische (Roem-)Seltsjoekse staat — gedateerde getuigenis in de bron", "dfb24c4b"], "d": ["De bron toont de stad Niğde op deze datum onder het bestuur van de Anatolische (Roem-)Seltsjoekse staat; het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dubays keerde terug naar Hilla", "9bc0e03a"], "d": ["Na de dood van Muhammad Tapar kon Dubays in de tijd van de Irakees-Seltsjoekse sultan Mahmud naar Hilla gaan.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmud werd in Bagdad uitgeroepen tot Irakees-Seltsjoeks sultan — de Irakees-Seltsjoekse staat werd gesticht", "18babf94"], "d": ["Na de dood van Muhammad Tapar werd zijn zoon Mahmud door de kalief tot sultan uitgeroepen; de Irakees-Seltsjoekse staat werd gesticht. Bagdad bleef met Mosul en Tikrit verbonden aan het Irakees-Seltsjoekse sultanaat, ook Azerbeidzjan (Maragha, Nachitsjevan) viel toe aan het Irakees-Seltsjoekse aandeel. Tikrit komt in de bron dit jaar voor als iqta' van de shahna van Bagdad.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["Ioannes II Komnenos heroverde Denizli", "cb523c0f"], "d": ["De Byzantijnse keizer Ioannes II Komnenos dwong de Seltsjoekse bevelhebber Alp Kara in Laodicea zich terug te trekken; het gebied van Denizli ging weer over naar Byzantium (het Byzantijnse item zegt 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aksungur al-Ahmadili werd naar Maragha gezonden", "7a3d6deb"], "d": ["Sultan Mahmud zond Aksungur al-Ahmadili naar Maragha; het atabegaat van de Ahmadiliden vestigde zich in de stad.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-01-01:0":{"b": ["De Danishmendid Emir Ghazi nam Malatya over; ook Elbistan ging naar de Danishmendiden", "97f3f958"], "d": ["Na de dood van Belek nam Emir Ghazi na een lange belegering Malatya in op de Seltsjoekse malik Tughril Arslan; met de verovering van de streek Malatya kwam ook Elbistan onder Danishmendidisch bestuur.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Emir Ghazi nam Ankara van de Seltsjoeken", "25b745cd"], "d": ["De Danishmendid Emir Ghazi versloeg Malik Arab, de zoon van Kilij Arslan I, en nam Ankara van hem.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["Imad ad-Din Zengi atabeg van Mosul (Zengiden)", "ba79276b"], "d": ["De Irakees-Seltsjoekse sultan Mahmud gaf Mosul als iqta' aan Imad ad-Din Zengi; het Atabegaat van Mosul werd gesticht.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kayseri onder heerschappij van de Danishmendiden — gedateerde getuigenis in de bron", "3b9b8604"], "d": ["De bron toont de stad Kayseri op deze datum onder het bestuur van de Danishmendiden; het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemah onder heerschappij van de Mengücekiden (Mengücekoğulları) — gedateerde getuigenis in de bron", "d86927c6"], "d": ["De bron toont de stad Kemah op deze datum onder het bestuur van de Mengücekiden (Mengücekoğulları); het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Sultan Mas'ud nam Elbistan in", "825e2c56"], "d": ["Mas'ud I nam Elbistan en Ceyhan in, die in handen waren van Ayn ad-Dawla, en stelde zijn zoon Kilij Arslan aan als malik.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Nachitsjevan werd bij de Ildenizieden gevoegd", "774400cc"], "d": ["Met het uiteenvallen van de Seltsjoeken werd Nachitsjevan bij de staat van de Ildenizieden gevoegd en was tot 1174 hun centrum (het jaar van aansluiting is zonder jaar; begin van de dynastie).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikrit ging naar de Begteginiden (EI2)", "a2caf5af"], "d": ["Volgens wat TDV uit de EI2 overneemt, stond Tikrit in 1149-1190 onder de heerschappij van de Begteginiden.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-04-30:0":{"b": ["Sultan Mas'ud gaf Hilla aan Salarkurd", "4bdbd034"], "d": ["Na de dood van de Mazyadid Ali gaf Sultan Mas'ud Hilla aan zijn bevelhebber Salarkurd.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-04-08:0":{"b": ["Sultan Mas'ud stierf; kalief al-Muqtafi werd alleenheerser in Irak, nam Hilla, Kufa en Wasit in", "21192405"], "d": ["Met de dood van Sultan Mas'ud vestigde kalief al-Muqtafi li-Amr Allah in Bagdad en Irak een heerschappij die onafhankelijk was van Seltsjoekse invloed; de vizier van de kalief nam Hilla in, ook Kufa en Wasit werden ingenomen.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Yağıbasan nam Elbistan in", "824708d3"], "d": ["Na de dood van Mas'ud nam de Danishmendidische malik van Sivas, Yağıbasan, Elbistan in; het bestuur ervan werd hem bij overeenkomst gelaten.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Seltsjoekse bevelhebbers namen Hilla in, de Mazyadiden werden onderworpen aan de vertegenwoordiger", "43afd955"], "d": ["Hilla werd ingenomen door de bevelhebbers van Sultan Muhammad b. Mahmud; de Mazyadiden regeerden als onderworpenen aan de vertegenwoordiger van de sultan.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Bakoe onder heerschappij van de Shirvanshahs — gedateerde getuigenis in de bron", "1f2863e4"], "d": ["De bron toont de stad Bakoe op deze datum onder het bestuur van de Shirvanshahs; het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Kalief al-Mustanjid nam Hilla in, de Mazyadiden kwamen ten einde", "4348923c"], "d": ["Troepen van kalief al-Mustanjid en de Banu Muntafiq bezetten Hilla, de Mazyadiden werden verstrooid.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kilij Arslan II nam Elbistan en Darende in", "7c109007"], "d": ["Kilij Arslan II, die profiteerde van de twist onder de Danishmendiden, nam Elbistan, Darende en de streek Geduk in.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["De Rubenid Mleh nam Tarsus op Byzantium in", "2f98fd11"], "d": ["De Rubenid Mleh heroverde met de hulp van Nur ad-Din Zengi Adana, Misis en Tarsus op de Byzantijnen.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["De Ildenizid Pehlivan nam Tabriz in", "f0831f17"], "d": ["De Ildenizid Pehlivan nam Tabriz langs vreedzame weg van de Ahmadiliden en gaf het aan zijn broer Kizil Arslan.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kilij Arslan II nam Sivas en Niksar van de Danishmendiden", "584575bb"], "d": ["Na de dood van Nur ad-Din Zengi nam Kilij Arslan II in de zomer van 1175 Sivas, Niksar, Tokat en de overige Danishmendidische gebieden in; de tak van Sivas kwam ten einde.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kilij Arslan II nam Malatya in, de Danishmendidische tak eindigde", "3bdbb060"], "d": ["Na een belegering van vier maanden ging Malatya over naar de Seltsjoeken en de Malatya-tak van de Danishmendiden kwam ten einde.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Saladin nam Âmid in en gaf het aan de Artukid Nur ad-Din Muhammad", "8c3cc7bb"], "d": ["Saladin belegerde en nam Âmid in, gaf Hisn Kayfa aan de Artukidische emir Nur ad-Din Muhammad; de Inalogullari kwamen ten einde.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Roepen III heroverde Adana op de kruisvaarders", "e9876f85"], "d": ["De Rubenid Roepen III heroverde in 1184 Misis, Adana en Tel Hamdun, die na Mleh enige tijd naar de kruisvaarders waren gegaan.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikrit ging naar de Abbasiden", "e8f5aeac"], "d": ["Na de Begteginidische heerschappij ging de stad over naar het bestuur van het Abbasidische kalifaat.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Rukn ad-Din Sulayman Shah II heroverde Samsun", "0971ebcd"], "d": ["Samsun en de gebieden aan de oostelijke Zwarte Zee, die tijdens de broederstrijd aan de Komnenen waren overgegaan, werden door Sulayman Shah heroverd.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana en Tarsus: het Rubenidische vorstendom werd het Armeense Koninkrijk van Cilicië", "de3c4beb"], "d": ["De Rubenidische dynastie, die Adana en Tarsus in handen hield, nam de koningstitel aan; het is een titelwijziging van dezelfde dynastie, er wisselde geen grondgebied van hand. De kroningsdag is in TDV NIET GEVONDEN — de datum is overgenomen van het begin van de registratie van het Armeense Koninkrijk van Cilicië (de dag van de registratie is geen bron).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Het Griekse Keizerrijk van Trebizonde werd gesticht — Giresun en Sinop ook binnen zijn grenzen", "a99b6ba0"], "d": ["Alexios Komnenos, die na de inname van Constantinopel door de Latijnen naar Trebizonde vluchtte, riep zichzelf uit tot keizer; de stad werd het centrum van de nieuwe staat. De staat die door de Komnenen-kleinzonen Alexios en David werd gesticht, strekte zich uit tot Sinop; ook Giresun lag binnen de grenzen van het Griekse Keizerrijk van Trebizonde.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kütahya onder heerschappij van het Keizerrijk Nicea (Laskaris) — gedateerde getuigenis in de bron", "d91fa405"], "d": ["De bron toont de stad Kütahya op deze datum onder het bestuur van het Keizerrijk Nicea (Laskaris); het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["De Ildenizid Abu Bakr nam Maragha in", "03faed10"], "d": ["De Ahmadilid Ala ad-Din Korpe Arslan moest het fort van Maragha overlaten aan de Ildenizidische atabeg Abu Bakr.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["De Seltsjoeken veroverden Denizli en Honaz", "1053ccc8"], "d": ["In het tweede sultanaat van Ghiyath ad-Din Kay Khusraw I gingen Denizli en Honaz over naar de Seltsjoeken (Byzantijnse bronnen zeggen 1196, het item over de Seltsjoeken 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Ghiyath ad-Din Kay Khusraw I voegde Maraş opnieuw bij de Seltsjoeken", "91b1544e"], "d": ["Kay Khusraw organiseerde een veldtocht tegen de Armeniërs en voegde Maraş bij het Seltsjoekse grondgebied.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu onder heerschappij van de Çobanoğulları — gedateerde getuigenis in de bron", "10b682ba"], "d": ["De bron toont de stad Kastamonu op deze datum onder het bestuur van de Çobanoğulları; het eerdere eigendom is in de bron niet gedateerd (de atlas laat de periode vóór deze datum leeg).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Izz ad-Din Kay Ka'us I veroverde Sinop", "463ea2b9"], "d": ["De Seltsjoekse sultan Izz ad-Din Kay Ka'us I nam Sinop van de Komnenen van Trebizonde.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Ala ad-Din Kay Qubad I nam Kalonoros (Alaiya) in", "5a4d6ac2"], "d": ["Het fort Kalonoros ten oosten van Antalya werd door de Seltsjoeken ingenomen, herbouwd en kreeg de naam Alaiya (het item over Alanya zegt 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Jalal ad-Din Khwarazmshah annexeerde Azerbeidzjan", "5b812b99"], "d": ["Jalal ad-Din Khwarazmshah voegde Azerbeidzjan en Arran bij zijn gebied (regionale zin).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Jalal ad-Din Khwarazmshah nam Maragha in", "a55ec004"], "d": ["Jalal ad-Din Khwarazmshah nam Maragha in en maakte het tot het militaire en bestuurlijke centrum in Azerbeidzjan.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Jalal ad-Din Khwarazmshah trok Tabriz binnen", "72904097"], "d": ["Toen atabeg Özbek zich terugtrok naar Ganja, trok Jalal ad-Din Khwarazmshah Tabriz binnen, kwam aan de macht in de stad en maakte haar tot zijn centrum.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Ala ad-Din Kay Qubad nam Kemah in", "8c5aa655"], "d": ["De tak Kemah-Erzincan van de Mengücekiden werd bij het Seltsjoekse grondgebied gevoegd door Ala ad-Din Kay Qubad I, die Kemah belegerde en innam.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Maragha voor de tweede keer door de Mongolen ingenomen", "f1320e5d"], "d": ["Aan het einde van de Khwarazmshah-heerschappij kwam Maragha in handen van de Mongolen.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Azerbeidzjan kwam onder Mongoolse heerschappij — Tabriz onderging de Mongoolse bezetting", "3f38ef66"], "d": ["Met de ineenstorting van Jalal ad-Din Khwarazmshah onderging Tabriz in 1231 de Mongoolse bezetting; de Mongoolse heerschappij omvatte in hetzelfde jaar Noord- en Zuid-Azerbeidzjan (regionale zin, niet specifiek voor de stad). In Shirvan (Bakoe, Shamakhi) bleven de Shirvanshahs onder Mongoolse soevereiniteit als lokale dynastie bestaan; de atlas houdt deze twee punten op besluit van Emre in de kleur van de Shirvanshahs (Mongoolse/Ilkhanidische onderworpenheid in de noot).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["De Ayyubid al-Malik al-Kamil nam Âmid in", "9cebe681"], "d": ["Al-Malik al-Kamil belegerde Âmid en nam het van de Artukiden in.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Ala ad-Din Kay Qubad I nam Kütahya van het Keizerrijk Nicea", "e0b9a7f7"], "d": ["Kütahya, dat in de wanorde na 1182 opnieuw naar Byzantium was gegaan, werd in de tijd van Ala ad-Din Kay Qubad I op het Keizerrijk Nicea heroverd.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Badr ad-Din Lu'lu' sultan van Mosul", "73268628"], "d": ["Met de dood van de laatste Zengidische atabeg werd Badr ad-Din Lu'lu' door de kalief tot sultan uitgeroepen. (Rabi' al-awwal 631 / december 1233; de atlas schrijft, de registratie volgend, in jaarprecisie.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["De Seltsjoeken namen Harput in", "3b9391eb"], "d": ["Het leger van Ala ad-Din Kay Qubad nam het fort van Harput over na een belegering van vierentwintig dagen; de Artukiden van Harput kwamen ten einde.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-07-23:0":{"b": ["Ghiyath ad-Din Kay Khusraw II nam Âmid in", "c37c3b04"], "d": ["De Anatolisch-Seltsjoekse sultan Ghiyath ad-Din Kay Khusraw II nam Âmid van de Ayyubiden.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Möngke Khan stelde Iftikhar ad-Din aan als gouverneur van Qazvin", "fc650d13"], "d": ["De Grote Mongoolse Khan Möngke benoemde een gouverneur van Qazvin; de periode van de Iftikhariden begon.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Komst van Hülegü: Qazvin en Nachitsjevan kwamen onder Ilkhanidisch bestuur", "24673608"], "d": ["Met de komst van Hülegü naar Iran droeg het Mongoolse bestuur over aan de Ilkhanidische staat; Qazvin en Nachitsjevan kwamen onder Ilkhanidisch bestuur (grens van regel 5, niet de bronnendag). In Shirvan (Bakoe, Shamakhi) bracht de Mongoolse bezetting zware verwoesting maar de Shirvanshahs bleven als lokale dynastie bestaan; de atlas houdt deze twee punten in de kleur van de Shirvanshahs (besluit van Emre).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["De Mongolen bezetten Tikrit", "60af2df0"], "d": ["Tijdens de Mongoolse invasie werd Tikrit bezet en geplunderd; de stad kwam uit het Abbasidische bestuur.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hülegü trok van Hamadan naar Bagdad", "5f0c77b5"], "d": ["Hülegü vertrok vanuit Hamadan, waar zijn bagage zich bevond, op veldtocht naar Bagdad (getuigenis van de Ilkhanidische heerschappij).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Buqa Temür nam Kufa en Basra in", "dec82b4e"], "d": ["De Mongoolse troepen onder bevel van Buqa Temür namen Kufa, Wasit en Basra in.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Irak kwam in handen van de Mongolen (regionaal)", "7b990281"], "d": ["Met de inname van Bagdad door Hülegü in 1258 werd de Abbasidische staat verwoest en kwam Irak in handen van de Mongolen.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Maraş werd aan de Armeniërs overgelaten", "6161f1a5"], "d": ["Toen Imad ad-Din uit de familie van Husam ad-Din geen steun vond, liet hij Maraş over aan de Armeniërs van Cilicië.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Wasit kwam onder Ilkhanidische heerschappij", "fbdf83fc"], "d": ["Met de verovering van Irak door de Ilkhaniden kwam Wasit onder hun bestuur.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["De Mongolen namen Bagdad in; einde van het Abbasidische kalifaat", "41c34bd4"], "d": ["De Mongolen onder bevel van Hülegü vielen Bagdad aan, kalief al-Musta'sim gaf zich over; de stad kwam onder Ilkhanidische heerschappij.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["De Mongolen namen Mosul in, de dynastie van Lu'lu' kwam ten einde", "035d0121"], "d": ["Mosul van al-Malik as-Salih Isma'il, die aan de zijde van Baibars stond, onderging Mongoolse verwoesting en hijzelf werd in aanwezigheid van Hülegü gedood.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1069-10-20:0":{"b": ["De khutba van Mekka werd van de Fatimiden overgezet naar de Abbasidische kalief en sultan Alp Arslan", "df951887"], "d": ["Toen wegens hongersnood in Egypte geen voorraden meer aankwamen, liet de emir van Mekka, Abu Hashim Muhammad b. Ja'far, de khutba uitspreken op naam van de Abbasidische kalief al-Qa'im bi-Amr Allah en de Seltsjoekse sultan Alp Arslan; Mekka kwam onder de opperheerschappij van de Grote Seltsjoeken.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsiz b. Uvak nam Damascus in", "8eea047f"], "d": ["Atsiz veroverde Syrië en liet de khutba uitspreken op naam van de Abbasidische kalief en Malik-Shah.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["De emir van Mekka Abu Hashim liet de khutba opnieuw uitspreken op naam van de Fatimidische kalief", "85b6c0c0"], "d": ["Ondanks de pogingen van Malik-Shah de soennitische invloed te versterken, begon de emir van Mekka de khutba weer op naam van de Fatimiden te laten uitspreken; Mekka keerde terug onder de Fatimidische opperheerschappij.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutush trok Damascus binnen, de Seltsjoeken van Syrië werden gesticht", "b48b38be"], "d": ["Tutush trok de stad binnen en stichtte de Seltsjoekse staat van Syrië.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["De emir van Mekka verklaarde zijn trouw aan de Abbasidische kalief al-Muqtadi en sultan Malik-Shah", "38a430a5"], "d": ["De emir van Mekka onderwierp zich opnieuw aan de Abbasidische kalief en de Seltsjoekse sultan; deze trouw duurde tot de dood van Malik-Shah (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["Na de dood van sultan Malik-Shah keerde de khutba in Mekka terug naar de Fatimiden", "195a27cd"], "d": ["Toen de Seltsjoekse sultan Malik-Shah stierf, begon de emir van Mekka de khutba opnieuw op naam van de Fatimidische kalief te laten uitspreken; Mekka ging over naar de Fatimidische opperheerschappij.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Na de nederlaag bij Dorylaion keerde Eskişehir terug naar Byzantium", "3f381ee4"], "d": ["Na de terugtrekking van Kilij Arslan I voor de kruisvaarders kwam de stad opnieuw onder Byzantijns bestuur.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Tughtekin stichtte het Atabegaat van Damascus", "f26729c0"], "d": ["Na de dood van Duqaq stichtte de atabeg Tughtekin de dynastie van de Buriden.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["De Almohaden namen Meknes in", "ee976b41"], "d": ["Na lang verzet kwam de stad onder Almohadische heerschappij en werd geplunderd.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nur ad-Din Zengi nam Damascus in", "a4fd8b58"], "d": ["Nur ad-Din Mahmud bracht Damascus onder zijn heerschappij.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Het Fatimidische bestuur in Egypte kwam ten einde, de Ayyubiden kwamen aan de macht — Alexandrië, Fayoum en Mekka (Hidjaz)", "1c565534"], "d": ["Met het vizierschap van Saladin en de dood van de Fatimidische kalief al-Adid (567/1171) ging Egypte over naar de Ayyubiden; Alexandrië en Fayoum kwamen onder Ayyubidisch bestuur. De dag staat niet in de bron — overgenomen van het einde van de Fatimidische registratie (de dag van de registratie is geen bron). Ook de Hidjaz kwam onder Ayyubidisch bestuur; de opperheerschappij over Mekka ging van de Fatimiden over naar de Ayyubiden (opperheerschappijmodel van Emre #23).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Saladin nam Damascus in", "dfdb11ce"], "d": ["Na de dood van Nur ad-Din ging de stad over naar Saladin al-Ayyubi.", "a20855b8"]},
"OLAYLAR_T5_1000B:1175-07-22:0":{"b": ["De Ayyubiden namen Aden in, de Zuray'iden kwamen ten einde", "d253acf0"], "d": ["De Ayyubiden rukten op naar Aden en lieten vizier Yasir b. Bilal executeren.", "06e4a877"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Na Myriokephalon ontruimde Byzantium Dorylaion", "24aef255"], "d": ["Na de nederlaag bij Myriokephalon liet Manuel krachtens het verdrag de versterking van Dorylaion slopen en de stad ontruimen; de Turken begonnen deze plek Eskişehir te noemen.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya werd bij het Seltsjoekse grondgebied gevoegd", "cf56b964"], "d": ["Kilij Arslan II voegde de Danishmendidische gebieden (inclusief Amasya) bij het Seltsjoekse land.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["De broers Asen namen Noord-Bulgarije in; Byzantium erkende de Tweede Bulgaarse Staat", "ff0554e9"], "d": ["De broers Petar en Asen namen met Koemaanse steun Noord-Bulgarije opnieuw in; met de vrede van 1187 erkende Byzantium de Tweede Bulgaarse Staat.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Servië consolideerde zijn heerschappij in Zeta", "794c821d"], "d": ["In 1189 consolideerde Servië zijn heerschappij over Zeta (inclusief de kust van Kotor); aan Zeta werd een bijzondere status verleend.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan kocht Cyprus, Nicosia werd hoofdstad", "11017aea"], "d": ["Guy de Lusignan kocht het eiland van de Tempeliers en maakte Nicosia tot hoofdstad.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kaloyan nam Varna in", "1237fe7f"], "d": ["De Bulgaren onder tsaar Kaloyan namen in maart 1201 Varna van Byzantium; de stad bleef in de 13e-14e eeuw binnen de grenzen van de Bulgaarse staat.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nishapur werd definitief bij de Khwarazmshahs gevoegd", "fa4a6cd2"], "d": ["Ala ad-Din Muhammad b. Tekish voegde de stad definitief bij het gebied van de Khwarazmshahs.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["Het schiereiland Gallipoli kwam onder Latijns bestuur", "27308f59"], "d": ["Na de Vierde Kruistocht kwamen Gallipoli en omgeving in 1204 onder het bestuur van de Latijnen.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["Het Despotaat Epirus werd gesticht — Ioannina werd centrum, Lepanto ging naar het despotaat", "d7966877"], "d": ["Na de Vierde Kruistocht stichtte Michael Angelos het Despotaat Epirus; Ioannina werd het centrum van het despotaat, Lepanto bleef ook binnen het gebied van het despotaat.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Kreta werd aan Venetië verkocht", "f1760e84"], "d": ["Markies Bonifatius van Monferrato liet met de overeenkomst van 12 augustus 1204 Kreta voor 100.000 zilverstukken aan Venetië over.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Mansura werd gesticht", "342a6f47"], "d": ["Al-Malik al-Kamil stichtte Mansura als legerkamp tegen de kruisvaarders die Damietta bezetten.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["De Mongolen namen Nishapur in", "0e73f075"], "d": ["De stad werd door de Mongoolse invasie verwoest.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["De Rasulid Nur ad-Din Umar bracht Jemen onder zijn bestuur", "ee1ec7ab"], "d": ["Na de dood van al-Mas'ud, de laatste Ayyubid van Jemen, kwam Nur ad-Din Umar aan de macht in Jemen.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["De keizer van Nicea Vatatzes heroverde Gallipoli", "a6936e33"], "d": ["De keizer van Nicea, Ioannes III Vatatzes, heroverde Gallipoli op de Latijnen (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["De Mongolen veroverden Amasya", "783bcd0c"], "d": ["Na Köse Dağ namen de Mongolen de stad in en bestuurden de Mongoolse gouverneurs haar.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatatzes trok naar Thracië: Edirne en Thessaloniki werden bij het Keizerrijk Nicea gevoegd", "0bf61ca5"], "d": ["De heerser van Nicea, Ioannes III Vatatzes, trok in 1246 naar Thracië en nam de door de Bulgaren bezette gebieden en Thessaloniki in.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["De Rasulidische heerschappij werd in Mekka erkend — Nur ad-Din Umar viel ten offer aan een aanslag", "d7e03c21"], "d": ["Toen de Rasulidische sultan van Jemen Nur ad-Din Umar in Janad werd vermoord (februari 1250), werd de heerschappij van zijn staat erkend tussen Mekka en Hadramaut; in het jaar waarin het Ayyubidische sultanaat eindigde, verschijnt Mekka onder Rasulidische opperheerschappij.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["In Egypte werd de Mamlukse staat gesticht — Alexandrië, Mansura en Fayoum gingen naar de Mamloeken", "230c1a11"], "d": ["Na Turan Shah werd met Shajar ad-Durr en Izz ad-Din Aybak de Mamlukse macht gevestigd; de Egyptische steden (Alexandrië, Mansura, Fayoum) kwamen onder Mamlukse heerschappij. De bron geeft de troonsbestijging van Aybak als 3 juli 1250; de atlas nam de dag over van het einde van de Ayyubidische registratie (30 april 1250) — de dag van de registratie is geen bron, het verschil is gemeld.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["De Ayyubid van Aleppo an-Nasir Yusuf kwam aan de macht in Damascus", "d585985d"], "d": ["Terwijl in Egypte de Mamlukse macht werd gevestigd, nam de heerser van Aleppo, an-Nasir Yusuf, Damascus in (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jeruzalem werd bij vrede aan de Mamloeken overgelaten", "50d53fac"], "d": ["Met een vrede onder bemiddeling van de kalief werd Jeruzalem aan de Mamloeken overgelaten.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jeruzalem ging opnieuw naar de Ayyubiden", "fdeedd4a"], "d": ["Palestina en Jeruzalem kwamen opnieuw in handen van de Syrische Ayyubiden.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["De Mongolen namen Damascus in", "430bdfea"], "d": ["Tijdens de Syrische veldtocht van Hülegü ging Damascus naar de Mongolen.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Slag bij Ayn Jalut: Damascus en Jeruzalem gingen naar de Mamloeken", "40ebd7b7"], "d": ["Qutuz versloeg de Mongolen bij Ayn Jalut (25 Ramadan 658 / 3 september 1260); het grootste deel van Syrië, Damascus en Jeruzalem kwamen in handen van de Mamloeken, de Ayyubidische dynastie kwam ten einde.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Baibars herstelde het Abbasidische kalifaat in Caïro — Mekka en Medina werden aan de Mamloeken gebonden", "a5128a1e"], "d": ["Baibars riep de Abbasid Ahmad, die aan de verwoesting van Bagdad was ontkomen, in Caïro uit tot kalief en zwoer hem trouw; als beschermer van het kalifaat bond hij ook de Haramain aan de Mamlukse opperheerschappij. De dag is die van het herstel van het kalifaat; de dag van de binding van Mekka en Medina staat niet in de bron (ondergrens).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["De troepen van Nicea trokken Constantinopel binnen — het Byzantijnse Rijk werd hersteld", "81741490"], "d": ["De troepen van Nicea trokken op 25 juli 1261 Constantinopel binnen en maakten een einde aan de Latijnse heerschappij; de gebieden van de Laskaridische (Nicea) staat — Bursa, Izmir, Çimpe, Edirne, Thessaloniki — werden opnieuw het Byzantijnse Rijk. De atlas toont op deze punten de periode van het Keizerrijk Nicea vóór 1261 alleen voor de plaatsen die in de bron met naam worden genoemd.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Charles d'Anjou nam Durrës en Krujë in", "082a86b8"], "d": ["Charles uit het huis Anjou nam in 1271-1272 Durrës en Krujë in en liet het oude fort herbouwen.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["De Sicilianen bezetten het eiland Djerba", "daab5ad2"], "d": ["Het eiland Djerba werd in het jaar 683 (1284-85) door de Sicilianen bezet; eerst was het bezit van het pausdom, daarna hoorde het bij het Koninkrijk Sicilië.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Ioannina werd opnieuw bij het Byzantijnse Rijk gevoegd", "60016303"], "d": ["Ioannina, dat in de tweede helft van de 13e eeuw vele malen van hand wisselde, werd in 1318 opnieuw bij Byzantium gevoegd, maar behield tot op zekere hoogte zijn autonomie; het centrum van het Despotaat Epirus verschoof naar Arta.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["De bevolking van Djerba verdreef de Sicilianen van het eiland", "ff71985e"], "d": ["De bevolking van het eiland, die in opstand kwam tegen het slechte bestuur van de Siciliaanse gouverneurs, verdreef in 1334 de Sicilianen; Djerba kwam opnieuw onder Hafsidisch bestuur.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Charles Thopia kwam aan de macht in Krujë", "4e40583d"], "d": ["Na de dood van tsaar Dušan (1355) kwam de Albanees Charles Thopia aan de macht in Krujë.", "7af64cd2"]}
});
